window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0063", [{"word":"reliably","ipa_uk":"/rɪˈlaɪəbli/","ipa_us":"/rɪˈlaɪəbli/","definition_zh":"可靠地；稳定地；有把握地；可信地；不出差错地","definition_en":"in a way that can be trusted to give accurate, consistent, or dependable results","core_image":"校准台上摆着一排相同的砝码，每次称量，指针都停在同一格刻度上。","scene":"实验室主管让学生把同一份样品连测三次，三次读数几乎分毫不差，她这才同意把数据写进报告。The instrument reliably gave the same reading three times, so the results could be trusted in the report.","sceneCN":"这里 reliably 是“稳定可靠地得出结果”（第 1 个义项）；句意：三次读数一致，结果可信，可以写进报告。","pos":[{"tag":"adv.","zh":"可靠地；稳定地；有把握地"}],"collocations":[{"phrase":"reliably predict","zh":"可靠地预测"},{"phrase":"reliably reproduce","zh":"稳定地重现"},{"phrase":"reliably measured","zh":"可靠测量的"},{"phrase":"reliably informed","zh":"据可靠消息"},{"phrase":"reliably deliver","zh":"稳定交付"},{"phrase":"reliably identify","zh":"可靠地识别"}],"forms":[{"label":"原级（副词）","form":"reliably"},{"label":"比较级","form":"more reliably"},{"label":"最高级","form":"most reliably"},{"label":"形容词形式","form":"reliable"},{"label":"名词形式","form":"reliability"}],"derivatives":[{"word":"rely","pos":"v.","zh":"依赖；信赖"},{"word":"reliable","pos":"adj.","zh":"可靠的；可信赖的"},{"word":"reliability","pos":"n.","zh":"可靠性；可信度"},{"word":"reliance","pos":"n.","zh":"依赖；依靠"}],"senses":[{"no":"01","title":"Results you can trust","titleCN":"可靠地：结果经得起信任","definition":"in a way that produces results a person can trust without checking every step","definitionCN":"以让人无须逐步核查也能信任其结果的方式","example":"The sensor reliably reports the temperature to within half a degree.","exampleCN":"这个传感器能可靠地把温度报告到半度以内。","why":"The suffix -ly turns the adjective reliable into a manner; reliable itself comes from rely, to bind fast, so the manner described is one that does not slip.","whyCN":"后缀 -ly 把形容词 reliable 变成方式副词；reliable 出自 rely“牢牢绑住”，因此这种做事方式不会松脱走样。"},{"no":"02","title":"The same every time","titleCN":"稳定重现：每次都是同一个结果","definition":"in a way that repeats the same outcome under the same conditions","definitionCN":"在相同条件下重复得出同一结果的方式","example":"The recipe reliably produces the same crumb every time she bakes it.","exampleCN":"她每次烘烤，这个配方都稳定地做出同样的组织。","why":"Repetition is the practical test of reliability: if the outcome moves about, the method cannot be trusted, however good a single trial looks.","whyCN":"重复是可靠性的实际检验：结果若飘忽不定，方法就不可信，单次试验再漂亮也没有用。"},{"no":"03","title":"Machines that do not fail","titleCN":"不出差错地：设备与服务靠得住","definition":"with a low rate of failure, especially of machines, systems, or services","definitionCN":"故障率很低，尤指机器、系统或服务","example":"The backup generator has run reliably through three winter storms.","exampleCN":"这台备用发电机经历了三场冬季风暴，一直运行可靠。","why":"When the subject is a machine, reliability is counted in hours of service rather than in truth; -ly still marks the manner of working.","whyCN":"主语是机器时，可靠性以服务时长而不是以真假来衡量；-ly 标记的仍是运行的方式。"},{"no":"04","title":"A source worth believing","titleCN":"有把握地：消息来源可信","definition":"in a way that shows the speaker has sound grounds for what is said","definitionCN":"表现出说话者对所言有可靠依据的方式","example":"She is reliably informed that the talks will resume next month.","exampleCN":"据她可靠的消息，会谈将于下月恢复。","why":"The phrase reliably informed moves the word from things to testimony: reliability now belongs to the channel that supplies the news.","whyCN":"reliably informed 把词从“事物”移到“证言”：这里的可靠性属于提供消息的那个渠道。"},{"no":"05","title":"Measured with little error","titleCN":"精确地：测量误差很小","definition":"with a small margin of error when a value is measured or estimated","definitionCN":"测量或估计数值时误差很小","example":"Satellite data can reliably estimate the area of open water.","exampleCN":"卫星数据能可靠地估算开阔水域的面积。","why":"Accuracy is closeness to a true value; reliability is getting that closeness again and again. The adverb often carries both at once.","whyCN":"准确讲的是与真值接近，可靠讲的是能否一次次保持这种接近；这个副词常常两者兼有。"},{"no":"06","title":"Predictable in advance","titleCN":"可预期地：事先就能算准","definition":"in a way that allows an outcome to be forecast before it happens","definitionCN":"使结果能在发生之前就被预测的方式","example":"Demand for electricity reliably peaks on the hottest afternoons.","exampleCN":"用电需求可靠地在最热的下午达到高峰。","why":"A pattern that can be counted on becomes a planning tool; predictability is reliability seen from the future looking back.","whyCN":"能被指望的规律就成了规划工具；可预测性是从未来往回看的可靠性。"},{"no":"07","title":"Holding up over time","titleCN":"长期可靠地：经久不坏","definition":"continuing to work well over a long period without sudden loss of quality","definitionCN":"长时间持续良好运转，质量不突然下滑","example":"The bridge has carried traffic reliably for over eighty years.","exampleCN":"这座桥已可靠地承载交通八十余年。","why":"Durability adds a time axis: a thing may work well today yet be unreliable if it fails soon, so the adverb claims endurance.","whyCN":"耐久性加上了时间轴：某物今天好用，若不久就坏仍不可靠；这个副词主张的是持久。"},{"no":"08","title":"Safely assumed in reasoning","titleCN":"可信地：推理中可当前提","definition":"used to say that something may be taken as true in an argument","definitionCN":"用于表示在某论证中可以把某事当作真的","example":"We can reliably assume that any sample drawn this way is unbiased.","exampleCN":"我们可以可信地假定，这样抽取的样本没有偏差。","why":"In logic the adverb licenses an inference rather than describing an action; reliability means the premise will not betray the conclusion.","whyCN":"在逻辑里这个副词是给推理发放许可，而不是描述动作；可靠意味着前提不会让结论落空。"}],"etymology":{"intro":{"en":"Reliably is rely plus -able plus -ly. The Latin source is religare, to bind fast, whose participle gave the idea of something tied so that it cannot slip.","cn":"reliably 由 rely 加 -able 再加 -ly 构成。其拉丁来源是 religare“牢牢绑住”，其分词义带来“绑紧而不松脱”的观念。"},"items":[{"era":"LATIN ligare","en":"Ligare meant to tie or bind. A thing bound fast stays where it is put, and this physical image later supplies the moral idea of trust.","cn":"ligare 意为“系、绑”。绑紧的东西会留在原处，这个具体形象后来提供了“信任”这一抽象含义。"},{"era":"LATIN religare","en":"Religare strengthened the image to binding fast or tying back. Roman writers used it for obligations that hold a person to a duty.","cn":"religare 把形象加强为“绑牢、系回”。罗马作家用它指把人系在义务上的约束。"},{"era":"FRENCH relier","en":"Old French relier meant to fasten together or connect, and it carried both the physical and the binding-obligation senses.","cn":"古法语 relier 意为“把……系在一起、连接”，兼有物理捆绑与义务约束两层意思。"},{"era":"ENGLISH rely (14th c.)","en":"English rely first meant to gather or assemble, then to depend on a person or thing, since what is fastened to you is what you lean on.","cn":"英语 rely 最初指“聚集、集合”，后指“依靠人或物”，因为系在你身上的东西正是你所倚靠的。"},{"era":"ENGLISH -able","en":"The Latin suffix -abilis marked what can be done or what deserves to be done; added to rely it yields reliable, worthy of being depended on.","cn":"拉丁后缀 -abilis 标记“可以……的、值得……的”；加在 rely 上得到 reliable“值得依靠的”。"},{"era":"ENGLISH -ly","en":"The Old English adverb ending -lice became -ly. It converts the adjective into the manner of doing something, hence reliably, in a dependable manner.","cn":"古英语副词词尾 -lice 演变为 -ly，把形容词转成做事的方式，于是 reliably 就是“以可依靠的方式”。"}]},"similar":{"note":{"en":"The first group is the rely family, which shares one root; the second compares adverbs of dependability, accuracy, and consistency.","cn":"第一组是 rely 词族，共享同一词根；第二组比较表示可靠、准确、稳定的几个副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rely","ipa":"/rɪˈlaɪ/","tag":"verb","definition":"to depend on someone or something for support or truth. It names the act of leaning on a source.","definitionCN":"依靠某人或某物以获得支持或真相；命名的是倚靠这一动作。"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"adjective","definition":"deserving to be depended on. It judges a person, machine, or result, not a manner.","definitionCN":"值得依靠的；评判的是人、机器或结果，而不是做事方式。"},{"word":"reliability","ipa":"/rɪˌlaɪəˈbɪləti/","tag":"noun","definition":"the quality of being dependable, often measured by failure rate or repeatability.","definitionCN":"可靠的性质，常用故障率或可重复性来衡量。"},{"word":"reliance","ipa":"/rɪˈlaɪəns/","tag":"noun","definition":"the state of depending on something. It stresses dependence, not the quality of the depended-on thing.","definitionCN":"依赖的状态；强调依赖关系，而不是被依赖物的品质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dependably","ipa":"/dɪˈpendəbli/","tag":"adverb","definition":"in a way that can be counted on, with emphasis on personal or contractual trust.","definitionCN":"可以被指望地；强调人身上的信任或契约上的信守。"},{"word":"consistently","ipa":"/kənˈsɪstəntli/","tag":"adverb","definition":"in the same way on different occasions, with emphasis on uniformity rather than on truth.","definitionCN":"在不同场合以同样的方式；强调一致性，而不是正确性。"},{"word":"accurately","ipa":"/əˈkjʊrətli/","tag":"adverb","definition":"without error, with emphasis on closeness to a true value rather than on repeatability.","definitionCN":"没有错误地；强调与真值的接近，而不是可重复性。"},{"word":"steadily","ipa":"/ˈstedɪli/","tag":"adverb","definition":"at a regular, unbroken rate. It describes rhythm and continuity rather than trustworthiness.","definitionCN":"以规则、不间断的速度；描述节奏与连续性，而非可信程度。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: rely, -able, -ly. Nothing is added that the word does not contain.","cn":"只用真实成分：rely、-able、-ly，不额外添加词里没有的东西。"},"normal":[{"en":"Rely plus able plus ly: able to be relied on, and doing things that way.","cn":"依靠加“能够”再加副词尾：能够被依靠，并且以那种方式做事。"},{"en":"A rope tied fast does not slide; that picture is the whole of reliability.","cn":"绑紧的绳子不会滑；这幅画面就是“可靠”的全部内容。"},{"en":"Three identical readings are what let a scientist say the method works reliably.","cn":"三次读数一样，科学家才敢说这个方法稳定可靠。"},{"en":"In an engineering report, reliably means the part never dropped out of service.","cn":"在工程报告里，可靠就意味着这个零件从未掉过链子。"},{"en":"Saying reliably informed puts a guarantee on the messenger as well as the message.","cn":"说“据可靠消息”，等于把消息和传话人一起打了包票。"}],"abstract":[{"en":"Reliability is not one success but the willingness to be checked again tomorrow.","cn":"可靠不是一次成功，而是明天仍敢让别人复查。"},{"en":"Handing a task to a machine moves trust from character to calibration.","cn":"把任务交给机器，就是把信任从人品转移到刻度。"},{"en":"To call something predictable is to squeeze the future into a number that can be recomputed.","cn":"说某事可预期，就是把未来压缩成一行可以复算的数。"}]},"examples":[{"en":"The old pump reliably starts on the first try, even in freezing weather.","cn":"这台旧水泵即使在严寒中也能可靠地一次启动。"},{"en":"Studies reliably show that spaced review beats a single long cram.","cn":"研究一致表明，间隔复习胜过一次性长时间突击。"},{"en":"A witness who is reliably informed may still repeat a rumour, so the source needs checking.","cn":"消息来源可靠的人也可能转述谣言，因此来源仍需核查。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"依赖（rely）加“能够”、加副词尾——能够被依赖地做事，就是可靠地。","word":"reliably"},"root":"由 rely（信赖、依靠，源自拉丁语 religare“牢牢绑住”）加 -able（值得……的）与 -ly（副词后缀）构成，本义为“以牢靠可信、可被依靠的方式”。","sensesIntro":{"en":"Eight senses of reliably, all circling one idea: what is done this way will not let you down. The thing that holds may be a result, a machine, a source, a measurement, a forecast, a habit, or a premise.","cn":"reliably 的八个义项都围绕一个观念：以这种方式做出的事不会让你落空。靠得住的对象可以是结果、机器、消息来源、测量、预测、习惯，也可以是推理前提。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of identical weights on a calibration bench, the needle stopping at the same mark every time.","cn":"核心意象：校准台上一排相同的砝码，指针每次都停在同一格刻度。"},"chain":["LATIN LIGARE = TO BIND","LATIN RELIGARE = TO BIND FAST","ENGLISH RELY = TO DEPEND ON","SUFFIX -ABLE = WORTHY OF","RELIABLE = ABLE TO BE DEPENDED ON","RELIABLY = IN A DEPENDABLE MANNER"],"branches":[{"senses":"S1 · S4","en":"TRUST IN THE RESULT AND IN THE SOURCE: a trustworthy reading and a trustworthy messenger both remove the need for checking.","cn":"信任结果与信任来源：可信的读数和可信的传话人，都免去了逐项核查。"},{"senses":"S2 · S5","en":"REPEATABILITY AND ACCURACY: the same value time after time, and a value close to the true one.","cn":"可重复与精确：一次次得到同一个值，并且这个值贴近真值。"},{"senses":"S3 · S7","en":"ENDURANCE OF THINGS: a machine that does not fail today and a bridge that does not fail for decades.","cn":"事物的耐久：今天不出故障的机器，与几十年不出问题的桥。"},{"senses":"S6","en":"RELIABILITY SEEN FROM THE FUTURE: a pattern stable enough to plan around.","cn":"从未来看可靠性：稳定到足以据此做计划的规律。"},{"senses":"S8","en":"RELIABILITY IN ARGUMENT: a premise that will not betray the conclusion drawn from it.","cn":"论证中的可靠性：不会让由它推出的结论落空的前提。"}]},"affixes":{"intro":{"en":"Reliably is built from rely plus the adjective suffix -able and the adverb suffix -ly; the family later adds -ability for the abstract quality and un- for the opposite.","cn":"reliably 由 rely 加形容词后缀 -able 与副词后缀 -ly 构成；词族后来又用 -ability 表示抽象性质，用 un- 表示相反。"},"latinIntro":{"en":"The Latin base is ligare, to bind, strengthened in religare. The suffix -abilis belongs to Latin adjective formation, while -ly is native English.","cn":"拉丁词基是 ligare“绑”，在 religare 中加强。后缀 -abilis 属拉丁形容词构词，而 -ly 是英语本族词尾。"},"items":[{"word":"ligare","structure":"Latin verb (to bind)","meaning":"to tie or fasten","meaningCN":"系；绑；固定","example":"The Latin verb survives mainly inside compounds such as oblige and religion.","exampleCN":"这个拉丁动词主要残存在 oblige（使负有义务）、religion（宗教）等复合词里。"},{"word":"religare","structure":"re- (back, fast) + ligare (to bind)","meaning":"to bind fast, to tie back","meaningCN":"绑牢；系回","example":"Roman law spoke of obligations that religare a person to a promise.","exampleCN":"罗马法谈到把人系在承诺上的义务，就用这个动词。"},{"word":"rely","structure":"Old French relier < Latin religare","meaning":"to depend on for support or truth","meaningCN":"依靠；信赖","example":"Readers rely on the glossary when the text turns technical.","exampleCN":"文本变得专业时，读者会依靠术语表。"},{"word":"reliable","structure":"rely + -able (worthy of, able to be)","meaning":"deserving to be depended on","meaningCN":"可靠的；值得依赖的","example":"The clinic needs a reliable supply of clean water.","exampleCN":"诊所需要可靠的洁净水供应。"},{"word":"reliability","structure":"reliable + -ity (quality)","meaning":"the quality of being dependable","meaningCN":"可靠性；可信度","example":"Engineers test reliability by running the unit for thousands of hours.","exampleCN":"工程师通过让设备运行数千小时来测试可靠性。"},{"word":"reliance","structure":"rely + -ance (state or act)","meaning":"dependence on someone or something","meaningCN":"依赖；依靠","example":"The village's reliance on one well made every drought a crisis.","exampleCN":"全村依赖一口井，使每次干旱都成了危机。"},{"word":"reliably","structure":"reliable + -ly (manner adverb)","meaning":"in a dependable manner","meaningCN":"可靠地；稳定地","example":"The ferry reliably crosses the strait twice a day.","exampleCN":"渡轮每天可靠地穿越海峡两次。"},{"word":"unreliable","structure":"un- (not) + reliable","meaning":"not able to be depended on","meaningCN":"不可靠的","example":"An unreliable narrator makes the reader doubt every fact.","exampleCN":"不可靠的叙述者让读者怀疑每一个事实。"},{"word":"self-reliant","structure":"self + reliant (rely + -ant)","meaning":"able to act without depending on others","meaningCN":"自力更生的；自主的","example":"The course aims to make students self-reliant in research.","exampleCN":"这门课旨在让学生在研究中能够自立。"}],"latinEntries":[{"word":"ligare","structure":"Latin verb, first conjugation","meaning":"to bind, tie, fasten","meaningCN":"绑；系；固定"},{"word":"religare","structure":"re- + ligare","meaning":"to bind fast, tie back","meaningCN":"绑牢；系回"},{"word":"-abilis","structure":"Latin adjective suffix","meaning":"able to be, worthy of being","meaningCN":"可以……的；值得……的"}]}},{"word":"representation","ipa_uk":"/ˌreprɪzenˈteɪʃn/","ipa_us":"/ˌreprɪzenˈteɪʃən/","definition_zh":"表现；代表；象征形象；陈述；代理；表示；代表性","definition_en":"the act of standing for something else, whether by depicting it, symbolizing it, speaking for it, or encoding it","core_image":"一间展厅里，一只木雕鸽子站在和平条约的展柜旁，观众从它身上读出整场战争。","scene":"博物馆讲解员指着展柜说，这只木雕鸽子不是普通的鸟，而是和平的象征形象，它替一个抽象概念出场。The carved wooden dove is a representation of peace, standing in for an abstract idea.","sceneCN":"这里 representation 是“象征形象”（第 3 个义项）；句意：鸽子是一种象征，用来代表和平这一抽象概念。","pos":[{"tag":"n.","zh":"表现；代表；象征；陈述；代理；表示"}],"collocations":[{"phrase":"a representation of","zh":"对……的表现／描绘"},{"phrase":"visual representation","zh":"视觉呈现"},{"phrase":"legal representation","zh":"法律代理"},{"phrase":"fair representation","zh":"公平代表性"},{"phrase":"make representations to","zh":"向……提出陈述"},{"phrase":"binary representation","zh":"二进制表示"}],"forms":[{"label":"单数","form":"representation"},{"label":"复数","form":"representations"},{"label":"动词形式","form":"represent"},{"label":"形容词形式","form":"representational"}],"derivatives":[{"word":"represent","pos":"v.","zh":"代表；描绘；象征"},{"word":"representative","pos":"adj./n.","zh":"有代表性的；代表"},{"word":"representational","pos":"adj.","zh":"具象的；表征的"},{"word":"misrepresentation","pos":"n.","zh":"失实陈述；歪曲"}],"senses":[{"no":"01","title":"The act of depicting","titleCN":"表现：把事物以某种方式呈现","definition":"the act of showing or describing something in a particular way, especially in art or language","definitionCN":"以特定方式展示或描述某事物，尤指在艺术或语言中","example":"The painting is a striking representation of a storm at sea.","exampleCN":"这幅画是对海上风暴的惊人表现。","why":"Representation here names the activity of standing in for something else; the Latin root means making present again what is absent.","whyCN":"这里的 representation 命名的是“替另一物出场”的活动；拉丁词根本义是把不在场之物重新带到眼前。"},{"no":"02","title":"Speaking for a group","titleCN":"代表：替群体发声","definition":"the act of speaking or acting officially for a group or constituency","definitionCN":"正式为某个群体或选区发声或行事","example":"The union demanded fair representation on the company board.","exampleCN":"工会要求在董事会中有公平的代表权。","why":"When one person stands for many, presence is transferred: the delegate makes the group present in a room it cannot fill itself.","whyCN":"当一个人代替许多人出场，在场性就转移了：代表让群体出现在它自己无法进入的房间。"},{"no":"03","title":"An image or symbol","titleCN":"象征形象：用作象征的图像","definition":"an image, model, or symbol that stands for something else","definitionCN":"用来代表另一事物的图像、模型或符号","example":"The dove is a common representation of peace.","exampleCN":"鸽子是和平常见的象征形象。","why":"A symbol does not copy its object, it replaces it; representation covers both faithful pictures and conventional signs.","whyCN":"象征并不复制对象，而是替代对象；representation 同时涵盖忠实的图像与约定俗成的符号。"},{"no":"04","title":"A formal statement of facts","titleCN":"陈述：向权威正式说明","definition":"a formal statement made to an authority, setting out facts or complaints","definitionCN":"向权威机构作出的正式说明，陈述事实或提出申诉","example":"The residents made representations to the council about the noise.","exampleCN":"居民就噪声问题向议会作了陈述。","why":"In law and administration the word shifts from picture to plea: what is presented is an account offered for someone to act upon.","whyCN":"在法律与行政语境里，词义从“图像”转为“陈情”：被呈上的是供他人据以行动的说法。"},{"no":"05","title":"A performance on stage","titleCN":"演绎：舞台上的呈现","definition":"a performance of a play or an interpretation of a role","definitionCN":"戏剧的演出，或对某个角色的诠释","example":"Her representation of the queen was cold and calculating.","exampleCN":"她对女王的演绎冷峻而精于算计。","why":"A performance presents a character to an audience, so the same word that covers pictures also covers staged presence.","whyCN":"演出把一个人物呈现给观众，因此覆盖图像的那个词也覆盖舞台上的在场。"},{"no":"06","title":"Legal standing for a client","titleCN":"代理：律师替当事人出庭","definition":"the state of being represented by a lawyer in legal proceedings","definitionCN":"在法律程序中由律师代为出面的状态","example":"The defendant asked for legal representation before the hearing.","exampleCN":"被告在听证前要求获得律师代理。","why":"Legal representation is the institutional form of sense two: the lawyer's presence counts as the client's presence in court.","whyCN":"法律代理是第二义项的制度化形式：律师的出庭被算作当事人在法庭上的在场。"},{"no":"07","title":"How data is encoded","titleCN":"表示：信息的编码形式","definition":"a particular way of storing or expressing information, as in a graph or a code","definitionCN":"存储或表达信息的特定方式，如用图表或编码","example":"The same number has different representations in binary and decimal.","exampleCN":"同一个数在二进制与十进制中有不同的表示。","why":"Once information is abstracted, any faithful encoding can stand in for it; representation then becomes a technical choice of format.","whyCN":"信息一旦被抽象出来，任何忠实的编码都能替它出场；表示由此变成格式上的技术选择。"},{"no":"08","title":"Fair reflection of a group","titleCN":"代表性：群体被如实反映","definition":"the extent to which a group is accurately reflected in a body, sample, or account","definitionCN":"某个群体在机构、样本或叙述中被如实反映的程度","example":"The survey was criticized for its poor representation of rural voters.","exampleCN":"这项调查因对农村选民代表性不足而受到批评。","why":"Here the word measures a mirror: the question is not who speaks but whether the whole has been reproduced in miniature.","whyCN":"这里衡量的是镜面效果：问题不在于谁在说话，而在于整体是否被缩小后如实复制。"}],"etymology":{"intro":{"en":"Representation is represent plus -ation. The base goes back to Latin repraesentare, to make present, built on praesens, being before the eyes.","cn":"representation 由 represent 加 -ation 构成。词基可追溯到拉丁语 repraesentare“使在场”，其构词基于 praesens“在眼前存在”。"},"items":[{"era":"LATIN esse","en":"Esse, to be, is the deepest layer. A present thing is literally something that is before one, available to the senses.","cn":"esse“存在”是最深的一层。在场之物字面上就是“在某人面前存在、可被感官触及”之物。"},{"era":"LATIN praesens","en":"Praesens joins prae-, before, with the participle of esse: being before someone, hence present and at hand.","cn":"praesens 由 prae-“在前”与 esse 的分词组合：在某人面前存在，因而“在场、在手边”。"},{"era":"LATIN repraesentare","en":"Repraesentare meant to bring something before the eyes or mind, to make absent things present again.","cn":"repraesentare 意为把某物带到眼前或心头，使不在场之物重新在场。"},{"era":"FRENCH representer","en":"Old French representer passed the verb into English with the senses of exhibiting, depicting, and standing for another.","cn":"古法语 representer 把该动词传入英语，义为展示、描绘以及替他人出场。"},{"era":"ENGLISH represent","en":"English represent covers depicting, symbolizing, and acting in another's place: three ways of making something present.","cn":"英语 represent 涵盖描绘、象征与代他人行事，都是使某物在场的三种方式。"},{"era":"ENGLISH -ation","en":"The Latin suffix -ationem named an action or its result; added here it yields the act or product of making something present.","cn":"拉丁后缀 -ationem 命名动作或其结果；加在这里得到“使某物在场的动作或产物”。"}]},"similar":{"note":{"en":"The first group is the represent family, separated by grammatical role; the second compares words for pictures, accounts, and likenesses.","cn":"第一组是 represent 词族，按语法角色区分；第二组比较表示图画、叙述与相似之物的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"represent","ipa":"/rɪˈprezənt/","tag":"verb","definition":"to depict, symbolize, or act for another. It names the act itself.","definitionCN":"描绘、象征或代他人行事；命名的是动作本身。"},{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","tag":"adjective or noun","definition":"typical of a larger group, or a person who acts for others. It describes or names the stand-in.","definitionCN":"能代表整体的典型，或代他人行事的人；描述或命名的是替代者。"},{"word":"representational","ipa":"/ˌreprɪzenˈteɪʃənl/","tag":"adjective","definition":"showing recognizable objects, as opposed to abstract art. It labels a style.","definitionCN":"描绘可辨认对象的，与抽象艺术相对；标记的是一种风格。"},{"word":"representation","ipa":"/ˌreprɪzenˈteɪʃn/","tag":"noun","definition":"the act or result of standing for something. It can also mean a formal complaint or a coded form of data.","definitionCN":"替某物出场的行为或结果；也可指正式申诉或数据的编码形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"depiction","ipa":"/dɪˈpɪkʃn/","tag":"noun","definition":"a picture or description of something. It stays close to visual or verbal rendering.","definitionCN":"对某物的图画或描述；始终贴近视觉或语言的再现。"},{"word":"portrayal","ipa":"/pɔːˈtreɪəl/","tag":"noun","definition":"the way a person or situation is shown in art or writing, often with emphasis on characterization.","definitionCN":"艺术或文字中呈现人物、情境的方式，常强调性格刻画。"},{"word":"symbol","ipa":"/ˈsɪmbl/","tag":"noun","definition":"a sign that stands for an idea by convention rather than by resemblance.","definitionCN":"按约定而不是按相似性代表某个观念的符号。"},{"word":"account","ipa":"/əˈkaʊnt/","tag":"noun","definition":"a spoken or written report of an event. It stresses narration and explanation.","definitionCN":"对事件的口头或书面报告；强调叙述与解释。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: represent plus -ation. The verb already contains the idea of making present, so the noun is the making present of something.","cn":"只用真实成分：represent 加 -ation。动词里已经含“使在场”的意思，因此名词就是“使某物在场这件事”。"},"normal":[{"en":"Present again: representation puts before your eyes something that is not there.","cn":"重新在场：representation 把不在眼前的东西放到你眼前。"},{"en":"A delegate is a representation of people who cannot all fit in the room.","cn":"代表是那些挤不进房间的人的一种 representation。"},{"en":"A graph is a representation of data, not the data itself.","cn":"图表是数据的 representation，而不是数据本身。"},{"en":"A lawyer provides legal representation: the client appears through the lawyer.","cn":"律师提供法律代理：当事人通过律师出场。"},{"en":"A formal letter to the council is also called a representation, an account laid before authority.","cn":"写给议会的正式信函也叫 representation，是摆在权威面前的说法。"}],"abstract":[{"en":"Every representation is a choice: something is always left out of the frame.","cn":"每一种再现都是选择：画框之外总有什么被留下。"},{"en":"To represent a group is to risk speaking with authority you were not given.","cn":"代表一个群体，就要冒用以未被授予的权威说话的风险。"},{"en":"A perfect representation would be a copy; a useful one is a compression.","cn":"完美的再现会是一份复制品；有用的再现则是一种压缩。"}]},"examples":[{"en":"The map is a flattened representation of a curved surface, so distances near the poles stretch.","cn":"地图是对曲面的压平表示，因此靠近两极的距离会被拉长。"},{"en":"Women's representation in the assembly rose from twelve to thirty percent in a decade.","cn":"女性在议会中的代表性十年间从百分之十二升到百分之三十。"},{"en":"The court agreed that his lawyer's representation had been inadequate.","cn":"法院认定他的律师代理不够充分。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（重新）+ present（呈现）——把不在场的东西重新呈到眼前，就是“表现、代表”。","word":"representation"},"root":"由 represent（呈现、代表）加 -ation（名词后缀）构成；represent 源自拉丁语 repraesentare“使在场”，其词基 praesens 由 prae-“在前”与 esse“存在”组成，本义为“使不在场之物重新在场”。","sensesIntro":{"en":"Eight senses of representation, all circling one idea: something stands in for something else. The stand-in may be a picture, a delegate, a symbol, a formal statement, a performance, a lawyer, a code, or a sample.","cn":"representation 的八个义项都围绕一个观念：某物替另一物出场。这个替代者可以是图画、代表、符号、正式陈述、演出、律师、编码或样本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a carved dove beside a peace treaty in a display case, read by visitors as the whole war.","cn":"核心意象：展柜里一只木雕鸽子立在和平条约旁，观众从它身上读出整场战争。"},"chain":["LATIN ESSE = TO BE","LATIN PRAESENS = BEING BEFORE","LATIN REPRAESENTARE = TO MAKE PRESENT","ENGLISH REPRESENT = TO STAND FOR","SUFFIX -ATION = ACT OR RESULT","REPRESENTATION = MAKING SOMETHING PRESENT"],"branches":[{"senses":"S1 · S3","en":"PICTURE AND SYMBOL: a faithful image and a conventional sign are two ways of putting an absent thing before the eye.","cn":"图像与符号：忠实的图像与约定的符号，都是把不在场之物放到眼前的方式。"},{"senses":"S2 · S6","en":"SPEAKING FOR OTHERS: a delegate in an assembly and a lawyer in court both make an absent party present.","cn":"替他人出场：议会里的代表与法庭上的律师，都让不在场的一方到场。"},{"senses":"S4","en":"A FORMAL ACCOUNT LAID BEFORE AUTHORITY: facts offered so that someone may act on them.","cn":"呈给权威的正式陈述：提供事实，供他人据以行动。"},{"senses":"S5","en":"STAGED PRESENCE: a performance gives the audience a character who is not in the room.","cn":"舞台上的在场：演出让观众看到一个并不在房间里的人物。"},{"senses":"S7 · S8","en":"ENCODING AND REFLECTION: data expressed in a format, and a group reproduced in miniature.","cn":"编码与映照：用某种格式表达数据，以及在缩小尺度上复制一个群体。"}]},"affixes":{"intro":{"en":"Representation is represent plus -ation; the verb itself is re- plus present. The family spreads across verb, person, style, and abstract noun.","cn":"representation 由 represent 加 -ation 构成，动词本身又是 re- 加 present。词族分布在动词、人物、风格与抽象名词上。"},"latinIntro":{"en":"The Latin layers are esse and praesens, then repraesentare. The -ation suffix comes from Latin -ationem, which names an action or its result.","cn":"拉丁层次依次是 esse 与 praesens，再到 repraesentare。后缀 -ation 出自拉丁语 -ationem，命名动作或其结果。"},"items":[{"word":"praesens","structure":"prae- (before) + esse (to be)","meaning":"being before one, present","meaningCN":"在某人面前存在的；在场的","example":"The Latin participle is the source of the English word present.","exampleCN":"这个拉丁分词是英语 present 的来源。"},{"word":"repraesentare","structure":"re- (again) + praesentare (to present)","meaning":"to bring before the eyes or mind","meaningCN":"带到眼前或心头；使呈现","example":"Roman orators spoke of repraesentare a scene to the listener.","exampleCN":"罗马演说家谈到把场景呈现在听众眼前，就用这个动词。"},{"word":"represent","structure":"re- + present, through French representer","meaning":"to depict, symbolize, or act for another","meaningCN":"描绘；象征；代表","example":"The dots on the map represent cities above ten thousand people.","exampleCN":"地图上的点代表人口过万的城市。"},{"word":"representation","structure":"represent + -ation (action or result)","meaning":"the act or result of standing for something","meaningCN":"替某物出场的行为或结果","example":"The sculpture is a representation of the river rather than the river itself.","exampleCN":"这座雕塑是对河流的表现，而不是河流本身。"},{"word":"representative","structure":"represent + -ative (tending to, serving as)","meaning":"typical of a group, or a person who acts for a group","meaningCN":"有代表性的；代表","example":"Each district sends one representative to the assembly.","exampleCN":"每个选区派一名代表进入议会。"},{"word":"representational","structure":"representation + -al (relating to)","meaning":"depicting recognizable objects rather than abstractions","meaningCN":"描绘可辨认对象的；具象的","example":"The gallery keeps its representational paintings on the ground floor.","exampleCN":"美术馆把具象绘画放在一层展厅。"},{"word":"misrepresentation","structure":"mis- (wrongly) + representation","meaning":"a misleading account of facts","meaningCN":"失实陈述；歪曲","example":"The company was fined for misrepresentation in its advertising.","exampleCN":"该公司因广告失实陈述被罚款。"},{"word":"representable","structure":"represent + -able (can be)","meaning":"able to be depicted or expressed","meaningCN":"可被表现或表示的","example":"Some feelings are barely representable in words.","exampleCN":"有些感受几乎无法用语言表现。"}],"latinEntries":[{"word":"esse","structure":"Latin verb, irregular","meaning":"to be, to exist","meaningCN":"存在；是"},{"word":"praesens","structure":"prae- + esse participle","meaning":"present, at hand","meaningCN":"在场的；在手边的"},{"word":"repraesentare","structure":"re- + praesentare","meaning":"to make present, to show","meaningCN":"使在场；呈现"}]}},{"word":"representative","ipa_uk":"/ˌreprɪˈzentətɪv/","ipa_us":"/ˌreprɪˈzentətɪv/","definition_zh":"代表；代理人；有代表性的；典型的；代议制的；具象的；议员","definition_en":"a person who acts or speaks for others, or something that is typical of a larger whole","core_image":"一间社区礼堂里，一位居民把邻居们的签名册摊在会议桌上，替没能到场的人说话。","scene":"社区会议上，这位居民代表拿着整条街的签名册起身发言，替没能到场的邻居表达意见。He acted as a representative for the neighbours who could not attend and spoke on their behalf.","sceneCN":"这里 representative 是“受托替他人出面的代表”（第 1 个义项）；句意：他替没有到场的居民发言。","pos":[{"tag":"n.","zh":"代表；代理人；议员"},{"tag":"adj.","zh":"有代表性的；典型的；代议制的"}],"collocations":[{"phrase":"a representative sample","zh":"代表性样本"},{"phrase":"sales representative","zh":"销售代表"},{"phrase":"representative government","zh":"代议制政府"},{"phrase":"trade representative","zh":"贸易代表"},{"phrase":"broadly representative","zh":"具有广泛代表性的"},{"phrase":"elected representative","zh":"民选代表"}],"forms":[{"label":"单数","form":"representative"},{"label":"复数","form":"representatives"},{"label":"比较级","form":"more representative"},{"label":"最高级","form":"most representative"},{"label":"副词形式","form":"representatively"}],"derivatives":[{"word":"represent","pos":"v.","zh":"代表；描绘"},{"word":"representation","pos":"n.","zh":"代表；表现"},{"word":"representativeness","pos":"n.","zh":"代表性"},{"word":"representatively","pos":"adv.","zh":"有代表性地"}],"senses":[{"no":"01","title":"Someone who acts for others","titleCN":"代表：受托替他人出面的人","definition":"a person chosen to speak or act on behalf of a group","definitionCN":"被选出代表某个群体发言或行事的人","example":"Each department sent a representative to the budget meeting.","exampleCN":"每个部门都派了一名代表参加预算会议。","why":"The word adds -ative to represent: the suffix marks the person who carries out the standing-for that the verb names.","whyCN":"这个词在 represent 后加 -ative：该后缀标记的是执行“替他人出场”这一动作的人。"},{"no":"02","title":"A typical example","titleCN":"典型样本：能代表整体的样本","definition":"a thing that is typical of a larger set and can stand for it in study","definitionCN":"能代表更大整体、可在研究中替代整体的样本","example":"The survey drew a representative sample of two thousand households.","exampleCN":"这项调查抽取了两千户的代表性样本。","why":"A sample is representative when its proportions match the whole; the person sense is reused for a statistical stand-in.","whyCN":"样本的比例与整体相符时才具代表性；这里把“人”的义项挪用到统计上的替代物。"},{"no":"03","title":"Government by delegates","titleCN":"代议制的：由代表议事","definition":"describing a system in which elected delegates make decisions for the people","definitionCN":"描述由民选代表代人民做决定的制度","example":"The country moved toward representative government in the nineteenth century.","exampleCN":"这个国家在十九世纪走向代议制政府。","why":"Here the adjective describes a whole system: decisions are made by stand-ins rather than by assembled citizens.","whyCN":"这里的形容词描述一整套制度：决定由代表做出，而不是由全体公民集会做出。"},{"no":"04","title":"Typical of a group","titleCN":"有代表性的：体现群体特征","definition":"showing the usual qualities of a group or category","definitionCN":"显示某群体或类别通常具有的特征","example":"Her experience is representative of many first-year teachers.","exampleCN":"她的经历对许多第一年任教的教师来说很有代表性。","why":"A single case becomes representative by matching a pattern; the claim is about typicality, not about delegation.","whyCN":"单个案例通过吻合某种模式而变得有代表性；这里主张的是典型性，而不是授权。"},{"no":"05","title":"A sales agent","titleCN":"销售代理：公司派驻的业务人员","definition":"an employee who promotes and sells a company's products in a territory","definitionCN":"在某个区域内推广并销售公司产品的雇员","example":"The pharmaceutical representative explained the dosage to the clinic.","exampleCN":"医药代表向诊所解释了剂量。","why":"A company cannot be everywhere, so it sends someone who carries its voice; representative adds commercial agency to the political sense.","whyCN":"公司无法无处不在，于是派一个带着公司声音的人；representative 在政治义之外加上了商业代理义。"},{"no":"06","title":"Art that shows recognizable things","titleCN":"具象的：描绘可辨认对象","definition":"depicting recognizable objects or scenes rather than pure form and colour","definitionCN":"描绘可辨认的物体或场景，而不是纯粹的形式与色彩","example":"The museum's representative works hang beside its abstract canvases.","exampleCN":"博物馆的具象作品挂在抽象画作旁边。","why":"Representative art makes an object present through its likeness; the adjective marks the mode of depiction.","whyCN":"具象艺术通过相似性让对象在场；这个形容词标记的是描绘方式。"},{"no":"07","title":"A symbolic stand-in","titleCN":"象征代表：以符号身份出场","definition":"something that stands for a larger idea or movement","definitionCN":"代表更大观念或运动的事物","example":"The oak became representative of the whole campaign.","exampleCN":"这棵橡树成了整场运动的象征代表。","why":"A symbol can be representative without being elected or typical; it is chosen to carry a meaning.","whyCN":"象征可以是代表，却既非选出也非典型；它是被选中来承载某种意义的。"},{"no":"08","title":"A member of a legislature","titleCN":"议员：立法机构中的代表","definition":"a member of a law-making body, especially in the United States Congress","definitionCN":"立法机构的成员，尤指美国国会","example":"The representative voted against the bill after hearing from her district.","exampleCN":"这位议员在听取本选区意见后对法案投了反对票。","why":"The title is the institutional shortening of sense one: an elected member whose seat stands for a district.","whyCN":"这一头衔是第 1 个义项的制度化简称：民选议员的席位代表一个选区。"}],"etymology":{"intro":{"en":"Representative is represent plus -ative, a Latin adjective ending that later also names persons. The base is repraesentare, to make present.","cn":"representative 由 represent 加 -ative 构成；该拉丁形容词词尾后来也用来指人。词基是 repraesentare“使在场”。"},"items":[{"era":"LATIN praesens","en":"Praesens means being before someone, formed from prae-, before, and the participle of esse, to be.","cn":"praesens 意为“在某人面前存在”，由 prae-“在前”与 esse“存在”的分词构成。"},{"era":"LATIN repraesentare","en":"The verb meant to bring a thing before the eyes or mind. In public life it came to mean putting a person or body before an assembly.","cn":"该动词意为把事物带到眼前或心头。在公共生活中，它逐渐指把某人或某机构呈到议会面前。"},{"era":"FRENCH representer","en":"Old French carried the verb to English with the added sense of acting in another's place.","cn":"古法语把该动词带入英语，并加上了“代他人行事”的意思。"},{"era":"LATIN -ativus","en":"The suffix -ativus formed adjectives meaning tending to do or serving to do; with represent it names what serves to stand for something.","cn":"后缀 -ativus 构成表示“倾向于做、用于做”的形容词；与 represent 结合后指“用于替某物出场的”。"},{"era":"ENGLISH representative (17th c.)","en":"The word first described things that symbolize or stand for others, then persons sent to speak for a body, and finally members of parliaments.","cn":"这个词先描述象征或代表他物的事物，后指被派替某团体发言的人，最终指议会成员。"}]},"similar":{"note":{"en":"The first group contrasts grammatical roles inside the represent family; the second compares words for people and things that stand for a whole.","cn":"第一组对照 represent 词族内部的语法角色；第二组比较表示“代表整体”的人或物的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"represent","ipa":"/rɪˈprezənt/","tag":"verb","definition":"to act or speak for another, or to depict something. It is the action, not the actor.","definitionCN":"代他人行事或发言，或描绘某物；是动作，不是施动者。"},{"word":"representation","ipa":"/ˌreprɪzenˈteɪʃn/","tag":"noun","definition":"the act or result of standing for something, including pictures, symbols, and formal statements.","definitionCN":"替某物出场的行为或结果，包括图画、符号与正式陈述。"},{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","tag":"noun or adjective","definition":"a person who stands for a group, or a thing typical of a larger set.","definitionCN":"替群体出场的人，或能代表更大整体的典型事物。"},{"word":"representativeness","ipa":"/ˌreprɪˈzentətɪvnəs/","tag":"noun","definition":"the degree to which a sample or body reflects the whole it is drawn from.","definitionCN":"样本或机构反映其来源整体的程度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"delegate","ipa":"/ˈdelɪɡət/","tag":"person noun","definition":"a person sent with authority to act for others at a meeting. It stresses appointment and instructions.","definitionCN":"被派往会议、获授权替他人行事的人；强调任命与授权。"},{"word":"spokesperson","ipa":"/ˈspəʊkspɜːsn/","tag":"person noun","definition":"someone who speaks publicly for a group. The emphasis is on voice rather than on decision.","definitionCN":"公开为群体发声的人；强调发声，而非做决定。"},{"word":"typical","ipa":"/ˈtɪpɪkl/","tag":"adjective","definition":"showing the usual features of a group or kind. It describes a pattern, not a mandate.","definitionCN":"显示某群体或类别通常特征的；描述模式，而非授权。"},{"word":"emblematic","ipa":"/ˌembləˈmætɪk/","tag":"adjective","definition":"serving as a symbol of a larger idea. It stresses symbolic meaning rather than statistical fit.","definitionCN":"作为更大观念的象征的；强调象征意义，而非统计上的吻合。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: represent plus -ative. The suffix builds an adjective, and English later used the same form for the person who does the representing.","cn":"只用真实成分：represent 加 -ative。该后缀先构成形容词，英语后来又把同一形式用作执行代表的人。"},"normal":[{"en":"The ending -ative turns the act of standing for others into a person or a quality.","cn":"词尾 -ative 把“替他人出场”这一动作变成人或性质。"},{"en":"A representative carries a district in a single seat.","cn":"一名代表用一个席位承载一个选区。"},{"en":"A representative sample is a crowd shrunk until it fits in a test tube.","cn":"代表性样本就是缩小到能装进试管的整个人群。"},{"en":"A sales representative is the company's voice with legs.","cn":"销售代表就是长了腿的公司声音。"},{"en":"Representative art shows a cow you can recognize, not a theory of colour.","cn":"具象艺术画的是一头你认得出的牛，而不是色彩理论。"}],"abstract":[{"en":"Representation always borrows authority: the stand-in speaks with a power that was lent, not owned.","cn":"代表总要借取权威：替代者用的是被借来的权力，而不是自己的权力。"},{"en":"A sample can be representative and still hide the exception that matters most.","cn":"样本可以很有代表性，却仍藏起最要紧的那个例外。"},{"en":"The more typical a thing looks, the harder it is to notice what it leaves out.","cn":"某物看起来越典型，就越难察觉它省略了什么。"}]},"examples":[{"en":"The union's representative sat down with management and brought a list of shop-floor complaints.","cn":"工会代表与管理层坐下来谈判，带来一摞车间投诉。"},{"en":"Because the panel was not representative, its conclusions could not be applied to the whole city.","cn":"由于该小组不具代表性，其结论无法推广到全城。"},{"en":"She is a representative writer of the period: restrained, ironic, and deeply political.","cn":"她是那个时期的代表性作家：克制、反讽，且极具政治性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（反复）+ present（呈上）+ ative（人）——反复替你呈上意见的那个人，就是代表。","word":"representative"},"root":"由 represent（呈现、代表）加 -ative（有……倾向、起……作用）构成；represent 源自拉丁语 repraesentare“使在场”，词基为 praesens“在场的”，本义为“替某物或某人出场者”。","sensesIntro":{"en":"Eight senses of representative, all circling one idea: one thing answers for a larger whole. The stand-in may be a person, a sample, a system, a style, a symbol, or a seat in a legislature.","cn":"representative 的八个义项都围绕一个观念：一物替更大的整体作答。替代者可以是人、样本、制度、风格、符号，也可以是一个立法席位。"},"semanticMap":{"core":{"en":"CORE IMAGE: a resident holding a petition signed by the whole street, speaking in a hall where the neighbours cannot all sit.","cn":"核心意象：一位居民捧着整条街签名的请愿册，在邻居们挤不进去的礼堂里发言。"},"chain":["LATIN PRAE- = BEFORE","LATIN ESSE = TO BE","LATIN REPRAESENTARE = TO MAKE PRESENT","SUFFIX -ATIVUS = SERVING TO","REPRESENTATIVE = SERVING TO STAND FOR","ONE WHO OR THAT WHICH ANSWERS FOR A WHOLE"],"branches":[{"senses":"S1 · S8","en":"ELECTED VOICE: a delegate in a meeting and a member of Congress both hold a seat that stands for others.","cn":"选出的声音：会议上的代表与国会议员，都持有一个替他人出场的席位。"},{"senses":"S2 · S4","en":"TYPICALITY: a sample whose proportions match the whole, and a single case that matches the group's pattern.","cn":"典型性：比例吻合整体的样本，以及吻合群体模式的单个案例。"},{"senses":"S3","en":"A WHOLE SYSTEM OF STAND-INS: government in which delegates decide for citizens.","cn":"整套替代制度：由代表代公民做决定的政府形式。"},{"senses":"S5","en":"COMMERCIAL AGENCY: a sales agent carries a company's voice into distant places.","cn":"商业代理：销售代表把公司的声音带到远方。"},{"senses":"S6 · S7","en":"SYMBOLIC AND VISUAL STAND-INS: recognizable pictures and chosen emblems that carry a meaning.","cn":"符号与视觉替身：可辨认的图画与被选定的徽记，都承载某种意义。"}]},"affixes":{"intro":{"en":"Representative is represent plus -ative. The family runs from the verb through the act, the person, the style, and the abstract quality.","cn":"representative 由 represent 加 -ative 构成。词族从动词延伸到动作、人物、风格与抽象性质。"},"latinIntro":{"en":"Latin supplies praesens and repraesentare; -ativus is a Latin adjective suffix. The English word later shifted from adjective to person noun.","cn":"拉丁语提供了 praesens 与 repraesentare；-ativus 是拉丁形容词后缀。英语中这个词后来从形容词转为指人的名词。"},"items":[{"word":"represent","structure":"re- + present < Latin repraesentare","meaning":"to act or speak for another, or to depict","meaningCN":"代表；替他人行事或发言；描绘","example":"Two students represent the school at the regional debate.","exampleCN":"两名学生代表学校参加地区辩论赛。"},{"word":"representation","structure":"represent + -ation (action or result)","meaning":"the act or result of standing for something","meaningCN":"代表的行为或结果；表现","example":"Proportional representation gives small parties a share of seats.","exampleCN":"比例代表制让小党也分到席位。"},{"word":"representative","structure":"represent + -ative (serving to)","meaning":"a stand-in person, or something typical of a whole","meaningCN":"代表；有代表性的","example":"Ask a representative of the tenants to sign the agreement.","exampleCN":"请租户代表来签这份协议。"},{"word":"representatively","structure":"representative + -ly (manner adverb)","meaning":"in a way that reflects the whole","meaningCN":"有代表性地","example":"The committee was representatively composed of town and country members.","exampleCN":"委员会的构成兼具城镇与乡村成员，具有代表性。"},{"word":"representativeness","structure":"representative + -ness (quality)","meaning":"the degree of reflecting the whole","meaningCN":"代表性程度","example":"Statisticians argue about the representativeness of online polls.","exampleCN":"统计学家争论网络民调的代表性。"},{"word":"misrepresent","structure":"mis- (wrongly) + represent","meaning":"to give a false account of someone or something","meaningCN":"歪曲；不如实地代表","example":"The advertisement misrepresented the size of the apartment.","exampleCN":"广告歪曲了公寓的面积。"},{"word":"representational","structure":"representation + -al (relating to)","meaning":"depicting recognizable objects","meaningCN":"具象的；描绘可辨认对象的","example":"Representational painting returned to fashion in the 1980s.","exampleCN":"具象绘画在二十世纪八十年代重新流行。"},{"word":"unrepresentative","structure":"un- (not) + representative","meaning":"not typical of the larger group","meaningCN":"不具代表性的","example":"The complaints came from an unrepresentative handful of users.","exampleCN":"这些投诉来自不具代表性的一小撮用户。"}],"latinEntries":[{"word":"praesens","structure":"prae- + esse participle","meaning":"present, at hand","meaningCN":"在场的；在手边的"},{"word":"repraesentare","structure":"re- + praesentare","meaning":"to make present, to show","meaningCN":"使在场；呈现"},{"word":"-ativus","structure":"Latin adjective suffix","meaning":"serving to, tending to","meaningCN":"用于……的；倾向于……的"}]}},{"word":"reproduction","ipa_uk":"/ˌriːprəˈdʌkʃn/","ipa_us":"/ˌriːprəˈdʌkʃən/","definition_zh":"繁殖；复制品；再生产；再现；声音还原；翻印","definition_en":"the process of producing new individuals or new copies of something already made","core_image":"温室里，一株母株旁边并排长出三株一模一样的小苗，每片叶子的纹路都相同。","scene":"园艺师指着温室里的三株小苗说，它们都是从同一株母本繁殖出来的，叶形和花纹完全一样。These three seedlings are reproductions of a single parent plant, with exactly the same leaves.","sceneCN":"这里 reproduction 是“生物的繁殖”（第 1 个义项）；句意：这三株小苗由同一母本繁殖而来。","pos":[{"tag":"n.","zh":"繁殖；复制；复制品；再生产；再现"}],"collocations":[{"phrase":"asexual reproduction","zh":"无性繁殖"},{"phrase":"a reproduction of","zh":"……的复制品"},{"phrase":"sound reproduction","zh":"声音还原"},{"phrase":"reproduction rate","zh":"繁殖率"},{"phrase":"social reproduction","zh":"社会关系的再生产"},{"phrase":"colour reproduction","zh":"色彩还原"}],"forms":[{"label":"单数","form":"reproduction"},{"label":"复数","form":"reproductions"},{"label":"动词形式","form":"reproduce"},{"label":"形容词形式","form":"reproductive"},{"label":"形容词形式（可复制的）","form":"reproducible"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"繁殖；复制；再现"},{"word":"reproductive","pos":"adj.","zh":"生殖的；复制的"},{"word":"reproducible","pos":"adj.","zh":"可复制的；可重现的"},{"word":"reproducibility","pos":"n.","zh":"可重复性；可复现性"}],"senses":[{"no":"01","title":"Making new living things","titleCN":"繁殖：生物产生后代","definition":"the biological process by which organisms produce new individuals of their own kind","definitionCN":"生物产生同类新个体的生物学过程","example":"Fungi can spread by asexual reproduction alone.","exampleCN":"真菌可以仅靠无性繁殖扩散。","why":"The prefix re- means again and production means bringing forth; a species brings forth its kind again, so the same form returns in a new body.","whyCN":"前缀 re- 表示“再一次”，production 表示“产出”；物种把自己的种类再一次产出，同一形制在新个体身上重现。"},{"no":"02","title":"A copy of a work","titleCN":"复制品：仿照原件做出的成品","definition":"a copy of a painting, document, or object, often made later and worth less than the original","definitionCN":"对绘画、文件或器物的仿制，通常晚于原件且价值较低","example":"The museum displays a reproduction of the tablet, not the original.","exampleCN":"博物馆展出的是那块泥板的复制品，而非原件。","why":"A copy brings the object forth again in another material; re- marks the second coming, and the copy is openly secondary.","whyCN":"复制品用另一种材料把器物再一次产出；re- 标记第二次出现，而复制品本身就公开地处于次要地位。"},{"no":"03","title":"Rebuilding capital and labour","titleCN":"再生产：经济体系把自身条件重新造出","definition":"the process by which an economy renews the capital, labour, and social relations it needs to continue","definitionCN":"经济体系重新造出延续自身所需的资本、劳动力与社会关系的过程","example":"Marx argued that the wage relation secures the reproduction of labour power.","exampleCN":"马克思主张，工资关系保证了劳动力的再生产。","why":"In economics the object reproduced is not a thing but the conditions of production; the system produces the means of producing again.","whyCN":"在经济学中，被再生产的不是某件物品，而是生产条件本身；体系产出的是“再次生产的手段”。"},{"no":"04","title":"Bringing a scene back","titleCN":"再现：把声音、画面或情境重放出来","definition":"the act of recreating a sound, image, or situation so that it can be experienced again","definitionCN":"把声音、图像或情境重新造出，使人能再次体验","example":"The recording gives a faithful reproduction of the concert hall's acoustics.","exampleCN":"这段录音忠实再现了音乐厅的声学效果。","why":"Here the thing reproduced is an experience rather than an object; fidelity is judged by how little the listener notices the medium.","whyCN":"这里复制的是体验而不是物件；还原的忠実程度，取决于听众多不容易察觉媒介的存在。"},{"no":"05","title":"How well sound or colour comes back","titleCN":"还原度：音响与色彩的再现质量","definition":"the quality with which a recording or display recreates sound or colour","definitionCN":"录音或显示设备重现声音或色彩的质量","example":"Cheap speakers give poor reproduction of low notes.","exampleCN":"廉价音箱对低音的还原很差。","why":"The word shifts from the act to the standard of the result: a system has good reproduction when little of the original is lost.","whyCN":"词义从动作转到结果的标准：当原物损失很少时，系统就有良好的还原度。"},{"no":"06","title":"Breeding behaviour","titleCN":"生殖活动：求偶、产卵与育幼","definition":"the behaviour and timing by which animals or plants breed","definitionCN":"动物或植物繁殖的行为与时间安排","example":"Day length triggers reproduction in many temperate birds.","exampleCN":"日照长度触发许多温带鸟类的生殖活动。","why":"Reproduction as a countable, seasonal event is the biological process seen from the calendar rather than from the cell.","whyCN":"作为可按季节计数的事件，这一义项是从日历而不是从细胞层面看繁殖过程。"},{"no":"07","title":"Copying documents","titleCN":"翻印：文件与图像的机械复制","definition":"the mechanical copying of documents, images, or recordings","definitionCN":"对文件、图像或录音的机械复制","example":"The archive restricts reproduction of fragile manuscripts.","exampleCN":"档案馆限制对易损手稿的翻印。","why":"Printing and photography detached copying from the hand; reproduction then names an industrial service rather than a likeness made by an artist.","whyCN":"印刷与摄影把手工复制与原件分离；reproduction 由此指一种工业服务，而不是艺术家的仿作。"},{"no":"08","title":"Passing inequality along","titleCN":"社会再生产：把不平等传给下一代","definition":"in sociology, the way families and schools transmit advantage and disadvantage across generations","definitionCN":"社会学中指家庭与学校把优势与劣势跨代传递的方式","example":"The study examines the reproduction of class differences through schooling.","exampleCN":"这项研究考察阶级差异如何通过学校教育被再生产。","why":"Society reproduces itself by reproducing its divisions; nothing is copied deliberately, yet the pattern returns.","whyCN":"社会通过再生产自身的分层来延续自身；没有人刻意复制，格局却照样重现。"}],"etymology":{"intro":{"en":"Reproduction is re- plus production. Production goes back to Latin producere, to lead forth, from pro-, forward, and ducere, to lead.","cn":"reproduction 是 re- 加 production。production 可追溯到拉丁语 producere“引出、带出”，由 pro-“向前”与 ducere“引导”构成。"},"items":[{"era":"LATIN ducere","en":"Ducere meant to lead or draw. Nearly every English word in this family carries the image of something being led out into view.","cn":"ducere 意为“引导、牵引”。这一词族的英语词几乎都带着“把某物引出到眼前”的形象。"},{"era":"LATIN producere","en":"Producere joined pro-, forward, with ducere: to lead or bring forth, as a plant brings forth a shoot.","cn":"producere 由 pro-“向前”与 ducere 组合：引出、带出，如同植物长出枝条。"},{"era":"LATIN productio","en":"Productio named a lengthening or a bringing forth; the noun kept the sense of extending something out from a source.","cn":"productio 指拉长或引出；这个名词保留了“从源头把某物延伸出来”的意思。"},{"era":"ENGLISH produce / production","en":"English production first meant the act of bringing forth goods, plays, or arguments; the thing produced is secondary to the act.","cn":"英语 production 最初指产出货物、演出戏剧或提出论据的行为；被产出之物相对于动作是次要的。"},{"era":"ENGLISH re-","en":"The prefix re- means back or again. Added to production it marks a second bringing forth, whether of offspring or of copies.","cn":"前缀 re- 表示“回、再”。加在 production 上就标记第二次产出，无论产出的是后代还是复制品。"},{"era":"ENGLISH reproduction (18th c.)","en":"Reproduction is recorded in the 18th century for the generation of new organisms, and soon after for copies of artworks and printed matter.","cn":"reproduction 的书面记录见于 18 世纪，指新个体的产生；不久后又指艺术品与印刷品的复制品。"}]},"similar":{"note":{"en":"The first group shares the produce root but differs in grammatical role; the second compares words for copies and for breeding.","cn":"第一组共享 produce 词根，但语法角色不同；第二组比较表示复制与繁殖的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"verb","definition":"to produce offspring or make a copy. It names the action.","definitionCN":"繁殖或复制；命名的是动作。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"noun","definition":"the process or result of producing again, whether offspring or copies.","definitionCN":"再次产出的过程或结果，可以是后代，也可以是复制品。"},{"word":"reproductive","ipa":"/ˌriːprəˈdʌktɪv/","tag":"adjective","definition":"relating to breeding or to copying. It describes what serves reproduction.","definitionCN":"与繁殖或复制有关的；描述服务于繁殖或复制的事物。"},{"word":"reproducible","ipa":"/ˌriːprəˈdjuːsəbl/","tag":"adjective","definition":"able to be made again, especially of an experiment. It judges repeatability.","definitionCN":"能够被再次做出的，尤指实验；评判的是可重复性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"copy","ipa":"/ˈkɒpi/","tag":"noun","definition":"an imitation of an original. It is the everyday word and carries no scientific sense.","definitionCN":"对原件的仿制；是日常用词，不含科学含义。"},{"word":"duplicate","ipa":"/ˈdjuːplɪkət/","tag":"noun","definition":"an exact second version made for practical use, such as a spare key.","definitionCN":"为实用目的做出的完全相同的第二份，如备用钥匙。"},{"word":"breeding","ipa":"/ˈbriːdɪŋ/","tag":"noun","definition":"the controlled production of animals or plants by humans. It stresses human management.","definitionCN":"人类对动植物繁殖的控制；强调人为管理。"},{"word":"replication","ipa":"/ˌreplɪˈkeɪʃn/","tag":"noun","definition":"the copying of a process or molecule, especially in science. It stresses exact repetition of a mechanism.","definitionCN":"过程或分子的复制，尤用于科学；强调机制的精确重复。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re-, production. Production comes from Latin producere, to lead forth, so reproduction is leading forth again.","cn":"只用真实成分：re- 与 production。production 出自拉丁语 producere“引出”，所以 reproduction 就是“再一次引出”。"},"normal":[{"en":"Re plus production: bring the same thing forth a second time.","cn":"re 加 production：把同样的东西第二次产出。"},{"en":"A rabbit reproducing is a species bringing itself forth again.","cn":"兔子繁殖，就是一个物种把自己再一次产出。"},{"en":"A museum reproduction is an honest second body for an object that must stay safe.","cn":"博物馆复制品是替必须妥善保存的原件做出的诚实的第二个身体。"},{"en":"Good speakers have good reproduction: little of the original sound is lost.","cn":"好音箱的还原度好：原声损失很少。"},{"en":"Photocopying a manuscript is reproduction in the office, not in the greenhouse.","cn":"复印手稿是办公室里的复制，不是温室里的繁殖。"}],"abstract":[{"en":"Every copy is a claim about what mattered in the original.","cn":"每一件复制品都是关于“原件里什么才重要”的一次主张。"},{"en":"A society reproduces itself most quietly when nobody notices the pattern returning.","cn":"社会最安静地再生产自身的时刻，是没人注意到旧格局又回来的时候。"},{"en":"Reproduction without variation would end adaptation; copying always carries small errors.","cn":"没有变异的复制会终止适应；复制总带着微小的错误。"}]},"examples":[{"en":"Bacteria reproduce by splitting, so a single cell can found a colony in hours.","cn":"细菌靠分裂繁殖，一个细胞数小时内就能建立菌落。"},{"en":"The gallery sells reproductions of the frescoes to protect the originals from flash photography.","cn":"美术馆出售壁画复制品，以保护原件不受闪光灯损害。"},{"en":"The paper failed to report enough detail for reproduction of the experiment.","cn":"这篇论文未报告足够细节，实验无法被重复。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（再）+ production（生产）——再生一次，既可指生后代，也可指复制品。","word":"reproduction"},"root":"由 re-（再、重新）加 production（产出，源自拉丁语 producere“引出”，由 pro-“向前”与 ducere“引导”构成）组合而成，本义为“把同一事物再一次产出”。","sensesIntro":{"en":"Eight senses of reproduction, all circling one idea: the same form comes back. What returns may be an organism, a copy, a set of economic conditions, a sound, colour fidelity, a seasonal brood, a printed page, or a social pattern.","cn":"reproduction 的八个义项都围绕一个观念：同一形制再次出现。回来的可以是生物个体、复制品、经济条件、声音、色彩还原、季节性繁殖、印刷页面，也可以是社会格局。"},"semanticMap":{"core":{"en":"CORE IMAGE: three identical seedlings beside the mother plant in a greenhouse, every leaf vein matching.","cn":"核心意象：温室里母株旁并排三株一模一样的小苗，叶脉纹路全都相同。"},"chain":["LATIN DUCERE = TO LEAD","LATIN PRODUCERE = TO LEAD FORTH","LATIN PRODUCTIO = A BRINGING FORTH","ENGLISH PRODUCTION = THE ACT OF MAKING","PREFIX RE- = AGAIN","REPRODUCTION = BRINGING FORTH AGAIN"],"branches":[{"senses":"S1 · S6","en":"LIVING REPRODUCTION: the making of new individuals and the seasonal behaviour that times it.","cn":"生命繁衍：新个体的产生，以及为之定时序的生殖活动。"},{"senses":"S2 · S7","en":"COPIES OF THINGS: an art reproduction and a photocopied document, both openly second-hand.","cn":"物品的复制：艺术复制品与复印文件，都公开地是二手之物。"},{"senses":"S3 · S8","en":"SYSTEMS REPRODUCING THEMSELVES: capital and labour renewed, and social divisions passed on.","cn":"体系自我延续：资本与劳动力的更新，以及社会分层的传递。"},{"senses":"S4","en":"AN EXPERIENCE BROUGHT BACK: a recorded scene that a listener can enter again.","cn":"体验的再现：被记录的场面，让听者得以再次进入。"},{"senses":"S5","en":"FIDELITY AS A STANDARD: the measured quality of sound or colour returned.","cn":"作为标准的还原度：声音或色彩被送回时的可测质量。"}]},"affixes":{"intro":{"en":"Reproduction is re- plus production. The family includes the verb reproduce and the adjectives reproductive and reproducible, with -tion, -ive, and -ible doing different work.","cn":"reproduction 是 re- 加 production。词族包括动词 reproduce 以及形容词 reproductive 与 reproducible，其中 -tion、-ive、-ible 各司其职。"},"latinIntro":{"en":"The Latin base is ducere, with producere and productio above it. The prefix re- is Latin and the -tion suffix reaches English through French.","cn":"拉丁词基是 ducere，其上是 producere 与 productio。前缀 re- 来自拉丁语，后缀 -tion 经法语进入英语。"},"items":[{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead, draw, or guide","meaningCN":"引导；牵引；带领","example":"The same root appears in duct, reduce, and conduct.","exampleCN":"同一词根出现在 duct（管道）、reduce（减少）、conduct（引导）等词中。"},{"word":"producere","structure":"pro- (forward) + ducere (to lead)","meaning":"to lead or bring forth","meaningCN":"引出；带出；产出","example":"The Latin verb could describe a tree putting out new growth.","exampleCN":"这个拉丁动词可以描述树木长出新枝。"},{"word":"produce","structure":"Latin producere through English verb formation","meaning":"to make, grow, or bring into being","meaningCN":"生产；生长；产生","example":"The region produces most of the country's rice.","exampleCN":"该国大部分稻米产自这个地区。"},{"word":"production","structure":"produce + -tion (action or result)","meaning":"the act of making goods or works","meaningCN":"生产；制作","example":"Steel production fell for a second year.","exampleCN":"钢产量连续第二年下降。"},{"word":"reproduce","structure":"re- (again) + produce","meaning":"to breed, or to make a copy","meaningCN":"繁殖；复制","example":"Some lizards reproduce without males.","exampleCN":"有些蜥蜴无需雄性即可繁殖。"},{"word":"reproduction","structure":"re- + production","meaning":"the process or result of producing again","meaningCN":"繁殖；复制；再生产","example":"The archive keeps a reproduction of every fragile map.","exampleCN":"档案馆为每张易损地图保存一份复制品。"},{"word":"reproductive","structure":"reproduce + -ive (tending to)","meaning":"relating to breeding or copying","meaningCN":"生殖的；复制的","example":"The frog's reproductive cycle depends on seasonal rain.","exampleCN":"这种蛙的生殖周期取决于季节性降雨。"},{"word":"reproducible","structure":"reproduce + -ible (able to be)","meaning":"able to be made again or copied","meaningCN":"可复制的；可重现的","example":"A reproducible result is the minimum standard in experimental science.","exampleCN":"可重现的结果是实验科学的最低标准。"},{"word":"reproducibility","structure":"reproducible + -ity (quality)","meaning":"the quality of being repeatable","meaningCN":"可重复性；可复现性","example":"The journal now asks authors for a reproducibility statement.","exampleCN":"该期刊现在要求作者提交可复现性声明。"}],"latinEntries":[{"word":"ducere","structure":"Latin verb","meaning":"to lead, draw","meaningCN":"引导；牵引"},{"word":"producere","structure":"pro- + ducere","meaning":"to lead forth, bring out","meaningCN":"引出；带出"},{"word":"productio","structure":"Latin noun from producere","meaning":"a lengthening, a bringing forth","meaningCN":"拉长；产出"}]}},{"word":"reproductive","ipa_uk":"/ˌriːprəˈdʌktɪv/","ipa_us":"/ˌriːprəˈdʌktɪv/","definition_zh":"生殖的；繁殖的；生殖系统的；复制的；还原的；再生产性的","definition_en":"relating to the production of offspring, or to the copying and playback of something already made","core_image":"解剖图上的鱼腹被轻轻揭开，一排细小的卵粒沿腹腔排成两列，等着被排出体外。","scene":"生物课上，老师指着鱼腹解剖图里成串的卵粒说，这些器官的唯一任务是保证后代产生。These organs serve a reproductive function: they exist to produce the next generation.","sceneCN":"这里 reproductive 是“与生殖有关的”（第 1 个义项）；句意：这些器官专门服务于繁殖。","pos":[{"tag":"adj.","zh":"生殖的；繁殖的；复制的；再生产的"}],"collocations":[{"phrase":"reproductive system","zh":"生殖系统"},{"phrase":"reproductive health","zh":"生殖健康"},{"phrase":"reproductive cycle","zh":"生殖周期"},{"phrase":"reproductive rights","zh":"生育权"},{"phrase":"reproductive labour","zh":"再生产劳动"},{"phrase":"reproductive technology","zh":"生殖技术"}],"forms":[{"label":"原级（形容词）","form":"reproductive"},{"label":"比较级（用 more）","form":"more reproductive"},{"label":"最高级（用 most）","form":"most reproductive"},{"label":"名词形式","form":"reproduction"},{"label":"副词形式","form":"reproductively"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"繁殖；复制"},{"word":"reproduction","pos":"n.","zh":"繁殖；复制品"},{"word":"reproductively","pos":"adv.","zh":"在生殖方面"},{"word":"reproductiveness","pos":"n.","zh":"生殖力；繁殖能力"}],"senses":[{"no":"01","title":"To do with breeding","titleCN":"生殖的：与产生后代有关","definition":"relating to the biological production of offspring","definitionCN":"与生物产生后代有关的","example":"Warmer water shortens the reproductive season of many fish.","exampleCN":"水温升高会缩短许多鱼类的生殖季。","why":"The adjective adds -ive to reproduce: what is reproductive is what tends to bring the kind forth again.","whyCN":"这个形容词在 reproduce 后加 -ive：凡是倾向于把同类再次产出的，就是 reproductive。"},{"no":"02","title":"The organs involved","titleCN":"生殖系统的：身体里负责繁殖的器官","definition":"belonging to the organs and structures used in breeding","definitionCN":"属于繁殖所用的器官与结构","example":"The drug can damage the reproductive organs of young fish.","exampleCN":"这种药物会损害幼鱼的生殖器官。","why":"An organ is called reproductive by its function, not its tissue; the adjective sorts body parts by the job they serve.","whyCN":"器官因功能而非组织类型被称为 reproductive；这个形容词按所司之职给身体部位分类。"},{"no":"03","title":"Capable of breeding","titleCN":"有繁殖能力的：到了能生育的阶段","definition":"mature enough or healthy enough to produce young","definitionCN":"成熟或健康到足以产生后代","example":"Only reproductive adults carry the bright breeding plumage.","exampleCN":"只有具备繁殖能力的成鸟才长有鲜艳的婚羽。","why":"Here the adjective marks a stage of life: an individual becomes reproductive when its body can complete the cycle.","whyCN":"这里标记的是生命阶段：当身体能完成整个周期时，个体才成为有繁殖能力的。"},{"no":"04","title":"To do with copying","titleCN":"复制的：与翻制、翻印有关","definition":"relating to the mechanical copying of images, documents, or recordings","definitionCN":"与图像、文件或录音的机械复制有关的","example":"The library's reproductive services are limited to out-of-copyright works.","exampleCN":"图书馆的复制服务只限版权过期的作品。","why":"The same suffix covers making a second object; what is reproductive here serves duplication rather than breeding.","whyCN":"同一后缀也覆盖“制造第二个物件”；这里服务于复制，而不是生育。"},{"no":"05","title":"Judged by fidelity","titleCN":"还原的：以保真度衡量的","definition":"describing equipment or processes measured by how faithfully they recreate sound or colour","definitionCN":"描述以还原声音或色彩的忠实度来衡量的设备或过程","example":"Reproductive accuracy matters more than loudness in a concert hall.","exampleCN":"在音乐厅里，还原的准确比音量更重要。","why":"Fidelity is the standard by which a copy is judged; the adjective names whatever is assessed on that standard.","whyCN":"保真度是评判复制品的标准；这个形容词命名的是按该标准受评判的对象。"},{"no":"06","title":"Work that renews workers","titleCN":"再生产性的：维持劳动力所需的劳动","definition":"in economics and social theory, describing unpaid work that sustains and renews people able to work","definitionCN":"经济学与社会理论中，描述维持并更新劳动人口的无偿劳动","example":"Cooking and caregiving are forms of reproductive labour.","exampleCN":"做饭与照护属于再生产劳动。","why":"Such work does not make goods; it remakes the worker, so the label borrows the biological image of renewing a kind.","whyCN":"这类劳动不制造商品，而是重新造出劳动者，因此这个标签借用了“更新同类”的生物学意象。"},{"no":"07","title":"Health and rights around birth","titleCN":"生殖健康与生育权：围绕生育的公共议题","definition":"used in phrases about access to fertility care, contraception, and related rights","definitionCN":"用于指生育照护、避孕及相关权利的短语中","example":"Reproductive health services were expanded in rural clinics.","exampleCN":"农村诊所的生殖健康服务得到扩展。","why":"The adjective becomes a policy label: it gathers medical, legal, and social questions under the single fact of reproduction.","whyCN":"这个形容词变成了政策标签：它把医学、法律与社会问题都收拢到“繁殖”这一事实之下。"},{"no":"08","title":"Repeatable by design","titleCN":"可复现的：能被别人照样做一遍","definition":"describing a method or result that another person can repeat exactly","definitionCN":"描述他人能够完全照样重复的方法或结果","example":"The protocol was designed to be reproductive across laboratories.","exampleCN":"该实验规程被设计成可在各实验室复现。","why":"Science calls a study reproductive when its outcome returns in other hands; repeatability is treated as the mark of a real effect.","whyCN":"当结果在别人手里重现时，科学界就说这项研究可复现；可重复性被视为真实效应的标志。"}],"etymology":{"intro":{"en":"Reproductive is reproduce plus -ive. Reproduce is re- plus produce, from Latin producere, to lead forth, built on ducere, to lead.","cn":"reproductive 由 reproduce 加 -ive 构成。reproduce 是 re- 加 produce，后者出自拉丁语 producere“引出”，其词基为 ducere“引导”。"},"items":[{"era":"LATIN ducere","en":"Ducere meant to lead or draw along; the image is of something being drawn out of a source.","cn":"ducere 意为“引导、牵引”；其形象是把某物从源头拉出来。"},{"era":"LATIN producere","en":"Producere put pro-, forward, before ducere, giving the sense of bringing something out into view or into existence.","cn":"producere 把 pro-“向前”放在 ducere 前，表示把某物带到眼前或带入存在。"},{"era":"ENGLISH produce","en":"The English verb kept the outward sense of yielding goods, crops, or effects.","cn":"英语动词保留了“产出货物、作物或效果”这一向外生长的含义。"},{"era":"ENGLISH re- + produce","en":"Adding re- makes the yielding a second one: a species yields its own kind again, or a workshop yields a copy.","cn":"加上 re- 就使产出成为第二次产出：物种再次产出同类，或作坊产出复制品。"},{"era":"LATIN -ivus","en":"The suffix -ivus formed adjectives meaning tending towards or serving for an action; it points to the function rather than the act.","cn":"后缀 -ivus 构成表示“倾向于、用于某动作”的形容词；它指向功能而非动作本身。"},{"era":"ENGLISH reproductive (18th c.)","en":"Reproductive first described organs and processes of breeding, and was later extended to copying and to repeatable methods.","cn":"reproductive 最初描述繁殖的器官与过程，后来扩展到复制以及可重复的方法。"}]},"similar":{"note":{"en":"The first group shares the produce root with different endings; the second compares words about breeding, copying, and repeatability.","cn":"第一组共享 produce 词根而词尾不同；第二组比较关于繁殖、复制与可重复性的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"verb","definition":"to breed or copy. It is the action that the adjective describes.","definitionCN":"繁殖或复制；是形容词所描述的那个动作。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"noun","definition":"the process or result of producing again. It names the event or the copy.","definitionCN":"再次产出的过程或结果；命名的是事件或复制品。"},{"word":"reproductive","ipa":"/ˌriːprəˈdʌktɪv/","tag":"adjective","definition":"relating to breeding, copying, or repeatability.","definitionCN":"与繁殖、复制或可重复性有关的。"},{"word":"productive","ipa":"/prəˈdʌktɪv/","tag":"adjective","definition":"yielding a good amount of results. It lacks re- and so says nothing about a second round.","definitionCN":"产出效果多的；没有 re-，因此不涉及第二轮。"}]},{"heading":"NEAR MEANING","entries":[{"word":"generative","ipa":"/ˈdʒenərətɪv/","tag":"adjective","definition":"having the power to produce or originate new things, especially in language or art.","definitionCN":"具有产生或创造新事物的能力，尤用于语言或艺术。"},{"word":"breeding","ipa":"/ˈbriːdɪŋ/","tag":"adjective or noun","definition":"relating to the controlled mating of animals. It stresses human management of reproduction.","definitionCN":"与动物受控交配有关；强调人对繁殖的管理。"},{"word":"duplicative","ipa":"/ˈdjuːplɪkətɪv/","tag":"adjective","definition":"tending to make an exact second copy. It stresses sameness rather than biological renewal.","definitionCN":"倾向于做出完全相同的第二份；强调同一性而非生命更新。"},{"word":"repeatable","ipa":"/rɪˈpiːtəbl/","tag":"adjective","definition":"able to be done or obtained again by the same or another person.","definitionCN":"能够被同样的人或他人再次做出或得到的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re-, produce, -ive. The suffix makes an adjective of function, so reproductive describes what serves the bringing forth again.","cn":"只用真实成分：re-、produce、-ive。该后缀构成表功能的形容词，因此 reproductive 描述的是服务于“再次产出”的事物。"},"normal":[{"en":"Re plus produce plus ive: the adjective of things that serve a second bringing forth.","cn":"re 加 produce 加 ive：服务于第二次产出的形容词。"},{"en":"Reproductive organs exist for one job: making the next generation.","cn":"生殖器官只为一件差事存在：造出下一代。"},{"en":"A reproductive adult is one whose body can complete the cycle.","cn":"有繁殖能力的成体，就是身体能跑完整个周期的个体。"},{"en":"Unpaid cooking and caregiving is reproductive labour: it remakes the worker.","cn":"无偿的做饭与照护是再生产劳动：它重新造出劳动者。"},{"en":"A reproductive experiment is one that still works when someone else repeats it.","cn":"可复现的实验，就是换个人重做仍然成立的实验。"}],"abstract":[{"en":"Calling work reproductive quietly asks who is expected to renew the renewers.","cn":"把某种劳动称为“再生产”，其实是在问：谁又来更新那些更新者。"},{"en":"An organ is named by its function, so the body is read as a set of purposes.","cn":"器官按功能命名，身体因此被读成一组目的。"},{"en":"Repeatability is trust in science made procedural.","cn":"可重复性是科学信任被程序化后的样子。"}]},"examples":[{"en":"The reproductive cycle of the eel takes it from river to ocean and back.","cn":"鳗鲡的生殖周期让它从河流到海洋，再返回河流。"},{"en":"Reproductive health clinics reported a sharp rise in visits after the campaign.","cn":"宣传活动之后，生殖健康诊所的就诊人数大幅上升。"},{"en":"The team published a reproductive protocol so other labs could copy the result.","cn":"团队公布了可复现的实验规程，让其他实验室能复制该结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（再）+ product（产品）+ ive——能再产生一次产品的，就是生殖的、复制的。","word":"reproductive"},"root":"由 reproduce（繁殖、复制）加 -ive（倾向于、用于……的）构成；reproduce 为 re-（再）加 produce（产出，源自拉丁语 producere“引出”，词基 ducere“引导”），本义为“用于再次产出同类的”。","sensesIntro":{"en":"Eight senses of reproductive, all circling one idea: what serves the return of the same form. The service may be breeding, an organ, a mature body, copying, fidelity, unpaid renewal work, health policy, or repeatable method.","cn":"reproductive 的八个义项都围绕一个观念：服务于同一形制的再次出现。这种服务可以是繁殖、器官、成熟个体、复制、保真、无偿的更新劳动、健康政策，或可重复的方法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fish dissection chart, two rows of eggs along the belly, every organ pointed at the next generation.","cn":"核心意象：一张鱼类解剖图，腹腔两侧排着卵粒，每个器官都指向下一代。"},"chain":["LATIN DUCERE = TO LEAD","LATIN PRODUCERE = TO LEAD FORTH","ENGLISH PRODUCE = TO YIELD","PREFIX RE- = AGAIN","REPRODUCE = TO YIELD AGAIN","REPRODUCTIVE = SERVING THE SECOND YIELD"],"branches":[{"senses":"S1 · S2 · S3","en":"BODILY BREEDING: the process, the organs, and the mature state that makes it possible.","cn":"身体层面的繁衍：过程、器官，以及使之可能的成熟状态。"},{"senses":"S4 · S5","en":"COPYING AND FIDELITY: mechanical reproduction and the measured faithfulness of the copy.","cn":"复制与保真：机械复制，以及复制品被测量的忠实度。"},{"senses":"S6","en":"SOCIAL RENEWAL: unpaid work that remakes the people who work.","cn":"社会性更新：重新造出劳动者本人的无偿劳动。"},{"senses":"S7","en":"PUBLIC POLICY: health, contraception, and rights gathered under one adjective.","cn":"公共政策：健康、避孕与权利被收拢在同一个形容词下。"},{"senses":"S8","en":"METHOD: a study counts as reproductive when other hands can repeat it.","cn":"方法：当别人的手能重复时，一项研究才算可复现。"}]},"affixes":{"intro":{"en":"Reproductive joins re-, produce, and -ive. The same pieces also build reproduce, reproduction, and reproducible, each ending marking a different grammatical job.","cn":"reproductive 由 re-、produce 与 -ive 组合。同样的成分也构成 reproduce、reproduction 与 reproducible，各词尾标记不同的语法任务。"},"latinIntro":{"en":"The Latin base is ducere, extended in producere. The -ive ending comes from Latin -ivus, shared with a large family of English adjectives.","cn":"拉丁词基是 ducere，在 producere 中扩展。-ive 词尾出自拉丁语 -ivus，与英语中大批形容词共享。"},"items":[{"word":"produce","structure":"Latin producere (to lead forth)","meaning":"to yield, make, or bring into being","meaningCN":"产出；制造；使产生","example":"The orchard produces pears even in poor soil.","exampleCN":"这片果园即使在贫瘠土壤里也产梨。"},{"word":"reproduce","structure":"re- (again) + produce","meaning":"to breed or make a copy","meaningCN":"繁殖；复制","example":"The pattern reproduces itself in every generation of the fabric.","exampleCN":"这一图案在每一代织物上都会复制自身。"},{"word":"reproduction","structure":"re- + production (-tion: action or result)","meaning":"breeding, copying, or renewal of conditions","meaningCN":"繁殖；复制；条件再生产","example":"The lab keeps a reproduction of the original slide.","exampleCN":"实验室保存着原始玻片的复制品。"},{"word":"reproductive","structure":"reproduce + -ive (serving or tending to)","meaning":"relating to breeding or to copying","meaningCN":"生殖的；复制的","example":"Reproductive success depends on finding a mate in time.","exampleCN":"繁殖成功取决于及时找到配偶。"},{"word":"reproduced","structure":"reproduce + -ed (past participle)","meaning":"having been bred or copied","meaningCN":"已被繁殖或复制的","example":"The image reproduced here is half the size of the original.","exampleCN":"此处复制的图像尺寸只有原件的一半。"},{"word":"reproductively","structure":"reproductive + -ly (manner adverb)","meaning":"in terms of breeding or copying","meaningCN":"在生殖或复制方面","example":"The two species are reproductively isolated by timing.","exampleCN":"这两个物种因繁殖时间不同而生殖隔离。"},{"word":"reproducible","structure":"reproduce + -ible (able to be)","meaning":"able to be repeated or copied","meaningCN":"可重复的；可复制的","example":"The experiment is reproducible with ordinary glassware.","exampleCN":"这个实验用普通玻璃器皿即可重复。"},{"word":"reproducibility","structure":"reproducible + -ity (quality)","meaning":"the quality of being repeatable","meaningCN":"可重复性","example":"Poor reproducibility has damaged trust in the field.","exampleCN":"可重复性差已损害了该领域的信任。"},{"word":"non-reproductive","structure":"non- (not) + reproductive","meaning":"not involved in breeding, as of worker bees","meaningCN":"不参与繁殖的，如工蜂","example":"Non-reproductive workers defend the colony instead.","exampleCN":"不繁殖的工蜂转而保卫群体。"}],"latinEntries":[{"word":"ducere","structure":"Latin verb","meaning":"to lead, draw","meaningCN":"引导；牵引"},{"word":"producere","structure":"pro- + ducere","meaning":"to lead forth, bring out","meaningCN":"引出；带出"},{"word":"-ivus","structure":"Latin adjective suffix","meaning":"tending to, serving to","meaningCN":"倾向于……的；用于……的"}]}},{"word":"researcher","ipa_uk":"/rɪˈsɜːtʃə(r)/","ipa_us":"/rɪˈsɜːrtʃər/","definition_zh":"研究者；科研人员；调查者；调研员；学术研究者","definition_en":"a person whose job is to study a subject carefully in order to discover new facts or reach a judgement","core_image":"深夜的档案室里，一个人把三十年前的借阅卡一张张摊开，用铅笔在笔记本上画出时间线。","scene":"出版社编辑等这位作者交稿等了两年，因为他把每一份旧报纸都翻过一遍，才敢写下那一段历史。A careful researcher, he read every old newspaper before writing that chapter.","sceneCN":"这里 researcher 是“从事系统研究的人”（第 1 个义项）；句意：他靠反复查证原始材料来完成研究。","pos":[{"tag":"n.","zh":"研究者；科研人员；调查者"}],"collocations":[{"phrase":"a leading researcher","zh":"一位顶尖研究者"},{"phrase":"research researcher","zh":"研究型学者"},{"phrase":"clinical researcher","zh":"临床研究员"},{"phrase":"market researcher","zh":"市场调研员"},{"phrase":"principal researcher","zh":"首席研究员"},{"phrase":"independent researcher","zh":"独立研究者"}],"forms":[{"label":"单数","form":"researcher"},{"label":"复数","form":"researchers"},{"label":"动词形式","form":"research"},{"label":"集体名词","form":"research"}],"derivatives":[{"word":"research","pos":"n./v.","zh":"研究；调查"},{"word":"researchable","pos":"adj.","zh":"可研究的"},{"word":"researched","pos":"adj.","zh":"经过充分研究的"},{"word":"research-based","pos":"adj.","zh":"基于研究的"}],"senses":[{"no":"01","title":"Someone who studies systematically","titleCN":"研究者：系统地查证一个问题的人","definition":"a person who investigates a subject in a planned, systematic way","definitionCN":"以有计划、系统的方式探究某个主题的人","example":"The researcher spent four years tracking the same herd.","exampleCN":"这位研究者花了四年追踪同一群动物。","why":"The agent suffix -er marks the person who performs the action named by research, and research literally means searching again and again.","whyCN":"施事后缀 -er 标记执行 research 这一动作的人，而 research 字面上就是“反复搜寻”。"},{"no":"02","title":"An investigator of facts","titleCN":"调查者：把事实一层层挖出来的人","definition":"a person who digs out facts, especially for a report or an inquiry","definitionCN":"把事实层层挖出的人，尤指为报道或调查","example":"The researcher found the missing invoice in a county archive.","exampleCN":"这位调查者在县档案馆找到了那张失踪的发票。","why":"Research began as intensive searching, so the person sense covers reporters and investigators, not only scientists.","whyCN":"research 本义是密集搜寻，因此这个指人的义项也覆盖记者与调查员，而不只是科学家。"},{"no":"03","title":"A member of a lab or university","titleCN":"科研人员：实验室与大学里的研究者","definition":"a scientist or scholar employed to carry out academic or laboratory research","definitionCN":"受雇从事学术或实验室研究的科学家或学者","example":"Two researchers in the lab share the microscopy work.","exampleCN":"实验室里的两名科研人员分担显微观察工作。","why":"Institutions turn the activity into a post, and the post gives the word its most common occupational sense.","whyCN":"机构把这项活动变成岗位，而岗位赋予这个词最常见的职业含义。"},{"no":"04","title":"A clinical investigator","titleCN":"临床研究员：在病人身上验证疗法的人","definition":"someone who runs or assists medical studies with human participants","definitionCN":"主持或协助以人为对象的医学研究的人","example":"The clinical researcher explained the trial to each volunteer.","exampleCN":"临床研究员向每位志愿者解释了试验内容。","why":"When the field is medicine, the search is for safety and effect in people, so the same title carries ethical duties.","whyCN":"当领域是医学时，所搜寻的是药物在人身上的安全与效果，因此同一头衔也带着伦理责任。"},{"no":"05","title":"A market or survey analyst","titleCN":"调研员：用问卷和数据摸清市场的人","definition":"a person who designs surveys or studies consumers for a company","definitionCN":"为公司设计问卷或研究消费者的人","example":"The market researcher ran focus groups before the launch.","exampleCN":"市场调研员在产品发布前组织了焦点小组。","why":"Commercial research also searches, but its object is preference and demand rather than natural law.","whyCN":"商业研究同样在搜寻，但对象是偏好与需求，而不是自然规律。"},{"no":"06","title":"Someone working outside institutions","titleCN":"独立研究者：不隶属机构的学者","definition":"a scholar who pursues research without a university or company post","definitionCN":"不在大学或公司任职而从事研究的学者","example":"An independent researcher corrected the census transcription.","exampleCN":"一位独立研究者更正了那次人口普查的转录。","why":"The word names the activity, not the employer; removing the institution leaves the searching intact.","whyCN":"这个词命名的是活动而非雇主；去掉机构，搜寻这件事依然完整。"},{"no":"07","title":"A digger in archives","titleCN":"史料研究者：在档案堆里找证据的人","definition":"a person whose method is the close reading of documents, records, and manuscripts","definitionCN":"以细读文件、记录与手稿为方法的人","example":"The historian works as a researcher in the national library.","exampleCN":"这位历史学家在国家图书馆做史料研究。","why":"Documents are a second kind of field: evidence is buried in paper, and finding it is still a search.","whyCN":"文献是另一种田野：证据埋在纸堆里，把它找出来仍然是搜寻。"},{"no":"08","title":"A student learning the craft","titleCN":"研究生研究者：边学边做的年轻学者","definition":"a graduate student or junior member learning to conduct research within a team","definitionCN":"在团队中边学习边开展研究的研究生或初级成员","example":"Each researcher presents her findings at the weekly seminar.","exampleCN":"每位研究生研究者都在每周讨论会上报告自己的发现。","why":"Training and research merge in the modern laboratory, so the title also covers those still learning the method.","whyCN":"现代实验室里训练与研究合而为一，因此这个头衔也覆盖仍在学习方法的人。"}],"etymology":{"intro":{"en":"Researcher is research plus -er. Research is re- plus search, and search goes back through Old French cerchier to Latin circare, to go about, from circus, a circle.","cn":"researcher 由 research 加 -er 构成。research 是 re- 加 search，而 search 经古法语 cerchier 上溯到拉丁语 circare“四处走动”，其词源为 circus“圆圈”。"},"items":[{"era":"LATIN circus","en":"Circus meant a ring or circle. The round track supplied the image of going round and round a space.","cn":"circus 意为“圆圈、环”。环形跑道提供了“绕着某处来回走”的形象。"},{"era":"LATIN circare","en":"Circare meant to go about or wander over an area. Searching is pictured as walking a territory until nothing is missed.","cn":"circare 意为在某区域内走动、巡行。搜寻被想象成把一片地方走遍，直到没有遗漏。"},{"era":"FRENCH cerchier","en":"Old French cerchier meant to search or seek, keeping the image of circling a place to find something.","cn":"古法语 cerchier 意为搜寻、寻找，保留了“绕着某处转以找到东西”的形象。"},{"era":"FRENCH recerche","en":"Middle French recerche meant a close search, with re- adding intensity or repetition rather than simple return.","cn":"中古法语 recerche 意为仔细搜寻，其中的 re- 加强的是强度或反复，而不只是“返回”。"},{"era":"ENGLISH research","en":"English research first meant the act of searching closely; only later did it become the systematic study of a subject.","cn":"英语 research 最初指仔细搜寻的行为，后来才指对某一主题的系统研究。"},{"era":"ENGLISH -er","en":"The Old English agent suffix -ere became -er, marking the person who performs the action of the verb.","cn":"古英语施事后缀 -ere 演变为 -er，标记执行动词动作的人。"}]},"similar":{"note":{"en":"The first group is the research family, separated by word class; the second compares people who investigate in different settings.","cn":"第一组是 research 词族，按词类区分；第二组比较在不同场景中从事调查的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"research","ipa":"/rɪˈsɜːtʃ/","tag":"noun or verb","definition":"systematic investigation of a subject. It names the activity or the body of work.","definitionCN":"对某主题的系统研究；命名的是活动或成果。"},{"word":"researcher","ipa":"/rɪˈsɜːtʃə(r)/","tag":"person noun","definition":"a person who carries out research. It names the individual.","definitionCN":"从事研究的人；命名的是个体。"},{"word":"researchable","ipa":"/rɪˈsɜːtʃəbl/","tag":"adjective","definition":"able to be investigated with available methods and evidence.","definitionCN":"能够用现有方法与证据加以研究的。"},{"word":"researched","ipa":"/rɪˈsɜːtʃt/","tag":"adjective","definition":"carefully investigated, as in a well-researched article. It judges the finished product.","definitionCN":"经过仔细研究的，如“研究扎实的文章”；评判的是成品。"}]},{"heading":"NEAR MEANING","entries":[{"word":"investigator","ipa":"/ɪnˈvestɪɡeɪtə(r)/","tag":"person noun","definition":"a person who investigates, especially a crime or an official inquiry. It stresses uncovering causes.","definitionCN":"从事调查的人，尤指刑事案件或官方调查；强调查明原因。"},{"word":"scholar","ipa":"/ˈskɒlə(r)/","tag":"person noun","definition":"a person with deep learning in a field. It stresses knowledge rather than the process of discovery.","definitionCN":"在某一领域学识深厚的人；强调学识而非发现过程。"},{"word":"analyst","ipa":"/ˈænəlɪst/","tag":"person noun","definition":"a person who examines data or situations to explain them. It stresses interpretation.","definitionCN":"分析数据或形势以作出解释的人；强调解读。"},{"word":"scientist","ipa":"/ˈsaɪəntɪst/","tag":"person noun","definition":"a person trained in a natural or social science. It names a profession rather than an activity.","definitionCN":"受过自然科学或社会科学训练的人；命名的是职业而非活动。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re-, search, -er. Search itself comes from a Latin verb for going round a place, so a researcher is someone who keeps walking the territory.","cn":"只用真实成分：re-、search、-er。search 出自拉丁语中“绕行某地”的动词，因此研究者就是反复走遍这片地方的人。"},"normal":[{"en":"Re plus search plus er: the person who searches again and again.","cn":"re 加 search 加 er：一遍又一遍搜寻的那个人。"},{"en":"Search comes from circling a field until nothing is missed.","cn":"search 出自绕着田野走遍、直到没有遗漏。"},{"en":"A researcher in an archive is walking a paper field.","cn":"在档案馆里的研究者，是在一片纸做的田野上行走。"},{"en":"The -er tells you who; the research tells you what they keep doing.","cn":"词尾告诉你“谁”，词根告诉你“他一直在做什么”。"},{"en":"A clinical researcher searches for safety in people, not in test tubes.","cn":"临床研究员在人身上寻找安全性，而不是在试管里。"}],"abstract":[{"en":"Research is only called systematic when the searcher can say where the search stopped.","cn":"只有当搜寻者说得出自己在哪里停下时，研究才被称为系统的。"},{"en":"Every researcher chooses a small field to walk, and the choice is already an argument.","cn":"每位研究者都选一小片田野去走，而这个选择本身已是一种主张。"},{"en":"The word keeps its old image: knowledge is produced by circling a question long enough.","cn":"这个词保留着旧形象：知识是靠围绕一个问题转得足够久才产生的。"}]},"examples":[{"en":"Researchers at three universities compared the same soil samples.","cn":"三所大学的研究者比较了同一批土壤样本。"},{"en":"As a researcher, she is known for checking every citation by hand.","cn":"作为研究者，她以逐条手工核对引文而闻名。"},{"en":"The market researcher found that shoppers ignored the new labels.","cn":"市场调研员发现购物者根本不看新标签。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（反复）+ search（搜寻）+ er（人）——反复搜寻的人，就是研究者。","word":"researcher"},"root":"由 research（研究、反复搜寻）加 -er（施事者后缀）构成；research 为 re-（反复、加强）加 search（搜寻，经古法语 cerchier 源自拉丁语 circare“巡行、绕行”，词源为 circus“圆圈”），本义为“反复走访以查明问题的人”。","sensesIntro":{"en":"Eight senses of researcher, all circling one idea: a person who searches a subject until the evidence settles. The search may be academic, journalistic, clinical, commercial, independent, archival, or still being learned.","cn":"researcher 的八个义项都围绕一个观念：把一个问题搜寻到证据落定为止的人。这种搜寻可以是学术的、新闻的、临床的、商业的、独立的、档案的，也可以是尚在学习中的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a document room at midnight, thirty-year-old borrowing cards spread out, a timeline drawn in pencil.","cn":"核心意象：午夜的档案室，三十年前的借阅卡摊满桌面，铅笔画出时间线。"},"chain":["LATIN CIRCUS = CIRCLE","LATIN CIRCARE = TO GO ABOUT","FRENCH CERCHIER = TO SEARCH","FRENCH RECERCHE = CLOSE SEARCH","ENGLISH RESEARCH = SYSTEMATIC STUDY","RESEARCHER = THE PERSON WHO SEARCHES"],"branches":[{"senses":"S1 · S2","en":"THE SEARCH ITSELF: systematic inquiry, and the digging out of facts for a report or inquiry.","cn":"搜寻本身：系统探究，以及为报道或调查把事实挖出来。"},{"senses":"S3 · S4","en":"INSTITUTIONAL ROLES: a laboratory or university post, and a clinical investigator with ethical duties.","cn":"机构角色：实验室或大学岗位，以及承担伦理责任的临床研究员。"},{"senses":"S5","en":"COMMERCIAL SEARCH: surveys and consumer studies aimed at demand rather than natural law.","cn":"商业搜寻：面向需求而非自然规律的问卷与消费者研究。"},{"senses":"S6 · S7","en":"OUTSIDE AND INSIDE THE ARCHIVE: the independent scholar and the close reader of documents.","cn":"档案内外：独立学者，与细读文献的人。"},{"senses":"S8","en":"THE CRAFT BEING LEARNED: a junior member who researches while still in training.","cn":"正在学习的技艺：一边受训一边做研究的初级成员。"}]},"affixes":{"intro":{"en":"Researcher is research plus -er. Research is re- plus search, and the -er suffix marks the person. The family also supplies researchable and researched.","cn":"researcher 由 research 加 -er 构成。research 是 re- 加 search，-er 标记人。词族还包括 researchable 与 researched。"},"latinIntro":{"en":"Latin circus and circare supply the base of search through Old French. The prefix re- is Latin, and the agent suffix -er is native English.","cn":"拉丁语 circus 与 circare 经古法语提供了 search 的词基。前缀 re- 来自拉丁语，施事后缀 -er 是英语本族成分。"},"items":[{"word":"circus","structure":"Latin noun (ring, circle)","meaning":"a circular track or ring","meaningCN":"环形场地；圆圈","example":"The Latin word survives in English circus and in circle.","exampleCN":"这个拉丁词在英语 circus（马戏场）与 circle（圆圈）中留存。"},{"word":"circare","structure":"Latin verb from circus","meaning":"to go about, wander over","meaningCN":"巡行；四处走动","example":"The verb described going over a district in search of something.","exampleCN":"该动词描述为寻找某物而走遍一个区域。"},{"word":"search","structure":"Old French cerchier < Latin circare","meaning":"to look carefully for something","meaningCN":"仔细寻找","example":"They searched the attic for the missing deed.","exampleCN":"他们在阁楼里寻找那份失踪的地契。"},{"word":"research","structure":"re- (intensive or repeated) + search","meaning":"close searching, later systematic study","meaningCN":"仔细搜寻，后指系统研究","example":"Her research on the harbour took ten years.","exampleCN":"她对这座港口的研究花了十年。"},{"word":"researcher","structure":"research + -er (agent)","meaning":"a person who carries out research","meaningCN":"从事研究的人","example":"A researcher must record where each figure came from.","exampleCN":"研究者必须记录每个数据的来源。"},{"word":"researchers","structure":"researcher + -s (plural)","meaning":"more than one person carrying out research","meaningCN":"多名研究者","example":"Researchers disagree about the date of the wall.","exampleCN":"研究者们对这段城墙的年代意见不一。"},{"word":"researchable","structure":"research + -able (able to be)","meaning":"able to be investigated with available evidence","meaningCN":"可研究的；有证据可查的","example":"The question is interesting but barely researchable.","exampleCN":"这个问题很有意思，却几乎无法研究。"},{"word":"researched","structure":"research + -ed (past participle)","meaning":"thoroughly investigated","meaningCN":"经过充分研究的","example":"The biography is well researched and clearly written.","exampleCN":"这部传记研究扎实，文字清晰。"},{"word":"research-based","structure":"research + based (founded on)","meaning":"founded on systematic evidence","meaningCN":"基于研究证据的","example":"The school adopted a research-based reading programme.","exampleCN":"学校采用了一套基于研究的阅读课程。"}],"latinEntries":[{"word":"circus","structure":"Latin noun","meaning":"ring, circular track","meaningCN":"圆圈；环形场地"},{"word":"circare","structure":"Latin verb from circus","meaning":"to go about, wander over","meaningCN":"巡行；四处走动"},{"word":"re-","structure":"Latin prefix","meaning":"back, again, or intensive","meaningCN":"回；再；或表加强"}]}},{"word":"residential","ipa_uk":"/ˌrezɪˈdenʃl/","ipa_us":"/ˌrezɪˈdenʃəl/","definition_zh":"住宅的；居住用的；居民区的；寄宿制的；常驻的；居住地址的","definition_en":"relating to homes or to living in a place, rather than to work, business, or industry","core_image":"傍晚的街道两侧是矮房、篱笆与晾在阳台上的衣服，没有招牌，也没有货车停靠。","scene":"房产中介把地图上一片安静街区圈出来说，这里没有工厂也没有写字楼，全是住户的房子。This quiet district is purely residential: there are no factories or offices, only homes.","sceneCN":"这里 residential 是“住宅性质的、居住用的”（第 1 个义项）；句意：这一片全是住人的房子，没有商业或工业。","pos":[{"tag":"adj.","zh":"住宅的；居住的；寄宿制的；常驻的"}],"collocations":[{"phrase":"residential area","zh":"住宅区"},{"phrase":"residential property","zh":"住宅房产"},{"phrase":"residential address","zh":"居住地址"},{"phrase":"residential care","zh":"住宿照护"},{"phrase":"residential course","zh":"住校课程"},{"phrase":"residential population","zh":"常住人口"}],"forms":[{"label":"原级（形容词）","form":"residential"},{"label":"比较级（用 more）","form":"more residential"},{"label":"最高级（用 most）","form":"most residential"},{"label":"名词形式","form":"resident"},{"label":"名词形式（居住）","form":"residence"}],"derivatives":[{"word":"resident","pos":"n./adj.","zh":"居民；居住的"},{"word":"residence","pos":"n.","zh":"住宅；居住"},{"word":"reside","pos":"v.","zh":"居住；存在"},{"word":"residency","pos":"n.","zh":"居住资格；住院医师期"}],"senses":[{"no":"01","title":"Land used for homes","titleCN":"住宅的：用于住人的土地与建筑","definition":"describing areas or buildings used mainly for private homes rather than businesses or factories","definitionCN":"描述主要用于私人住宅而非商业或工业的区域或建筑","example":"The old warehouse district was rezoned as residential land.","exampleCN":"旧仓库区被重新规划为住宅用地。","why":"The adjective adds -ial to resident, which comes from Latin residere, to remain sitting; land is residential when people remain there to live.","whyCN":"这个形容词在 resident 后加 -ial，而 resident 出自拉丁语 residere“留下坐住”；当人们留下来生活时，土地就是住宅性质的。"},{"no":"02","title":"Living there, not visiting","titleCN":"居住的：长期住在某地","definition":"relating to the fact of living in a place, especially for legal or administrative purposes","definitionCN":"与在某地居住这一事实有关，尤用于法律或行政用途","example":"The visa requires proof of residential status for five years.","exampleCN":"该签证要求提供五年居住身份证明。","why":"Here the word marks duration and legal attachment: a resident is not a visitor, and the adjective carries that permanence.","whyCN":"这里标记的是时长与法律归属：居民不是访客，这个形容词承载着那份长期性。"},{"no":"03","title":"Who lives there","titleCN":"常住人口的：按居住统计的人","definition":"relating to the people who live in a place, as counted in censuses","definitionCN":"与在某地居住、并按人口普查统计的人有关","example":"The residential population doubles during the summer season.","exampleCN":"夏季这里的常住人口会翻倍。","why":"Statistics distinguish people by where they sleep, not where they work; residential population is the count of sleepers.","whyCN":"统计按人睡在哪里而不是在哪里工作来分类；常住人口统计的是“在这里过夜的人”。"},{"no":"04","title":"Homes as property","titleCN":"住宅地产的：作为买卖对象的住房","definition":"relating to private housing as a market commodity, as opposed to commercial property","definitionCN":"与作为市场商品的私人住房有关，与商业地产相对","example":"Residential prices rose faster than office rents.","exampleCN":"住宅价格的涨幅快于写字楼租金。","why":"When housing enters the market it becomes a class of property, and the adjective separates it from shops and factories.","whyCN":"当住房进入市场，它就成为一类地产，这个形容词把它与商铺、工厂区分开。"},{"no":"05","title":"Students living on site","titleCN":"寄宿制的：学生住在校内","definition":"describing a school, course, or programme in which participants live on the premises","definitionCN":"描述参与者住在校内的学校、课程或项目","example":"The summer programme is residential, so students stay in the dormitories.","exampleCN":"这个暑期项目是寄宿制的，学生住在宿舍里。","why":"The word shifts from a district to an institution: a residential course houses its students, making the school a temporary home.","whyCN":"词义从街区转到机构：寄宿课程把学生安置在校内，使学校成为临时的家。"},{"no":"06","title":"The feel of a housing street","titleCN":"居民区的：街道呈现生活气息","definition":"having the quiet, domestic character of a street where people live","definitionCN":"具有人们居住的街道那种安静、居家的特征","example":"The café sits on a residential corner and closes at nine.","exampleCN":"这家咖啡馆位于居民区街角，九点就打烊。","why":"Character, not zoning, is at stake: a street feels residential when its sounds and hours belong to households.","whyCN":"这里看的是气质而不是规划：当街道的声音与作息属于家庭时，它就有居民区的感觉。"},{"no":"07","title":"Where you actually live","titleCN":"居住地址的：信件能寄到的地方","definition":"used of the address at which a person actually lives, as distinct from a work address","definitionCN":"指一个人实际居住的地址，与工作地址相对","example":"Please give a residential address, not a post office box.","exampleCN":"请提供居住地址，而不是邮政信箱。","why":"Administration needs a place where a body can be found; a residential address is that physical anchor.","whyCN":"行政事务需要一个能找得到人的地方；居住地址就是那个物理锚点。"},{"no":"08","title":"Staff required to live in","titleCN":"常驻的：工作人员必须住在驻地","definition":"describing staff who are required to live at their workplace, such as wardens or caretakers","definitionCN":"描述必须住在工作场所的工作人员，如管理员或看护","example":"The school employs a residential tutor who is on call at night.","exampleCN":"学校聘有一位常驻导师，夜里随时待命。","why":"The adjective reverses the usual direction: instead of work coming to the home, the home is brought to the job.","whyCN":"这个形容词把通常方向倒过来：不是工作来到家，而是家被搬到工作那里。"}],"etymology":{"intro":{"en":"Residential is resident plus -ial. Resident comes from Latin residere, to remain sitting behind, from re-, back, and sedere, to sit.","cn":"residential 由 resident 加 -ial 构成。resident 出自拉丁语 residere“留在后面坐着”，由 re-“向后”与 sedere“坐”组成。"},"items":[{"era":"LATIN sedere","en":"Sedere meant to sit. The image of sitting down supplies the whole family: a place where one settles is where one resides.","cn":"sedere 意为“坐”。坐下的形象支撑了整个词族：人安顿下来的地方就是居住地。"},{"era":"LATIN residere","en":"Residere combined re-, back, with sedere: to sit back, stay behind, and therefore to dwell in a place.","cn":"residere 由 re-“向后”与 sedere 组合：向后坐、留在后面，因而指在某地居住。"},{"era":"LATIN residens","en":"The participle residens described someone remaining in a place, and English took it directly as resident.","cn":"分词 residens 描述留在某地的人，英语直接把它借为 resident。"},{"era":"FRENCH resident","en":"Old French used resident for an official who stayed at a court or in a country to represent a power.","cn":"古法语用 resident 指留在宫廷或某国代表某一势力的官员。"},{"era":"ENGLISH resident","en":"English resident widened from diplomats to anyone who lives in a place, and later to medical staff living at a hospital.","cn":"英语 resident 从外交人员扩展到任何在某地居住的人，后来又指住在医院的医务人员。"},{"era":"LATIN -ialis","en":"The suffix -ialis formed adjectives meaning belonging to or concerning; with resident it produces residential, concerning residence.","cn":"后缀 -ialis 构成表示“属于、关于”的形容词；与 resident 结合得到 residential，即“关于居住的”。"}]},"similar":{"note":{"en":"The first group is the reside family, separated by word class; the second compares words about homes, housing, and living on site.","cn":"第一组是 reside 词族，按词类区分；第二组比较关于住宅、住房与住校的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reside","ipa":"/rɪˈzaɪd/","tag":"verb","definition":"to live in a particular place, often used formally.","definitionCN":"正式用语，指住在某个特定地方。"},{"word":"resident","ipa":"/ˈrezɪdənt/","tag":"noun or adjective","definition":"a person who lives in a place. As an adjective it means living there.","definitionCN":"在某地居住的人；作形容词时意为居住的。"},{"word":"residence","ipa":"/ˈrezɪdəns/","tag":"noun","definition":"a house or the fact of living somewhere. It names the place or the state.","definitionCN":"住宅，或居住的状态；命名的是地点或状态。"},{"word":"residential","ipa":"/ˌrezɪˈdenʃl/","tag":"adjective","definition":"relating to homes, housing, or living on site.","definitionCN":"与住宅、住房或住在场所内有关的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"domestic","ipa":"/dəˈmestɪk/","tag":"adjective","definition":"relating to the home and family, or to one's own country. It stresses household life.","definitionCN":"与家庭或本国有关的；强调家居生活。"},{"word":"suburban","ipa":"/səˈbɜːbən/","tag":"adjective","definition":"relating to the outskirts of a city where people live and commute. It stresses location.","definitionCN":"与城市外围居住区有关的；强调地理位置。"},{"word":"boarding","ipa":"/ˈbɔːdɪŋ/","tag":"adjective","definition":"describing a school where pupils live during term. It is the common British term for residential schooling.","definitionCN":"描述学期中学生在校住宿的学校；是英式英语中“寄宿制”的常用说法。"},{"word":"occupancy","ipa":"/ˈɒkjəpənsi/","tag":"noun","definition":"the fact or number of people using a building. It counts use rather than classifying land.","definitionCN":"建筑被使用的状况或人数；统计使用情况，而非给土地分类。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: resident plus -ial. Resident comes from Latin sedere, to sit, so residential land is land where people sit down and stay.","cn":"只用真实成分：resident 加 -ial。resident 出自拉丁语 sedere“坐”，所以住宅用地就是人们坐下来长住的地方。"},"normal":[{"en":"Resident plus ial: the adjective of places where residents sit and stay.","cn":"resident 加 ial：居民坐下来长住之处的形容词。"},{"en":"No shop signs, no lorries: that street is residential.","cn":"没有店招、没有货车：那条街就是住宅区。"},{"en":"A residential address is where your body is found at night.","cn":"居住地址就是你夜里能被找到的地方。"},{"en":"A residential course makes the school your temporary home.","cn":"寄宿课程把学校变成你临时的家。"},{"en":"A residential warden lives where the job is, not the other way round.","cn":"常驻管理员住在工作地点，而不是工作搬到家里。"}],"abstract":[{"en":"Zoning is a society deciding which activities may share a patch of ground.","cn":"用地规划就是一个社会在决定哪些活动可以共享一块地面。"},{"en":"A residential address turns a person into someone who can be reached.","cn":"居住地址把一个人变成可以被找到的对象。"},{"en":"The quieter a district sounds, the more invisible its rules become.","cn":"一个街区越安静，它的规则就越不易被察觉。"}]},"examples":[{"en":"The council approved a residential tower on the old car park.","cn":"议会批准在旧停车场地块上建住宅塔楼。"},{"en":"Residential care is intended for people who cannot live alone safely.","cn":"住宿照护面向无法安全独居的人。"},{"en":"Her residential address is in the city, though she works abroad.","cn":"她的居住地址在城里，尽管她在国外工作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"resident（居民）+ ial（关于……的）——关于居民的，就是住宅的。","word":"residential"},"root":"由 resident（居民；居住的）加 -ial（属于……的、关于……的）构成；resident 出自拉丁语 residere“留在后面坐住”，其词基 sedere 意为“坐”，本义为“与居住、住宅有关的”。","sensesIntro":{"en":"Eight senses of residential, all circling one idea: a place belongs to living rather than to work. The claim may concern land, legal status, population, property, a boarding institution, a street's character, a home address, or staff quarters.","cn":"residential 的八个义项都围绕一个观念：某个地方属于生活，而不是属于工作。这个主张可以涉及土地、法律身份、人口、房产、寄宿机构、街道气质、居住地址，或员工驻地。"},"semanticMap":{"core":{"en":"CORE IMAGE: an evening street of low houses, hedges, and washing on balconies, without a single shop sign.","cn":"核心意象：傍晚的街两侧是矮房、篱笆与阳台上的衣物，一块店招也没有。"},"chain":["LATIN SEDERE = TO SIT","LATIN RESIDERE = TO STAY SEATED","LATIN RESIDENS = ONE WHO REMAINS","ENGLISH RESIDENT = ONE WHO LIVES THERE","SUFFIX -IAL = CONCERNING","RESIDENTIAL = CONCERNING HOMES"],"branches":[{"senses":"S1 · S6","en":"LAND AND ITS FEEL: zoning for homes, and the quiet hours that mark a lived-in street.","cn":"土地与气质：划作住宅的用地，以及标记居住生活的安静作息。"},{"senses":"S2 · S7","en":"ADMINISTRATIVE ANCHORS: legal residential status and the address where a body is found.","cn":"行政锚点：法律上的居住身份，以及能找到人的居住地址。"},{"senses":"S3 · S4","en":"COUNTING PEOPLE AND PROPERTY: census numbers and housing as a market commodity.","cn":"人与房产的统计：普查数字，以及作为市场商品的住房。"},{"senses":"S5","en":"AN INSTITUTION AS HOME: a boarding school or course that houses its members.","cn":"作为家的机构：把成员安置在内的寄宿学校或课程。"},{"senses":"S8","en":"THE JOB BROUGHT HOME: staff required to live on site.","cn":"把家搬到岗位：必须住在驻地的员工。"}]},"affixes":{"intro":{"en":"Residential is resident plus -ial. The family also includes reside, residence, and residency, all built on the Latin image of sitting down.","cn":"residential 由 resident 加 -ial 构成。词族还包括 reside、residence 与 residency，都建立拉丁语“坐下来”的形象上。"},"latinIntro":{"en":"The Latin base is sedere, to sit, extended in residere. The -ial ending comes from Latin -ialis, and the -ence ending from -entia.","cn":"拉丁词基是 sedere“坐”，在 residere 中扩展。-ial 词尾出自拉丁语 -ialis，-ence 词尾出自 -entia。"},"items":[{"word":"sedere","structure":"Latin verb, second conjugation","meaning":"to sit, to settle","meaningCN":"坐；安顿","example":"The root also appears in sedentary and sediment.","exampleCN":"这个词根也出现在 sedentary（久坐的）与 sediment（沉积物）中。"},{"word":"residere","structure":"re- (back) + sedere (to sit)","meaning":"to sit back, remain behind, dwell","meaningCN":"向后坐；留下；居住","example":"The Latin verb described water that stays in a pool after a flood.","exampleCN":"这个拉丁动词可描述洪水退后留在水洼里的水。"},{"word":"reside","structure":"Latin residere through French","meaning":"to live in a place","meaningCN":"居住","example":"The family resides above the shop.","exampleCN":"这家人住在店铺楼上。"},{"word":"resident","structure":"Latin residens, present participle","meaning":"a person who lives in a place","meaningCN":"居民；居住者","example":"Residents complained about the night buses.","exampleCN":"居民抱怨夜班公交。"},{"word":"residence","structure":"resident + -ence (state or place)","meaning":"the state of living somewhere, or the house itself","meaningCN":"居住状态；住宅","example":"The ambassador's residence stands behind the embassy.","exampleCN":"大使官邸位于使馆后面。"},{"word":"residential","structure":"resident + -ial (concerning)","meaning":"relating to homes or to living on site","meaningCN":"住宅的；居住的；寄宿的","example":"Residential streets have lower speed limits.","exampleCN":"居民区街道限速更低。"},{"word":"residency","structure":"resident + -ency (state or period)","meaning":"legal permission to live somewhere, or a hospital training period","meaningCN":"居住许可；住院医师培训期","example":"She applied for permanent residency after six years.","exampleCN":"六年后她申请了永久居留权。"},{"word":"residentiality","structure":"residential + -ity (quality)","meaning":"the degree to which an area is made up of homes","meaningCN":"某区域的住宅化程度","example":"Planning disputes often turn on residentiality.","exampleCN":"规划争议常常围绕一个区域的住宅化程度展开。"},{"word":"non-residential","structure":"non- (not) + residential","meaning":"not used for living in","meaningCN":"非居住用的","example":"The site is zoned non-residential, so no flats may be built.","exampleCN":"该地块规划为非住宅用途，不得建公寓。"}],"latinEntries":[{"word":"sedere","structure":"Latin verb","meaning":"to sit","meaningCN":"坐"},{"word":"residere","structure":"re- + sedere","meaning":"to remain sitting, dwell","meaningCN":"留下；居住"},{"word":"-ialis","structure":"Latin adjective suffix","meaning":"concerning, belonging to","meaningCN":"关于……的；属于……的"}]}},{"word":"resolution","ipa_uk":"/ˌrezəˈluːʃn/","ipa_us":"/ˌrezəˈluːʃən/","definition_zh":"决心；决议；解决；分辨率；分解；果断；裁决；和声解决","definition_en":"the act of solving a problem, a formal decision, the sharpness of an image, or the quality of being determined","core_image":"会议桌上一张写满争执的纸被翻到背面，一群人用铅笔在上面写出三条双方都能接受的条款。","scene":"两方吵了整晚，天亮时律师在纸上写下三条双方都能接受的条款，宣布争端到此为止。The lawyer drafted three clauses both sides accepted, bringing the dispute to a resolution by morning.","sceneCN":"这里 resolution 是“问题的解决”（第 3 个义项）；句意：通过三条条款，争端得到解决。","pos":[{"tag":"n.","zh":"决心；决议；解决；分辨率；分解"}],"collocations":[{"phrase":"reach a resolution","zh":"达成解决"},{"phrase":"high resolution","zh":"高分辨率"},{"phrase":"a resolution to the dispute","zh":"争端的解决方案"},{"phrase":"New Year's resolution","zh":"新年决心"},{"phrase":"resolution of an image","zh":"图像分辨率"},{"phrase":"pass a resolution","zh":"通过一项决议"}],"forms":[{"label":"单数","form":"resolution"},{"label":"复数","form":"resolutions"},{"label":"动词形式","form":"resolve"},{"label":"形容词形式","form":"resolute"}],"derivatives":[{"word":"resolve","pos":"v.","zh":"解决；决心；分解"},{"word":"resolute","pos":"adj.","zh":"坚决的；果断的"},{"word":"resolved","pos":"adj.","zh":"下定决心的"},{"word":"unresolved","pos":"adj.","zh":"未解决的"}],"senses":[{"no":"01","title":"Firm determination","titleCN":"决心：拿定主意不动摇","definition":"a firm decision to do or not do something, often stated formally","definitionCN":"做或不做的坚定决定，常以正式方式表达","example":"She made a resolution to finish the thesis before spring.","exampleCN":"她下定决心在春天前完成论文。","why":"Resolution comes from resolvere, to loosen; a mind that was tangled becomes untangled and settles on one course.","whyCN":"resolution 出自 resolvere“松开”；纠缠不清的心思被解开，落在一条路上，这就是决心。"},{"no":"02","title":"A formal decision","titleCN":"决议：集体表决通过的正式文件","definition":"a formal statement or decision voted on by a committee, assembly, or board","definitionCN":"由委员会、议会或董事会表决通过的正式声明或决定","example":"The council passed a resolution condemning the demolition.","exampleCN":"议会通过了一项谴责拆建的决议。","why":"A body cannot have a single mind, so its decision must be written and voted; the word moves from the mind to the document.","whyCN":"机构没有单一的心智，因此它的决定必须写下来并付诸表决；词义由“心”转到“文件”。"},{"no":"03","title":"Solving a problem","titleCN":"解决：把纠结的问题打开","definition":"the act of finding an answer to a problem, dispute, or difficulty","definitionCN":"为问题、争端或困难找到答案的行为","example":"The talks ended with a resolution of the border dispute.","exampleCN":"会谈以边界争端的解决告终。","why":"The Latin verb meant to untie a knot; solving is untying, and the noun names the moment the knot gives way.","whyCN":"拉丁动词本义是解开绳结；解决问题就是解结，名词命名的是结终于松开的时刻。"},{"no":"04","title":"Sharpness of an image","titleCN":"分辨率：图像能分辨出多少细节","definition":"the amount of detail that an image, screen, or lens can distinguish","definitionCN":"图像、屏幕或镜头能够分辨出的细节数量","example":"The scan is stored at a resolution of six hundred dots per inch.","exampleCN":"扫描件以每英寸六百点的分辨率保存。","why":"Two points close together must be separated to be seen; resolution measures how small that separation can be.","whyCN":"两个靠得很近的点必须被分开才能看见；分辨率衡量的就是能被分开的最小间距。"},{"no":"05","title":"Splitting into parts","titleCN":"分解：把整体拆成成分","definition":"the separation of something into its constituent parts, as in chemistry or medicine","definitionCN":"把某物分离为其组成成分，如化学或医学中","example":"The resolution of the compound required strong heat.","exampleCN":"分解这种化合物需要高温。","why":"Chemists borrowed the word because analysis loosens a whole into its pieces, much as untangling separates strands.","whyCN":"化学家借用这个词，因为分析把整体松开成各个部分，就像解开缠结把线分开。"},{"no":"06","title":"Unwavering firmness","titleCN":"果断：性格上的坚定","definition":"the quality of being resolute in character or purpose","definitionCN":"性格或目标上坚定不移的品质","example":"He met the criticism with calm resolution.","exampleCN":"他以沉着的坚定面对批评。","why":"Here the noun names a trait rather than an act; the settled mind is treated as a permanent possession.","whyCN":"这里的名词命名的是品质而非行为；已定的心意被当作一种持久的所有物。"},{"no":"07","title":"A dissonance resolved","titleCN":"和声解决：不协和音走向协和","definition":"in music, the progression by which a dissonant chord moves to a consonant one","definitionCN":"音乐中不协和和弦进行到协和和弦的过程","example":"The phrase ends on a quiet resolution into the tonic.","exampleCN":"这一乐句以安静地解决到主音结束。","why":"Musicians hear tension loosen; the same Latin image of untying fits a chord that was held and then released.","whyCN":"音乐家听到的是紧张被松开；拉丁语“解结”的形象正好适用于被按住又放开的和弦。"},{"no":"08","title":"A formal ruling","titleCN":"裁决：机构给出的正式结论","definition":"an authoritative decision that settles a matter, as by a court or arbitrator","definitionCN":"由法院或仲裁者等权威机构作出、使事项落定的决定","example":"The arbitrator's resolution was binding on both firms.","exampleCN":"仲裁者的裁决对两家公司都有约束力。","why":"This sense joins sense two and sense three: a formal decision that ends a dispute by authority rather than by persuasion.","whyCN":"这一义项结合了第二与第三义项：靠权威而非说服来终结争端的正式决定。"}],"etymology":{"intro":{"en":"Resolution is resolve plus -tion. Resolve comes from Latin resolvere, to loosen or untie, built on re-, back, and solvere, to loosen.","cn":"resolution 由 resolve 加 -tion 构成。resolve 出自拉丁语 resolvere“松开、解开”，由 re-“回”与 solvere“松开”组成。"},"items":[{"era":"LATIN solvere","en":"Solvere meant to loosen, release, or dissolve. Its older analysis as se-, apart, plus luere, to loosen, is generally accepted but not certain.","cn":"solvere 意为松开、释放、溶解。它较早的分析为 se-“分开”加 luere“松开”，一般认为是这样，但并非确证。"},{"era":"LATIN resolvere","en":"Resolvere added re- to solvere: to loosen back, untie, dissolve, and finally to explain a difficulty by taking it apart.","cn":"resolvere 在 solvere 前加 re-：松回去、解开、溶解，最终指把难题拆开来解释。"},{"era":"LATIN resolutio","en":"Resolutio named an untying or a dissolving, and also the answering of a question by analysis.","cn":"resolutio 指解开或溶解，也指通过分析来回答一个问题。"},{"era":"FRENCH resolution","en":"Old French resolution carried both the physical sense of dissolving and the mental sense of a settled decision.","cn":"古法语 resolution 兼有物理上的“溶解”与心理上的“已定决定”两义。"},{"era":"ENGLISH resolution (14th c.)","en":"English first used the word for breaking into parts and for answering doubts, then for determination and for formal votes.","cn":"英语最初用它指分解与解惑，后来指决心与正式表决。"},{"era":"ENGLISH optical sense (20th c.)","en":"The image sense developed with lenses and photography: resolution became the smallest detail an instrument can separate.","cn":"图像义随透镜与摄影发展而来：分辨率成为仪器能分开的最小细节。"}]},"similar":{"note":{"en":"The first group is the resolve family, separated by word class; the second compares words for decisions, answers, and sharpness of images.","cn":"第一组是 resolve 词族，按词类区分；第二组比较表示决定、解答与图像清晰度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"resolve","ipa":"/rɪˈzɒlv/","tag":"verb","definition":"to solve, decide firmly, or separate into parts. It is the action behind the noun.","definitionCN":"解决、决心或分解；是名词背后的动作。"},{"word":"resolute","ipa":"/ˈrezəluːt/","tag":"adjective","definition":"firm and determined in purpose. It describes the person rather than the decision.","definitionCN":"目标坚定果断的；描述的是人，而不是决定。"},{"word":"resolution","ipa":"/ˌrezəˈluːʃn/","tag":"noun","definition":"a decision, a solution, a formal vote, or image sharpness.","definitionCN":"决心、解决方案、正式表决，或图像清晰度。"},{"word":"resolvable","ipa":"/rɪˈzɒlvəbl/","tag":"adjective","definition":"able to be solved or separated into parts.","definitionCN":"可解决的；可分解的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decision","ipa":"/dɪˈsɪʒn/","tag":"noun","definition":"a choice made after consideration. It names the choice, not the firmness behind it.","definitionCN":"考虑后作出的选择；命名选择本身，而非其背后的坚定。"},{"word":"settlement","ipa":"/ˈsetlmənt/","tag":"noun","definition":"an official agreement ending a dispute. It stresses the deal rather than the mental act.","definitionCN":"结束争端的正式协议；强调协议本身，而非心理活动。"},{"word":"determination","ipa":"/dɪˌtɜːmɪˈneɪʃn/","tag":"noun","definition":"the quality of continuing despite difficulty. It stresses persistence over time.","definitionCN":"遇难仍坚持下去的品质；强调长期的坚持。"},{"word":"clarity","ipa":"/ˈklærəti/","tag":"noun","definition":"the quality of being easy to see or understand. It lacks the measured, technical sense of optical resolution.","definitionCN":"易于看清或理解的品质；缺少光学分辨率那种可测量的技术含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re- plus solve plus -tion. Solve comes from Latin solvere, to loosen, so a resolution is the loosening of a knot.","cn":"只用真实成分：re- 加 solve 再加 -tion。solve 出自拉丁语 solvere“松开”，所以 resolution 就是把结松开。"},"normal":[{"en":"Unloosen a problem and you have a resolution.","cn":"把问题松开，你就得到了一个解决方案。"},{"en":"A committee that cannot untie a knot writes a resolution instead.","cn":"解不开结的委员会，就改写一份决议。"},{"en":"Pixels close enough to blur have not reached the resolution limit.","cn":"近到糊成一片的像素，说明还没达到分辨率极限。"},{"en":"A New Year's resolution is a knot in the mind deliberately untied.","cn":"新年决心，就是心里一个被主动解开的结。"},{"en":"A dissonant chord resolves when the tension is finally released.","cn":"不协和和弦的“解决”，就是紧张终于被释放。"}],"abstract":[{"en":"Resolution always implies prior tension; nothing is resolved unless something was first bound.","cn":"解决总意味着先有紧张；没有先被绑住的东西，就谈不上解开。"},{"en":"A formal resolution can end a debate without changing a single mind.","cn":"一份正式决议可以终结辩论，却改变不了任何一个人的想法。"},{"en":"Sharpness is measured by what can be separated, not by what can be seen.","cn":"清晰度衡量的是能被分开的东西，而不是能被看见的东西。"}]},"examples":[{"en":"The two countries signed a resolution of their long-standing water dispute.","cn":"两国签署了解决长期水权争端的方案。"},{"en":"The telescope's resolution is fine enough to separate the two stars.","cn":"这台望远镜的分辨率足以分开那两颗星。"},{"en":"The board passed a resolution to phase out single-use plastics.","cn":"董事会通过了一项逐步淘汰一次性塑料的决议。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（反复）+ solution（解决）——反复求解直到定案，就是决心与决议。","word":"resolution"},"root":"由 resolve（解决、决心、分解）加 -tion（名词后缀）构成；resolve 出自拉丁语 resolvere“松开、解开”，由 re-“回”与 solvere“松开”组成，本义为“把纠结之物解开的结果”。","sensesIntro":{"en":"Eight senses of resolution, all circling one idea: a knot is untied. What was bound may be a problem, a debate, a mind, an image, a compound, a character, a chord, or a dispute under authority.","cn":"resolution 的八个义项都围绕一个观念：结被解开。被绑住的可以是问题、辩论、心思、图像、化合物、性格、和弦，也可以是由权威裁断的争端。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet of quarrels turned over, three acceptable clauses written on the back, the argument declared over.","cn":"核心意象：一张写满争执的纸被翻面，背面写下三条各方都能接受的条款，争吵宣告结束。"},"chain":["LATIN SOLVERE = TO LOOSEN","LATIN RESOLVERE = TO UNTIE, DISSOLVE","LATIN RESOLUTIO = AN UNTYING","ENGLISH RESOLVE = TO SETTLE OR DECIDE","SUFFIX -TION = ACT OR RESULT","RESOLUTION = THE UNTYING AND ITS RESULT"],"branches":[{"senses":"S1 · S6","en":"THE MIND SETTLED: a stated determination and the steady firmness of character behind it.","cn":"心意落定：明言的决心，以及其背后持久的坚定性格。"},{"senses":"S2 · S8","en":"THE COLLECTIVE AND AUTHORITATIVE DECISION: a voted statement and a binding ruling.","cn":"集体与权威的决定：表决通过的声明，以及有约束力的裁决。"},{"senses":"S3","en":"THE PROBLEM UNTIED: a dispute or difficulty brought to an end.","cn":"难题被解开：争端或困难被带到终点。"},{"senses":"S4","en":"SEPARATION MEASURED: the smallest detail an instrument can distinguish.","cn":"可测的分离：仪器能分辨的最小细节。"},{"senses":"S5 · S7","en":"TENSION RELEASED: a compound split into elements and a dissonance moved into consonance.","cn":"紧张被释放：化合物被拆成元素，不协和音走向协和。"}]},"affixes":{"intro":{"en":"Resolution is resolve plus -tion. The family includes resolute, resolved, and unresolvable, with -tion naming the act, -ute the quality, and un- the negation.","cn":"resolution 由 resolve 加 -tion 构成。词族包括 resolute、resolved 与 unresolvable，其中 -tion 命名动作，-ute 表示性质，un- 表示否定。"},"latinIntro":{"en":"The Latin layers are solvere, resolvere, and resolutio. The -tion suffix comes through French from Latin -tionem.","cn":"拉丁层次是 solvere、resolvere 与 resolutio。后缀 -tion 经法语来自拉丁语 -tionem。"},"items":[{"word":"solvere","structure":"Latin verb (to loosen, dissolve)","meaning":"to loosen, release, pay a debt","meaningCN":"松开；释放；偿还债务","example":"The root also appears in dissolve, absolute, and solution.","exampleCN":"这个词根也出现在 dissolve（溶解）、absolute（绝对的）与 solution（溶液）中。"},{"word":"resolvere","structure":"re- (back) + solvere (to loosen)","meaning":"to untie, dissolve, explain","meaningCN":"解开；溶解；解释","example":"The Latin verb could describe ice melting back into water.","exampleCN":"这个拉丁动词可描述冰融回水中。"},{"word":"resolve","structure":"Latin resolvere through French","meaning":"to settle a problem or make a firm decision","meaningCN":"解决问题；下定决心","example":"The committee resolved to postpone the vote.","exampleCN":"委员会决定推迟表决。"},{"word":"resolution","structure":"resolve + -tion (action or result)","meaning":"a solution, decision, or measured sharpness","meaningCN":"解决方案；决定；分辨率","example":"The resolution was adopted by a single vote.","exampleCN":"该决议以一票之差获得通过。"},{"word":"resolute","structure":"Latin resolutus (past participle) + English adjective use","meaning":"firm and unwavering","meaningCN":"坚定果断的","example":"She remained resolute despite the setbacks.","exampleCN":"尽管屡遭挫折，她仍然坚定。"},{"word":"resolved","structure":"resolve + -ed (past participle)","meaning":"having firmly decided","meaningCN":"已下定决心的","example":"He is resolved to leave the department.","exampleCN":"他已下定决心离开这个部门。"},{"word":"resolvable","structure":"resolve + -able (able to be)","meaning":"able to be solved or separated","meaningCN":"可解决的；可分解的","example":"Most of these conflicts are resolvable through mediation.","exampleCN":"这类冲突大多可通过调解解决。"},{"word":"irresolution","structure":"ir- (not) + resolution","meaning":"hesitation and lack of firmness","meaningCN":"犹豫不决","example":"His irresolution cost the team the contract.","exampleCN":"他的犹豫不决让团队失去了合同。"},{"word":"unresolved","structure":"un- (not) + resolved","meaning":"still not settled","meaningCN":"未解决的","example":"The question of funding remains unresolved.","exampleCN":"资金问题仍未解决。"}],"latinEntries":[{"word":"solvere","structure":"Latin verb","meaning":"to loosen, dissolve, release","meaningCN":"松开；溶解；释放"},{"word":"resolvere","structure":"re- + solvere","meaning":"to untie, dissolve, resolve","meaningCN":"解开；溶解；解决"},{"word":"resolutio","structure":"Latin noun from resolvere","meaning":"an untying, a dissolving","meaningCN":"解开；溶解"}]}},{"word":"respectively","ipa_uk":"/rɪˈspektɪvli/","ipa_us":"/rɪˈspektɪvli/","definition_zh":"分别地；各自地；依次地；按顺序对应地","definition_en":"used to say that two or more things match two or more other things in the order in which they were named","core_image":"两列名字写在黑板左右，中间画着一根根对得笔直的连线，第一根连第一根，第二根连第二根。","scene":"表格说明里写着，两名学生的得分分别是九十分和八十五分，读者立刻知道前者对应第一个人，后者对应第二个人。The two students scored ninety and eighty-five respectively, in the order listed.","sceneCN":"这里 respectively 是“按前文所列顺序依次对应”（第 1 个义项）；句意：两个分数按名单顺序分别属于两位学生。","pos":[{"tag":"adv.","zh":"分别地；各自地；依次对应地"}],"collocations":[{"phrase":"A and B respectively","zh":"分别是 A 和 B"},{"phrase":"respectively corresponding to","zh":"分别对应于"},{"phrase":"listed respectively","zh":"按顺序分别列出"},{"phrase":"ranked first and second respectively","zh":"分别排名第一和第二"},{"phrase":"scores of 90 and 85 respectively","zh":"分数分别为九十和八十五"}],"forms":[{"label":"原级（副词）","form":"respectively"},{"label":"形容词形式","form":"respective"},{"label":"名词形式","form":"respect"},{"label":"比较级（很少用）","form":"more respectively"}],"derivatives":[{"word":"respective","pos":"adj.","zh":"各自的；分别的"},{"word":"respect","pos":"n./v.","zh":"尊重；方面；尊敬"},{"word":"respectively","pos":"adv.","zh":"分别地"},{"word":"irrespective","pos":"adj.","zh":"不考虑的；不顾的"}],"senses":[{"no":"01","title":"Matching by order","titleCN":"依次对应：按前文顺序一一配对","definition":"used when two lists are matched in the order in which their items were mentioned","definitionCN":"用于按提及顺序把两个列表逐项配对","example":"Tom and Anna scored ninety and eighty-five respectively.","exampleCN":"汤姆和安娜的得分分别是九十和八十五。","why":"Respective comes from respicere, to look back; the adverb tells the reader to look back at the first list and take each item in turn.","whyCN":"respective 出自 respicere“向后看”；这个副词让读者回头看向第一个列表，并依次取用各项。"},{"no":"02","title":"Each on its own","titleCN":"各自地：分开而不合并","definition":"used to stress that items are considered separately rather than as a group","definitionCN":"用于强调各项被分开考虑，而不是作为一个整体","example":"The two experiments were respectively funded by the state and the university.","exampleCN":"这两项实验分别由州政府和大学资助。","why":"The word refuses to pool things: what belongs to one item must not be transferred to another.","whyCN":"这个词拒绝把事物合并：属于某一项的，不可转给另一项。"},{"no":"03","title":"In the stated sequence","titleCN":"按顺序地：先说先对，后说后对","definition":"in the exact sequence already given, with no reordering allowed","definitionCN":"严格按已给出的顺序，不允许重新排列","example":"The first and second chapters deal with growth and decline respectively.","exampleCN":"第一章与第二章分别讨论增长与衰退。","why":"Matching is positional, so a swap of the order would reverse the meaning; the sequence itself carries the information.","whyCN":"配对靠位置，顺序一旦调换，意思就反过来；信息就装在次序里。"},{"no":"04","title":"Item-by-item attribution","titleCN":"逐项归属：把属性分派给对应项","definition":"used to assign a different fact or quality to each of several items","definitionCN":"用于把不同的事实或性质分派给若干对应项","example":"The authors are a chemist and a historian respectively.","exampleCN":"两位作者分别是化学家和历史学家。","why":"Each predicate attaches to its own subject; the adverb prevents a reader from applying both to either one.","whyCN":"每个谓语各自附着于自己的主语；这个副词防止读者把两者都套到其中一个身上。"},{"no":"05","title":"Symmetric pairing","titleCN":"对称配对：前后两组的次序镜像相同","definition":"used when two groups of equal size are set against each other in the same order","definitionCN":"用于把两组数量相等的项目按同一顺序对照","example":"The male and female pairs weigh twelve and nine kilograms respectively.","exampleCN":"雄性与雌性个体分别重十二公斤和九公斤。","why":"The adverb works only when the lists have equal length; a missing item would break the correspondence silently.","whyCN":"只有当两个列表长度相等时这个副词才成立；缺一项，对应关系就会无声断裂。"},{"no":"06","title":"Separate figures in a report","titleCN":"分别计值：报告里各自给出数字","definition":"used in statistics and reports to give separate values for separate groups","definitionCN":"在统计与报告中为不同组分别给出数值","example":"Rural and urban incomes rose by three and seven percent respectively.","exampleCN":"农村与城镇收入分别增长百分之三和百分之七。","why":"Data tables compress information, and the adverb is the grammar that keeps the columns aligned.","whyCN":"数据表压缩信息，而这个副词就是保持各列对齐的语法手段。"},{"no":"07","title":"Keys in a legend","titleCN":"按图例顺序：图注里各符号对应各含义","definition":"used to pair the entries of a legend, map, or diagram with their meanings in order","definitionCN":"用于把图例、地图或图解中的条目按顺序与其含义配对","example":"The solid and dashed lines show rainfall and temperature respectively.","exampleCN":"实线与虚线分别表示降雨量与气温。","why":"A legend relies on position instead of labels; respectively tells the reader to read down both columns at once.","whyCN":"图例靠位置而不是标签来指认；这个副词让读者同时向下读两列。"},{"no":"08","title":"Separate obligations in a contract","titleCN":"各自承担：条款把义务分给各方","definition":"used in formal texts to assign duties, rights, or amounts to named parties in order","definitionCN":"用于正式文本，按顺序把义务、权利或金额分派给各方","example":"The lessor and the lessee shall bear repair and insurance costs respectively.","exampleCN":"出租人与承租人应分别承担维修费和保险费。","why":"Legal drafting needs zero ambiguity; the adverb fixes which party owes what without repeating the parties' names.","whyCN":"法律起草要求零歧义；这个副词不必重复各方名称，就固定了谁负什么。"}],"etymology":{"intro":{"en":"Respectively is respective plus -ly. Respective comes from Latin respectivus, from respicere, to look back at, built on re-, back, and specere, to look.","cn":"respectively 由 respective 加 -ly 构成。respective 出自拉丁语 respectivus，源头是 respicere“回头看”，由 re-“向后”与 specere“看”组成。"},"items":[{"era":"LATIN specere","en":"Specere meant to look or observe. The root runs through spectacle, inspect, and respect.","cn":"specere 意为看、观察。这个词根贯穿 spectacle、inspect 与 respect。"},{"era":"LATIN respicere","en":"Respicere joined re-, back, with specere: to look back at something, and so to take account of it.","cn":"respicere 由 re-“向后”与 specere 组合：回头看某物，因而顾及它。"},{"era":"LATIN respectivus","en":"Respectivus meant relating to or having reference to something, from the idea of looking back towards it.","cn":"respectivus 意为“与某物相关、参照某物的”，来自“回头看它”的想法。"},{"era":"ENGLISH respective","en":"English respective meant relating separately to each of several things, hence belonging to each one in its turn.","cn":"英语 respective 意为分别与若干事物相关，因而依次属于每一个。"},{"era":"ENGLISH respectively (15th c.)","en":"The adverb first meant relatively or with reference to something; the modern order-matching sense is recorded from the seventeenth century.","cn":"这个副词最初意为“相对地、参照地”；现代“按顺序对应”的用法见于十七世纪。"},{"era":"ENGLISH -ly","en":"The native adverb ending -ly turns respective into the instruction to read two lists in parallel.","cn":"本族副词词尾 -ly 把 respective 变成“平行读两个列表”的指令。"}]},"similar":{"note":{"en":"The first group is the respect family, separated by function; the second compares words that express correspondence, one by one, or separately.","cn":"第一组是 respect 词族，按功能区分；第二组比较表示对应、逐一或各自分开的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"respect","ipa":"/rɪˈspekt/","tag":"noun or verb","definition":"admiration, or a particular aspect. It has no order-matching function.","definitionCN":"尊重，或某个方面；没有按顺序配对的功能。"},{"word":"respective","ipa":"/rɪˈspektɪv/","tag":"adjective","definition":"belonging separately to each of the things mentioned.","definitionCN":"分别属于所提及的各个事物的。"},{"word":"respectively","ipa":"/rɪˈspektɪvli/","tag":"adverb","definition":"in the order named, matching two lists item by item.","definitionCN":"按所列顺序，逐项配对两个列表。"},{"word":"irrespective","ipa":"/ˌɪrɪˈspektɪv/","tag":"adjective","definition":"without regard to something, as in irrespective of cost. It means the opposite of taking account.","definitionCN":"不顾、不论，如 irrespective of cost；与“顾及”正好相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"correspondingly","ipa":"/ˌkɒrɪˈspɒndɪŋli/","tag":"adverb","definition":"in a way that matches or follows from something. It stresses consequence rather than order.","definitionCN":"以相称或随之而来的方式；强调结果关系，而非次序。"},{"word":"individually","ipa":"/ˌɪndɪˈvɪdʒuəli/","tag":"adverb","definition":"one by one, considered as single persons or things. It stresses separateness, not pairing.","definitionCN":"逐个地，作为单个的人或物；强调分开，而非配对。"},{"word":"separately","ipa":"/ˈseprətli/","tag":"adverb","definition":"as distinct items or occasions. It does not itself establish a one-to-one order.","definitionCN":"作为不同项目或场合；本身并不建立一对一顺序。"},{"word":"in turn","ipa":"/ɪn ˈtɜːn/","tag":"adverbial phrase","definition":"one after another in a stated order. It stresses succession rather than matching two lists.","definitionCN":"按给定顺序一个接一个；强调接续，而非两组配对。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: respect plus -ive plus -ly. Respect here means looking back, so the adverb tells you to look back down the first list as you read the second.","cn":"只用真实成分：respect 加 -ive 再加 -ly。这里的 respect 意为“回头看”，所以这个副词让你读第二列时回头对着第一列。"},"normal":[{"en":"Respect plus ive plus ly: look back at the earlier list, one item at a time.","cn":"respect 加 ive 加 ly：回头看向前一个列表，一次对一项。"},{"en":"Two columns of names, one straight line between each pair.","cn":"两列名字，每一对之间画一条直线。"},{"en":"Say the numbers respectively and the reader knows which belongs to whom.","cn":"用 respectively 说数字，读者就知道哪个数归谁。"},{"en":"Swap the order and the meaning flips; position is doing the work.","cn":"调换顺序意思就翻；是位置在承担表意。"},{"en":"In a contract, respectively keeps each party attached to its own duty.","cn":"在合同里，respectively 让每一方牢牢绑在自己的义务上。"}],"abstract":[{"en":"The word is a small machine for preventing two things from being confused.","cn":"这个词是一台防止两件事被混淆的小机器。"},{"en":"Its power comes from silence: it repeats no names, yet fixes every match.","cn":"它的力量来自沉默：不重复任何名称，却固定了每一处配对。"},{"en":"A list is an argument about order, and respectively enforces it.","cn":"列表本身就是关于次序的一次主张，而这个副词负责强制执行。"}]},"examples":[{"en":"The two samples weighed 3.2 and 4.7 grams respectively.","cn":"两份样品分别重三点二克和四点七克。"},{"en":"She and her brother were born in 1990 and 1993 respectively.","cn":"她和弟弟分别出生于一九九零年和一九九三年。"},{"en":"The red and blue curves plot pressure and volume respectively.","cn":"红线和蓝线分别绘出压强与体积。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"respective（各自的）+ ly——各自按顺序对号入座，就是分别地。","word":"respectively"},"root":"由 respective（各自的、分别的）加 -ly（副词后缀）构成；respective 出自拉丁语 respectivus，源头为 respicere“回头看”，由 re-“向后”与 specere“看”组成，本义为“回头按顺序各自对应地”。","sensesIntro":{"en":"Eight senses of respectively, all circling one idea: two lists are read in parallel, position by position. The lists may be names and scores, items and funders, chapters and themes, authors and trades, animals and weights, groups and figures, symbols and meanings, or parties and duties.","cn":"respectively 的八个义项都围绕一个观念：两个列表被平行读取，一位对一位。这两列可以是人名与分数、项目与资助方、章节与主题、作者与职业、动物与体重、群体与数字、符号与含义，或各方与义务。"},"semanticMap":{"core":{"en":"CORE IMAGE: two columns of names on a blackboard with straight lines drawn between them, first to first, second to second.","cn":"核心意象：黑板上两列名字，中间一根根笔直的连线，第一个连第一个，第二个连第二个。"},"chain":["LATIN SPECERE = TO LOOK","LATIN RESPICERE = TO LOOK BACK AT","LATIN RESPECTIVUS = HAVING REFERENCE TO","ENGLISH RESPECTIVE = BELONGING TO EACH","SUFFIX -LY = IN THE MANNER OF","RESPECTIVELY = IN THE ORDER NAMED"],"branches":[{"senses":"S1 · S3","en":"POSITIONAL MATCHING: the first goes with the first, and the sequence cannot be rearranged.","cn":"按位置配对：第一个对第一个，次序不可重排。"},{"senses":"S2 · S4","en":"SEPARATE ATTRIBUTION: each item keeps its own fact and does not share it with a neighbour.","cn":"分别归属：每一项守住自己的事实，不与邻项共享。"},{"senses":"S5","en":"EQUAL LISTS SET AGAINST EACH OTHER: pairing works only while the two lists stay the same length.","cn":"等长列表相互对照：只有两列长度一致，配对才成立。"},{"senses":"S6 · S7","en":"ALIGNING DATA AND LEGENDS: separate figures in a report and symbols in a key, each tied to its own meaning.","cn":"对齐数据与图例：报告里各自的数字，图注里各自的符号，都绑定到自己的含义。"},{"senses":"S8","en":"LEGAL ALLOCATION: named parties bound to their own obligations without repeating their names.","cn":"法律分派：具名各方各自绑定义务，而不必重复名称。"}]},"affixes":{"intro":{"en":"Respectively is respective plus -ly. The family includes respect, respective, and irrespective, where the prefix ir- reverses the idea of taking account.","cn":"respectively 由 respective 加 -ly 构成。词族包括 respect、respective 与 irrespective，其中前缀 ir- 反转“顾及”的意思。"},"latinIntro":{"en":"The Latin layers are specere and respicere, with the adjective respectivus. The -ly ending is native English rather than Latin.","cn":"拉丁层次是 specere 与 respicere，以及形容词 respectivus；-ly 词尾是英语本族成分，而非拉丁语。"},"items":[{"word":"specere","structure":"Latin verb (to look)","meaning":"to look at, observe","meaningCN":"看；观察","example":"The root appears in spectrum, inspect, and specimen.","exampleCN":"这个词根出现在 spectrum（光谱）、inspect（检查）与 specimen（标本）中。"},{"word":"respicere","structure":"re- (back) + specere (to look)","meaning":"to look back at, to have regard for","meaningCN":"回头看；顾及","example":"The Latin verb could describe looking back at one's own tracks.","exampleCN":"这个拉丁动词可描述回头查看自己的足迹。"},{"word":"respect","structure":"Latin respectus, from respicere","meaning":"regard, esteem, or a particular aspect","meaningCN":"尊重；方面","example":"In this respect the two plans differ sharply.","exampleCN":"在这个方面，两个方案差别很大。"},{"word":"respective","structure":"Latin respectivus + English adjective use","meaning":"belonging separately to each","meaningCN":"分别属于各个的","example":"They returned to their respective homes.","exampleCN":"他们各自回到自己的家。"},{"word":"respectively","structure":"respective + -ly (manner adverb)","meaning":"in the order already named","meaningCN":"按已列出的顺序","example":"The first and second prizes went to Lee and Park respectively.","exampleCN":"一等奖和二等奖分别颁给李和朴。"},{"word":"irrespective","structure":"ir- (not) + respective","meaning":"without regard to something","meaningCN":"不论；不顾","example":"All applicants are treated equally, irrespective of age.","exampleCN":"所有申请者一律平等，不论年龄。"},{"word":"respectful","structure":"respect + -ful (full of)","meaning":"showing polite regard","meaningCN":"恭敬的；表示尊重的","example":"The students were respectful during the ceremony.","exampleCN":"典礼期间学生们很恭敬。"},{"word":"disrespect","structure":"dis- (not) + respect","meaning":"lack of respect, or to show it","meaningCN":"不尊重；失礼","example":"He felt the remark was a disrespect to his team.","exampleCN":"他觉得那番话是对他团队的不尊重。"},{"word":"spec","structure":"shortening of specification","meaning":"a detailed requirement or description","meaningCN":"规格；详细说明","example":"The parts were built to spec.","exampleCN":"这些零件按规格制造。"}],"latinEntries":[{"word":"specere","structure":"Latin verb","meaning":"to look, observe","meaningCN":"看；观察"},{"word":"respicere","structure":"re- + specere","meaning":"to look back at, regard","meaningCN":"回头看；顾及"},{"word":"respectivus","structure":"Latin adjective from respicere","meaning":"having reference to","meaningCN":"与……相关的；参照……的"}]}},{"word":"restoration","ipa_uk":"/ˌrestəˈreɪʃn/","ipa_us":"/ˌrestəˈreɪʃən/","definition_zh":"修复；恢复；归还；复辟；康复；生态修复；修复后的版本","definition_en":"the act of bringing something back to a former condition, or the result of that work","core_image":"老教堂的彩窗被拆下平放在木架上，工人用镊子把碎成十七块的蓝色玻璃一片片拼回原位。","scene":"修复师在灯下把碎裂的彩窗玻璃一片片拼合，半年后那扇窗又能像一百年前那样透进蓝光。The restorer pieced the broken stained glass together, and the restoration brought the window back to its original state.","sceneCN":"这里 restoration 是“对受损建筑或艺术品的修复”（第 1 个义项）；句意：这扇彩窗被修复回原貌。","pos":[{"tag":"n.","zh":"修复；恢复；归还；复辟；康复"}],"collocations":[{"phrase":"restoration work","zh":"修复工作"},{"phrase":"a restoration of order","zh":"秩序的恢复"},{"phrase":"the Restoration period","zh":"王政复辟时期"},{"phrase":"ecological restoration","zh":"生态修复"},{"phrase":"restoration of property","zh":"财产归还"},{"phrase":"a full restoration","zh":"全面修复"}],"forms":[{"label":"单数","form":"restoration"},{"label":"复数","form":"restorations"},{"label":"动词形式","form":"restore"},{"label":"形容词形式","form":"restorative"},{"label":"施事名词","form":"restorer"}],"derivatives":[{"word":"restore","pos":"v.","zh":"修复；恢复；归还"},{"word":"restorative","pos":"adj./n.","zh":"恢复健康的；补品"},{"word":"restorer","pos":"n.","zh":"修复者；修复师"},{"word":"restorable","pos":"adj.","zh":"可修复的"}],"senses":[{"no":"01","title":"Repairing a damaged thing","titleCN":"修复：把受损之物修回原貌","definition":"the work of repairing a building, painting, or object so that it returns to an earlier condition","definitionCN":"修复建筑、绘画或器物，使其回到较早状态的工作","example":"The restoration of the ceiling took seven years and three teams.","exampleCN":"天花板的修复花了七年、换了三支队伍。","why":"Restoration aims at a former state, not a new one; the standard is the building as it once was, reconstructed from evidence.","whyCN":"修复瞄准的是旧状态而非新状态；标准是建筑曾经的样子，并依据证据把它重新造出。"},{"no":"02","title":"Bringing order back","titleCN":"恢复：让秩序与制度回到原状","definition":"the act of bringing a system, peace, or lawful order back into effect","definitionCN":"使制度、和平或合法秩序重新生效的行为","example":"The new government promised the restoration of public services.","exampleCN":"新政府承诺恢复公共服务。","why":"What is restored here is not matter but arrangement; the pieces still exist, and the task is to reattach them.","whyCN":"这里修复的不是物质而是秩序；各个部件仍在，任务是把它们重新接上。"},{"no":"03","title":"Giving back what was taken","titleCN":"归还：把拿走之物送回原主","definition":"the return of property, rights, or territory to the person or group that owned it","definitionCN":"把财产、权利或领土归还给原先拥有的人或群体","example":"The treaty provided for the restoration of the seized archives.","exampleCN":"条约规定归还被查扣的档案。","why":"The Latin verb could mean to give back; restoration is the undoing of a taking rather than the mending of a break.","whyCN":"拉丁动词也有“归还”义；此义是撤销一次夺取，而不是修补一次破损。"},{"no":"04","title":"A dynasty back on the throne","titleCN":"复辟：旧王朝或旧政权重新掌权","definition":"the return of a monarchy or former regime to power","definitionCN":"君主制或旧政权重新掌权","example":"The Restoration of 1660 brought Charles II back to London.","exampleCN":"一六六〇年的王政复辟使查理二世重返伦敦。","why":"A political order is treated as a thing that can be put back; the word lends the past a shape that can be reinstalled.","whyCN":"政治秩序被当成一件可以放回原处的东西；这个词把过去赋予一种可以重新安装的形状。"},{"no":"05","title":"Strength coming back","titleCN":"康复：体力与健康的恢复","definition":"the recovery of health, strength, or normal function after illness or exhaustion","definitionCN":"疾病或耗竭之后健康、体力或正常功能的恢复","example":"Rest and good food brought about a slow restoration of his strength.","exampleCN":"休息与良好的饮食使他的体力慢慢恢复。","why":"A body out of order is pictured as a damaged object, and its recovery as repair to the original working condition.","whyCN":"失调的身体被想象成受损的器物，康复则被想象为修回原来的运转状态。"},{"no":"06","title":"Healing a landscape","titleCN":"生态修复：让退化的生态系统恢复功能","definition":"the practice of helping a degraded ecosystem recover its structure, species, and functions","definitionCN":"帮助退化的生态系统恢复结构、物种与功能的实践","example":"The wetland restoration reconnected the river to its floodplain.","exampleCN":"湿地修复把河流重新接到它的泛滥平原。","why":"Ecologists borrow the word because a damaged marsh is treated as a broken system whose original functions can be rebuilt.","whyCN":"生态学家借用这个词，因为受损的沼泽被当作一个坏掉的系统，其原有功能可以被重建。"},{"no":"07","title":"The restored version","titleCN":"修复版本：修复工作产出的成品","definition":"a version of a film, recording, or text produced by repair and cleaning","definitionCN":"经修复与清理后产出的影片、录音或文本版本","example":"The restoration adds twelve minutes cut from the original release.","exampleCN":"这个修复版本多出十二分钟原发行时被剪掉的片段。","why":"Here the noun names the product rather than the process; the work becomes a thing that can be screened or sold.","whyCN":"这里名词命名的是成品而非过程；修复工作变成了一件可以放映或出售的东西。"},{"no":"08","title":"Recovering lost data","titleCN":"恢复：从损坏介质中取回数据","definition":"the retrieval of data or files from damaged or deleted storage","definitionCN":"从损坏或被删除的存储中取回数据或文件","example":"The restoration recovered most photographs from the failed drive.","exampleCN":"这次数据恢复从故障硬盘中取回了大部分照片。","why":"Digital recovery repeats the old pattern: something lost is brought back into use by patient reconstruction.","whyCN":"数字恢复重复了旧的模式：失去之物通过耐心重建被带回可用状态。"}],"etymology":{"intro":{"en":"Restoration is restore plus -ation. Restore comes from Latin restaurare, to renew or rebuild, whose second element is of uncertain origin.","cn":"restoration 由 restore 加 -ation 构成。restore 出自拉丁语 restaurare“更新、重建”，其第二个成分的来源并不确定。"},"items":[{"era":"LATIN restaurare","en":"Restaurare meant to rebuild, repair, or renew. It is recorded in Roman use for restoring buildings and institutions.","cn":"restaurare 意为重建、修理、更新。罗马文献用它指修复建筑与制度。"},{"era":"LATIN -staurare","en":"The element after re- is generally thought to come from a root meaning to stand, but its exact formation is uncertain.","cn":"re- 之后的成分一般被认为来自表示“站立”的词根，但其确切构词来源不确定。"},{"era":"LATIN instaurare","en":"Instaurare, to set up or establish, shares this element, which supports the reading of a standing structure put back in place.","cn":"instaurare“设立、建立”共享这一成分，支持“把立着的结构放回原处”这一理解。"},{"era":"FRENCH restaurer","en":"Old French restaurer carried the architectural and medical senses into English: rebuilding a fabric and rebuilding a body.","cn":"古法语 restaurer 把建筑与医学两义带入英语：重建建筑物，也重建身体。"},{"era":"ENGLISH restore (14th c.)","en":"English restore took on the added sense of giving back property, which the Latin verb only occasionally carried.","cn":"英语 restore 增加了“归还财产”义，而拉丁动词只是偶尔带有此义。"},{"era":"ENGLISH -ation","en":"The Latin suffix -ationem names an action or its result, so restoration can name either the work or the finished version.","cn":"拉丁后缀 -ationem 命名动作或其结果，因此 restoration 既可指工作，也可指修成的版本。"}]},"similar":{"note":{"en":"The first group is the restore family, separated by word class; the second compares words for repair, renewal, and recovery.","cn":"第一组是 restore 词族，按词类区分；第二组比较表示修理、更新与恢复的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"restore","ipa":"/rɪˈstɔː(r)/","tag":"verb","definition":"to repair, bring back, or return something. It names the action.","definitionCN":"修复、使恢复或归还；命名的是动作。"},{"word":"restoration","ipa":"/ˌrestəˈreɪʃn/","tag":"noun","definition":"the act or result of restoring. It can name the process or the restored version.","definitionCN":"修复的行为或结果；既可指过程，也可指修复版本。"},{"word":"restorative","ipa":"/rɪˈstɒrətɪv/","tag":"adjective or noun","definition":"having the power to restore health or strength.","definitionCN":"有恢复健康或体力作用的。"},{"word":"restorer","ipa":"/rɪˈstɔːrə(r)/","tag":"person noun","definition":"a person who repairs buildings, paintings, or furniture.","definitionCN":"修复建筑、绘画或家具的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"renovation","ipa":"/ˌrenəˈveɪʃn/","tag":"noun","definition":"the work of making a building new again, often with modern changes. It permits improvement.","definitionCN":"使建筑重新变新，常含现代化改造；允许改良。"},{"word":"reconstruction","ipa":"/ˌriːkənˈstrʌkʃn/","tag":"noun","definition":"the rebuilding of something destroyed, often from evidence or fragments.","definitionCN":"重建被毁之物，常依据证据或残片。"},{"word":"recovery","ipa":"/rɪˈkʌvəri/","tag":"noun","definition":"the return to a normal state after loss, illness, or failure. It stresses the process of getting well.","definitionCN":"在失去、患病或失败后回到正常状态；强调好转过程。"},{"word":"repair","ipa":"/rɪˈpeə(r)/","tag":"noun","definition":"the mending of something broken so that it works again. It stresses function over historical accuracy.","definitionCN":"修补破损之物使其重新可用；强调功能，而非历史准确性。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: restore plus -ation. The second element of the Latin verb is uncertain, so no invented root is offered.","cn":"只用真实成分：restore 加 -ation。该拉丁动词的第二个成分来源不确定，因此不编造词根。"},"normal":[{"en":"Restore plus ation: the work of putting something back as it was.","cn":"restore 加 ation：把某物放回原样的工作。"},{"en":"A restored window lets in light the way it did a century ago.","cn":"修好的窗户，让光像一百年前那样透进来。"},{"en":"Restoring order is reattaching pieces that still exist.","cn":"恢复秩序，就是把仍在的部件重新接上。"},{"en":"Restoring archives is giving back, not mending.","cn":"归还档案是物归原主，不是修补。"},{"en":"Wetland restoration treats a marsh like a broken machine.","cn":"湿地修复把沼泽当成一台坏掉的机器。"}],"abstract":[{"en":"Every restoration is also an interpretation: someone decides which past state counts as the real one.","cn":"每次修复同时也是一次解释：总有人决定哪个过去才算“真正的原貌”。"},{"en":"To restore is to admit that the present version is not acceptable.","cn":"要修复，就得承认眼前的版本不可接受。"},{"en":"Restored objects carry two dates at once: the year they were made and the year they were saved.","cn":"被修复的物件同时带着两个年份：制成之年与获救之年。"}]},"examples":[{"en":"The restoration of the mosaic revealed colours that had been hidden under soot for centuries.","cn":"马赛克镶嵌画的修复显露出被烟灰掩埋数百年的色彩。"},{"en":"After the flood, the restoration of the railway took two years.","cn":"洪水过后，铁路的修复花了两年。"},{"en":"The film's restoration was based on three surviving prints.","cn":"这部影片的修复依据三份幸存的拷贝。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（重新）+ store（储存、存放）——把旧样子重新存回去，就是修复。","word":"restoration"},"root":"由 restore（修复、恢复、归还）加 -ation（名词后缀）构成；restore 出自拉丁语 restaurare“重建、更新”，该词第二个成分来源不确定，本义为“使某物回到原有状态的行为或成果”。","sensesIntro":{"en":"Eight senses of restoration, all circling one idea: an earlier condition is brought back. What returns may be a building, an order, a piece of property, a dynasty, a body's strength, an ecosystem, a cleaned film, or lost data.","cn":"restoration 的八个义项都围绕一个观念：让较早的状态回来。回来的可以是建筑、秩序、财产、王朝、体力、生态系统、修复后的影片，或丢失的数据。"},"semanticMap":{"core":{"en":"CORE IMAGE: stained glass laid flat on trestles, seventeen blue shards being fitted back into place under a lamp.","cn":"核心意象：彩窗玻璃平放在木架上，十七块蓝色碎片在灯下被一片片放回原位。"},"chain":["LATIN RESTAURARE = TO REBUILD","UNCERTAIN -STAURARE ELEMENT","FRENCH RESTAURER = TO REBUILD","ENGLISH RESTORE = TO BRING BACK","SUFFIX -ATION = ACT OR RESULT","RESTORATION = THE BRINGING BACK"],"branches":[{"senses":"S1 · S7","en":"MATERIAL REPAIR: a building or artwork mended, and the cleaned version that results.","cn":"物质修复：被修好的建筑或艺术品，以及由此产生的清理版本。"},{"senses":"S2 · S4","en":"POLITICAL ORDER PUT BACK: public order re-established, and a dynasty returned to power.","cn":"政治秩序放回原处：公共秩序重建，王朝重新掌权。"},{"senses":"S3","en":"THE UNDOING OF A TAKING: property and archives returned to their owners.","cn":"撤销一次夺取：财产与档案物归原主。"},{"senses":"S5","en":"THE BODY REPAIRED: health and strength slowly regained.","cn":"身体被修好：健康与体力慢慢恢复。"},{"senses":"S6 · S8","en":"SYSTEMS RECOVERED: a degraded ecosystem and a failed disk both restored to function.","cn":"系统恢复：退化的生态系统与故障硬盘都被恢复到可用状态。"}]},"affixes":{"intro":{"en":"Restoration is restore plus -ation. The family includes restorative and restorer, with -ative marking what strengthens and -er marking the person.","cn":"restoration 由 restore 加 -ation 构成。词族包括 restorative 与 restorer，其中 -ative 标记能增强之物，-er 标记人。"},"latinIntro":{"en":"The Latin base is restaurare, with instaurare as a relative. The second element is of uncertain origin, so only the secure parts are labelled.","cn":"拉丁词基是 restaurare，instaurare 为同族词。第二个成分来源不确定，因此只标注可靠的部分。"},"items":[{"word":"restaurare","structure":"Latin verb (re- + uncertain element)","meaning":"to rebuild, renew, restore","meaningCN":"重建；更新；修复","example":"Latin inscriptions record the restaurare of temples after fires.","exampleCN":"拉丁铭文记载火灾之后对神庙的修复。"},{"word":"instaurare","structure":"Latin verb sharing the -staurare element","meaning":"to set up, establish","meaningCN":"设立；建立","example":"The related verb appears in discussions of founding a festival.","exampleCN":"这个相关动词出现在关于创立节庆的讨论中。"},{"word":"restore","structure":"Old French restaurer < Latin restaurare","meaning":"to repair, bring back, or give back","meaningCN":"修复；使恢复；归还","example":"Workers restored the facade stone by stone.","exampleCN":"工人一块石头一块石头地修复了立面。"},{"word":"restoration","structure":"restore + -ation (action or result)","meaning":"the act or result of bringing something back","meaningCN":"使某物恢复的行为或结果","example":"The restoration returned the hall to its 1890 appearance.","exampleCN":"修复使大厅恢复到一八九〇年的样子。"},{"word":"restorative","structure":"restore + -ative (serving to)","meaning":"able to restore health or strength","meaningCN":"有恢复健康或体力作用的","example":"A hot meal proved restorative after the long walk.","exampleCN":"长途步行后，一顿热饭很能恢复体力。"},{"word":"restorer","structure":"restore + -er (person)","meaning":"a person who repairs old buildings or artworks","meaningCN":"修复古建筑或艺术品的人","example":"The restorer worked with a microscope and a scalpel.","exampleCN":"修复师用显微镜和解剖刀工作。"},{"word":"restorable","structure":"restore + -able (able to be)","meaning":"able to be repaired or brought back","meaningCN":"可修复的；可恢复的","example":"The painting was damaged but still restorable.","exampleCN":"这幅画受损，但仍可修复。"},{"word":"restorationist","structure":"restoration + -ist (person or advocate)","meaning":"a person who wants an earlier state of things brought back","meaningCN":"主张恢复旧制度的人","example":"Restorationists argued for the old voting rules.","exampleCN":"复古派主张恢复旧的投票规则。"},{"word":"non-restoration","structure":"non- (not) + restoration","meaning":"an approach that refuses to rebuild an earlier state","meaningCN":"不修复、不复原的做法","example":"The architects chose non-restoration and left the ruin visible.","exampleCN":"建筑师选择不复原，让废墟保持可见。"}],"latinEntries":[{"word":"restaurare","structure":"Latin verb","meaning":"to rebuild, renew","meaningCN":"重建；更新"},{"word":"instaurare","structure":"Latin verb, related formation","meaning":"to set up, establish","meaningCN":"设立；建立"},{"word":"-ationem","structure":"Latin noun suffix","meaning":"action or result","meaningCN":"动作或其结果"}]}},{"word":"restriction","ipa_uk":"/rɪˈstrɪkʃn/","ipa_us":"/rɪˈstrɪkʃən/","definition_zh":"限制；限制规定；受限状态；限制条件；限制酶；自我克制；约束","definition_en":"a rule or condition that limits what someone or something may do","core_image":"一条粗绳把一辆货车的轮子与站台柱绑在一起，绳子不长，车只能在一小块地面内挪动。","scene":"码头管理员用一条短绳把货车的一侧轮子系在柱子上，说司机只能在划定的这块区域里装卸。The dock manager tied one wheel to a post with a short rope, a restriction that kept the truck inside the marked loading area.","sceneCN":"这里 restriction 是“对行动范围的限制规定”（第 1 个义项）；句意：车辆只能在被允许的小范围内作业。","pos":[{"tag":"n.","zh":"限制；限制规定；约束条件"}],"collocations":[{"phrase":"travel restrictions","zh":"出行限制"},{"phrase":"impose restrictions on","zh":"对……施加限制"},{"phrase":"without restriction","zh":"不受限制地"},{"phrase":"restriction enzyme","zh":"限制酶"},{"phrase":"usage restrictions","zh":"使用限制"},{"phrase":"lift restrictions","zh":"解除限制"}],"forms":[{"label":"单数","form":"restriction"},{"label":"复数","form":"restrictions"},{"label":"动词形式","form":"restrict"},{"label":"形容词形式","form":"restrictive"}],"derivatives":[{"word":"restrict","pos":"v.","zh":"限制；约束"},{"word":"restrictive","pos":"adj.","zh":"限制性的"},{"word":"restricted","pos":"adj.","zh":"受限制的"},{"word":"restrictively","pos":"adv.","zh":"以限制的方式"}],"senses":[{"no":"01","title":"An official limit","titleCN":"限制规定：官方划出的行为边界","definition":"a rule made by an authority that limits what people may do","definitionCN":"由权威制定、限制人们行为的规则","example":"The city imposed water restrictions during the drought.","exampleCN":"干旱期间，这座城市实施了用水限制。","why":"Restriction comes from restringere, to bind back; a rule binds conduct the way a rope binds a wheel.","whyCN":"restriction 出自 restringere“绑回”；规则约束行为，就像绳子约束车轮。"},{"no":"02","title":"The act of limiting","titleCN":"限制行为：把范围收窄这一动作","definition":"the act of keeping something within limits or reducing its scope","definitionCN":"把某物保持在限度内或缩小其范围的行为","example":"The restriction of imports protected local producers.","exampleCN":"对进口的限制保护了本地生产者。","why":"The noun can name the act itself, not only the rule it produces; -tion covers both the doing and the thing done.","whyCN":"这个名词可以命名动作本身，而不只是它产生的规则；-tion 同时覆盖“做”与“所做之物”。"},{"no":"03","title":"Living under limits","titleCN":"受限状态：处在被限制的情形中","definition":"the state of being confined or limited in movement, access, or activity","definitionCN":"在行动、进入或活动方面受到约束的状态","example":"The patients were kept under restriction for a week.","exampleCN":"病人们被限制了一周。","why":"Here the word describes a condition rather than a rule; the person is inside the boundary that someone else drew.","whyCN":"这里描述的是状态而非规则；人被放在别人画好的边界之内。"},{"no":"04","title":"A condition on use","titleCN":"使用限制：附着在物品上的条件","definition":"a condition attached to the use, sale, or transfer of property or data","definitionCN":"附在财产或数据的使用、出售或转让上的条件","example":"The deed carries a restriction against commercial building.","exampleCN":"这份地契附有禁止商业建筑的限制。","why":"Rights come bundled with limits, and a restriction is the clause that keeps a right from expanding.","whyCN":"权利总与限度捆在一起，限制条款就是防止某项权利扩张的那一条。"},{"no":"05","title":"A cutting enzyme","titleCN":"限制酶：在特定序列处切开核酸的酶","definition":"in molecular biology, an enzyme that cuts DNA at a specific recognition sequence","definitionCN":"分子生物学中，在特定识别序列处切开核酸的酶","example":"The lab used a restriction enzyme to cut the plasmid in two.","exampleCN":"实验室用限制酶把质粒切成两段。","why":"The enzyme restricts a virus's ability to spread by cutting its DNA, so the name came from the defence it gives bacteria.","whyCN":"这种酶通过切断病毒的核酸来限制其扩散，名称源自它给细菌提供的防御。"},{"no":"06","title":"A clause in a contract","titleCN":"限制条款：合同中对一方的约束约定","definition":"a contractual term that limits what a party may do, such as a non-compete clause","definitionCN":"合同中对一方行为加以约束的条款，如竞业禁止条款","example":"The contract includes a restriction on working for rivals.","exampleCN":"合同包含为竞争对手工作的限制条款。","why":"Contract law turns a promise into a fence; the restriction states where the party may not walk.","whyCN":"合同法把承诺变成一道栅栏；限制条款说明当事人不可以走到哪里。"},{"no":"07","title":"Holding oneself back","titleCN":"自我克制：主动给自己设限","definition":"the practice of deliberately limiting one's own consumption, speech, or behaviour","definitionCN":"有意限制自己的消费、言语或行为","example":"He followed a voluntary restriction on sugar and salt.","exampleCN":"他自愿限制糖和盐的摄入。","why":"The binding rope is held by the person being bound; self-restriction is a boundary kept from the inside.","whyCN":"绑人的绳子握在被绑者自己手里；自我限制是一条从内侧守住的边界。"},{"no":"08","title":"A function confined to a subset","titleCN":"约束：数学中把函数限定在子集上","definition":"in mathematics, a function considered only on a smaller domain","definitionCN":"数学中只在较小定义域上考虑的函数","example":"The restriction of the function to positive numbers is strictly increasing.","exampleCN":"该函数在正数范围内的约束严格递增。","why":"Mathematicians borrow the everyday word because a function is narrowed to a smaller domain without changing its rule.","whyCN":"数学家借用日常词，因为函数只是被收窄到较小定义域，规则本身没有改变。"}],"etymology":{"intro":{"en":"Restriction is restrict plus -ion. Restrict comes from Latin restringere, to bind back, from re-, back, and stringere, to draw tight.","cn":"restriction 由 restrict 加 -ion 构成。restrict 出自拉丁语 restringere“绑回”，由 re-“向后”与 stringere“拉紧”组成。"},"items":[{"era":"LATIN stringere","en":"Stringere meant to draw tight, to bind, or to graze the surface. The image is a cord pulled until it holds.","cn":"stringere 意为拉紧、绑住，或擦过表面。其形象是一根绳子被拉到绷紧为止。"},{"era":"LATIN restringere","en":"Restringere added re-, back: to bind back, restrain, or confine within limits.","cn":"restringere 加上 re-“向后”：绑回、约束、限制在一定范围内。"},{"era":"LATIN restrictus","en":"The past participle restrictus meant bound tight or confined, and English drew both restrict and strict from this family.","cn":"过去分词 restrictus 意为绑紧的、受限制的，英语中的 restrict 与 strict 都出自这个词族。"},{"era":"ENGLISH restrict (15th c.)","en":"English restrict first meant to confine or keep within bounds, especially of movement and rights.","cn":"英语 restrict 最初意为限制或保持在界限内，尤指行动与权利。"},{"era":"ENGLISH restriction","en":"The noun added -ion and came to name both the act of limiting and the rule that results from it.","cn":"名词加 -ion 后，既指限制这一动作，也指由此产生的规则。"},{"era":"ENGLISH scientific use (20th c.)","en":"Twentieth-century biology gave the word a technical sense in restriction enzymes, named for the defence they give bacteria.","cn":"二十世纪的生物学在“限制酶”中赋予这个词技术含义，名称源自它们给细菌的防御。"}]},"similar":{"note":{"en":"The first group is the restrict family, separated by word class; the second compares words for limits, rules, and self-control.","cn":"第一组是 restrict 词族，按词类区分；第二组比较表示限度、规则与自我克制的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"restrict","ipa":"/rɪˈstrɪkt/","tag":"verb","definition":"to keep something within limits. It names the action.","definitionCN":"把某物限制在界限内；命名的是动作。"},{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","tag":"noun","definition":"a rule or condition that limits, or the state of being limited.","definitionCN":"限制行为的规则或条件，或受限制的状态。"},{"word":"restrictive","ipa":"/rɪˈstrɪktɪv/","tag":"adjective","definition":"acting as a limit, as in a restrictive clause.","definitionCN":"起限制作用的，如限制性从句。"},{"word":"restricted","ipa":"/rɪˈstrɪktɪd/","tag":"adjective","definition":"subject to limits, or available only to certain people.","definitionCN":"受限制的；仅对特定人开放的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"limitation","ipa":"/ˌlɪmɪˈteɪʃn/","tag":"noun","definition":"a boundary on what is possible or allowed. It is the broadest term and need not imply an authority.","definitionCN":"对可能或允许之事的界限；最宽泛，且不必含权威之意。"},{"word":"constraint","ipa":"/kənˈstreɪnt/","tag":"noun","definition":"something that forces or confines action, often external and impersonal. It stresses pressure.","definitionCN":"迫使或束缚行动之物，常为外部且非人为；强调压力。"},{"word":"ban","ipa":"/bæn/","tag":"noun","definition":"an official prohibition of something. It forbids rather than merely narrows.","definitionCN":"对某事的官方禁止；是完全禁止，而不只是收窄。"},{"word":"restraint","ipa":"/rɪˈstreɪnt/","tag":"noun","definition":"the quality of holding oneself back, or a device that holds something. It stresses self-control or physical holding.","definitionCN":"自我克制的品质，或固定某物的装置；强调自控或物理固定。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re- plus strict plus -ion. Strict comes from stringere, to draw tight, so a restriction is a tightened cord.","cn":"只用真实成分：re- 加 strict 再加 -ion。strict 出自 stringere“拉紧”，所以 restriction 就是一根被绷紧的绳。"},"normal":[{"en":"Re plus strict plus ion: a cord pulled back until movement stops.","cn":"re 加 strict 加 ion：一根被拉回去、直到动不了的绳。"},{"en":"Water restrictions mean the tap is tied, not broken.","cn":"用水限制意味着水龙头被绑住，而不是坏了。"},{"en":"A deed restriction keeps the land from growing shops.","cn":"地契限制让这块地长不出商铺。"},{"en":"A restriction enzyme cuts DNA at one exact address.","cn":"限制酶在 DNA 的某一个确切地址上切开。"},{"en":"Self-restriction is a fence you hold up yourself.","cn":"自我限制是一道你自己举着的栅栏。"}],"abstract":[{"en":"Every rule is a rope someone else tied, and its length is a political decision.","cn":"每条规则都是别人系的绳，绳有多长是一个政治决定。"},{"en":"Restrictions are easiest to see when they are lifted.","cn":"限制在解除的那一刻最容易被看见。"},{"en":"A boundary that nobody contests has stopped being visible as a boundary.","cn":"无人争辩的边界，已经不再作为边界被看见。"}]},"examples":[{"en":"The new restrictions limit each visitor to two hours in the archive.","cn":"新规定限制每位访客在档案馆停留两小时。"},{"en":"The lease places restrictions on subletting the flat.","cn":"这份租约对转租公寓设有约束条款。"},{"en":"Researchers mapped the gene by digesting it with restriction enzymes.","cn":"研究人员用限制酶把该基因切段后绘制图谱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（往回）+ strict（拉紧）——把范围往回拉紧，就是限制。","word":"restriction"},"root":"由 restrict（限制、约束）加 -ion（名词后缀）构成；restrict 出自拉丁语 restringere“绑回、拉紧”，由 re-“向后”与 stringere“拉紧”组成，本义为“把行为或范围绷紧在界限之内的规定或状态”。","sensesIntro":{"en":"Eight senses of restriction, all circling one idea: a cord drawn tight around something. The cord may be an official rule, an act of narrowing, a state of confinement, a condition on property, an enzyme that cuts DNA, a contract clause, self-imposed discipline, or a narrowed mathematical domain.","cn":"restriction 的八个义项都围绕一个观念：一根绷紧在某物周围的绳。这根绳可以是官方的规定、收窄的动作、被限制的状态、附在财产上的条件、切开核酸的酶、合同条款、自我施加的纪律，或被收窄的数学定义域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a short rope tying a lorry wheel to a platform post, so the vehicle can move only within a small square.","cn":"核心意象：一条短绳把货车车轮系在站台柱上，车只能在一小块方形地面内挪动。"},"chain":["LATIN STRINGERE = TO DRAW TIGHT","LATIN RESTRINGERE = TO BIND BACK","LATIN RESTRICTUS = CONFINED","ENGLISH RESTRICT = TO KEEP WITHIN LIMITS","SUFFIX -ION = ACT OR RESULT","RESTRICTION = THE TIGHTENED BOUNDARY"],"branches":[{"senses":"S1 · S3","en":"THE RULE AND THE STATE: an official limit and the condition of living inside it.","cn":"规则与状态：官方划定的限度，以及活在其内的处境。"},{"senses":"S2 · S4","en":"NARROWING AND CONDITIONING: the act of reducing scope, and a condition attached to a right.","cn":"收窄与附条件：缩小范围的动作，以及附在权利上的条件。"},{"senses":"S5","en":"A BIOLOGICAL CUT: an enzyme that stops a foreign sequence from spreading.","cn":"生物学上的切割：阻止外源序列扩散的酶。"},{"senses":"S6 · S8","en":"FORMAL CONFINEMENT: a contract clause and a function limited to a smaller domain.","cn":"形式化的约束：合同条款，以及限定在较小定义域上的函数。"},{"senses":"S7","en":"SELF-IMPOSED LIMIT: a cord held by the person who is bound.","cn":"自我施加的限度：由被绑者自己握住的绳。"}]},"affixes":{"intro":{"en":"Restriction is restrict plus -ion. The family includes restrictive, restricted, and unrestrained, with -ive describing the limiting force and -ed describing the limited thing.","cn":"restriction 由 restrict 加 -ion 构成。词族包括 restrictive、restricted 与 unrestrained，其中 -ive 描述限制的力量，-ed 描述被限制者。"},"latinIntro":{"en":"The Latin layers are stringere and restringere, with the participle restrictus. The suffix -ion reaches English through French from Latin -ionem.","cn":"拉丁层次是 stringere 与 restringere，以及分词 restrictus。后缀 -ion 经法语来自拉丁语 -ionem。"},"items":[{"word":"stringere","structure":"Latin verb (to draw tight)","meaning":"to bind, tighten, graze","meaningCN":"绑紧；拉紧；擦过","example":"The root appears in strict, strain, and stringent.","exampleCN":"这个词根出现在 strict（严格的）、strain（拉紧）与 stringent（严厉的）中。"},{"word":"restringere","structure":"re- (back) + stringere (to tighten)","meaning":"to bind back, restrain","meaningCN":"绑回；约束","example":"The Latin verb described reins pulled back to stop a horse.","exampleCN":"这个拉丁动词可描述拉回缰绳以止住马。"},{"word":"restrict","structure":"Latin restrictus, past participle of restringere","meaning":"to keep within limits","meaningCN":"限制在界限内","example":"The council restricted traffic on the old bridge.","exampleCN":"议会限制旧桥上的交通。"},{"word":"restriction","structure":"restrict + -ion (action or result)","meaning":"a limiting rule, act, or state","meaningCN":"限制性规则、动作或状态","example":"Height restrictions keep the view of the cathedral open.","exampleCN":"限高规定保住了大教堂的视线。"},{"word":"restrictive","structure":"restrict + -ive (tending to)","meaning":"serving to limit","meaningCN":"起限制作用的","example":"A restrictive clause narrows the noun it modifies.","exampleCN":"限制性从句收窄它所修饰的名词。"},{"word":"restricted","structure":"restrict + -ed (past participle)","meaning":"limited, or open only to certain people","meaningCN":"受限制的；仅对特定人开放的","example":"The files are restricted to senior staff.","exampleCN":"这些文件仅限高级职员查阅。"},{"word":"restrictionist","structure":"restriction + -ist (advocate)","meaning":"a person who favours limiting immigration or trade","meaningCN":"主张限制移民或贸易的人","example":"Restrictionists wanted quotas on imports.","exampleCN":"限制派希望对进口设配额。"},{"word":"unrestricted","structure":"un- (not) + restricted","meaning":"without limits","meaningCN":"不受限制的","example":"Unrestricted access made the archive impossible to secure.","exampleCN":"出入不受限制，使档案馆无法保全。"},{"word":"restrictively","structure":"restrictive + -ly (manner adverb)","meaning":"in a limiting manner","meaningCN":"以限制的方式","example":"The rule was applied restrictively to small firms only.","exampleCN":"这条规则只对小公司作了限制性适用。"}],"latinEntries":[{"word":"stringere","structure":"Latin verb","meaning":"to draw tight, bind","meaningCN":"拉紧；绑住"},{"word":"restringere","structure":"re- + stringere","meaning":"to bind back, restrain","meaningCN":"绑回；约束"},{"word":"restrictus","structure":"Past participle of restringere","meaning":"confined, bound tight","meaningCN":"受限制的；绑紧的"}]}},{"word":"retention","ipa_uk":"/rɪˈtenʃn/","ipa_us":"/rɪˈtenʃən/","definition_zh":"保留；保持；留存；记忆力；留任；潴留；保留金；所有权保留","definition_en":"the act of keeping or holding something, whether information, people, fluid, or legal title","core_image":"一只手掌半握着一把湿沙，指缝间漏下的少，掌心里留下的多。","scene":"培训师在课后一周又发了同一份小测，发现大多数人都还记得那些术语，说明这次培训的内容留住了。A week after the course, most trainees still remembered the terms, a sign of strong retention.","sceneCN":"这里 retention 是“所学内容的保持”（第 1 个义项）；句意：一周后多数人仍记得术语，说明知识被保持住了。","pos":[{"tag":"n.","zh":"保留；保持；留任；记忆力；潴留"}],"collocations":[{"phrase":"retention of information","zh":"信息的保持"},{"phrase":"staff retention","zh":"员工留任"},{"phrase":"water retention","zh":"水分保持；水潴留"},{"phrase":"records retention","zh":"记录留存"},{"phrase":"retention rate","zh":"留存率；保持率"},{"phrase":"retention money","zh":"保留金"}],"forms":[{"label":"单数","form":"retention"},{"label":"复数（少见）","form":"retentions"},{"label":"动词形式","form":"retain"},{"label":"形容词形式","form":"retentive"}],"derivatives":[{"word":"retain","pos":"v.","zh":"保留；保持；聘请"},{"word":"retentive","pos":"adj.","zh":"记性好的；有保持力的"},{"word":"retainer","pos":"n.","zh":"预付聘金；保持器"},{"word":"retentionist","pos":"n.","zh":"主张保留现状者"}],"senses":[{"no":"01","title":"Knowledge staying put","titleCN":"记忆保持：学过的东西留在脑中","definition":"the ability to keep information in memory over time","definitionCN":"把信息在记忆中保留一段时间的能力","example":"Spaced practice improves retention more than rereading does.","exampleCN":"间隔练习比反复阅读更能提高记忆保持。","why":"Retention comes from retinere, to hold back; what is learned is held, and forgetting is measured by how much escaped.","whyCN":"retention 出自 retinere“握紧不放”；学到的东西被握住，遗忘则用“漏掉了多少”来衡量。"},{"no":"02","title":"Keeping staff","titleCN":"员工留任：组织把人留住","definition":"the proportion of employees who stay with an organisation over a period","definitionCN":"一段时间内留在某机构的员工比例","example":"The company raised pay to improve staff retention.","exampleCN":"公司提高薪酬以改善员工留任率。","why":"An organisation holds people the way a hand holds sand; retention statistics count those who did not slip away.","whyCN":"组织留人如同手握沙；留任统计计的是没有漏走的人。"},{"no":"03","title":"Keeping records","titleCN":"记录留存：按法规把文件保存一段时间","definition":"the practice of keeping documents or data for a required period","definitionCN":"按规定期限保存文件或数据的做法","example":"The hospital follows a ten-year records retention policy.","exampleCN":"这家医院执行十年记录留存政策。","why":"Here the held object is paper or data, and the holding is an obligation rather than a memory.","whyCN":"这里被握住的是纸张或数据，而“握住”是一项义务，不是记忆。"},{"no":"04","title":"Fluid that will not leave","titleCN":"潴留：体液滞留体内","definition":"the abnormal accumulation of fluid in the body, as in water retention","definitionCN":"体内液体异常积聚，如水肿","example":"Swelling in her ankles suggested fluid retention.","exampleCN":"她脚踝肿胀，提示体液潴留。","why":"In medicine the body fails to let go of what it should release; the word keeps its physical sense of holding back.","whyCN":"在医学中，身体没能放走本该排出的东西；这个词保留了“拦握不放”的物理义。"},{"no":"05","title":"Soil and materials holding water","titleCN":"保水能力：土壤或材料留住水分","definition":"the capacity of a material or soil to hold water or nutrients","definitionCN":"材料或土壤保持水分或养分的能力","example":"Clay has high water retention but poor drainage.","exampleCN":"黏土保水性强，但排水差。","why":"Agronomy measures retention as a capacity, so the noun becomes a quantity that can be tested.","whyCN":"农学把保持力当作一种可测量的容量，于是这个名词变成一个可检测的量。"},{"no":"06","title":"Money held back","titleCN":"保留金：验收前扣下的一部分款项","definition":"a sum withheld from a payment until work is completed or defects are fixed","definitionCN":"在完工或缺陷修复前从付款中扣下的一笔钱","example":"The contract withholds five percent as retention for a year.","exampleCN":"合同扣留百分之五作为为期一年的保留金。","why":"Construction retains money as leverage; the withheld sum holds the contractor to the promise.","whyCN":"建筑业扣款作为筹码；被扣下的钱把承包商拴在承诺上。"},{"no":"07","title":"Holding heat or flavour","titleCN":"保持：热量、颜色或风味的留存","definition":"the ability of something to keep heat, colour, moisture, or flavour","definitionCN":"某物保持热量、颜色、水分或风味的能力","example":"The clay pot's heat retention keeps the stew warm for hours.","exampleCN":"砂锅的保温性让炖菜保温数小时。","why":"The word applies to any quality that would otherwise escape; a good vessel is one that lets little out.","whyCN":"这个词适用于任何本会逸散的性质；好的容器就是让流失很少的容器。"},{"no":"08","title":"Title kept until payment","titleCN":"所有权保留：货款付清前卖方仍握所有权","definition":"a legal arrangement in which a seller keeps ownership of goods until the buyer pays in full","definitionCN":"卖方在买方全额付款前保留货物所有权的法律安排","example":"The supplier relied on retention of title when the buyer went bankrupt.","exampleCN":"买方破产时，供应商援引所有权保留条款。","why":"Ownership itself is held back as security, so the seller keeps a legal grip on goods already delivered.","whyCN":"所有权本身被扣作担保，卖方因此对已交付的货物保持法律上的抓握。"}],"etymology":{"intro":{"en":"Retention is retain plus -tion. Retain comes from Latin retinere, to hold back, from re-, back, and tenere, to hold.","cn":"retention 由 retain 加 -tion 构成。retain 出自拉丁语 retinere“握回、扣住”，由 re-“向后”与 tenere“握持”组成。"},"items":[{"era":"LATIN tenere","en":"Tenere meant to hold or keep. The root underlies tenant, contain, maintain, and retain.","cn":"tenere 意为握住、保持。这个词根支撑了 tenant、contain、maintain 与 retain。"},{"era":"LATIN retinere","en":"Retinere added re-, back, giving the sense of holding something back or keeping it from escaping.","cn":"retinere 加上 re-“向后”，得到“拦握某物、不让它跑掉”的意思。"},{"era":"LATIN retentio","en":"Retentio named the act of holding back, and in medical writing the retaining of fluid in the body.","cn":"retentio 指拦握不放的行为，在医学文献中也指体液滞留体内。"},{"era":"FRENCH retencion","en":"Old French carried the noun into English with both the mental sense of keeping knowledge and the legal sense of keeping possession.","cn":"古法语把这个名词带入英语，兼有“把知识留住”的心理义与“保有占有”的法律义。"},{"era":"ENGLISH retain","en":"The English verb retain covers keeping a fact, a right, a service, or a person, which prepares the broad noun.","cn":"英语动词 retain 覆盖保留事实、权利、服务或人员，这为宽泛的名词义铺路。"},{"era":"ENGLISH retention","en":"Retention later specialized in education as memory retention, in business as staff retention, and in law as retention of title.","cn":"retention 后来在教育中指记忆保持，在商业中指员工留任，在法律中指所有权保留。"}]},"similar":{"note":{"en":"The first group is the retain family, separated by word class; the second compares words for keeping, memory, and remaining.","cn":"第一组是 retain 词族，按词类区分；第二组比较表示保存、记忆与留下的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"retain","ipa":"/rɪˈteɪn/","tag":"verb","definition":"to keep something, or to employ a professional. It names the action.","definitionCN":"保留某物，或聘请专业人士；命名的是动作。"},{"word":"retention","ipa":"/rɪˈtenʃn/","tag":"noun","definition":"the act or capacity of keeping something.","definitionCN":"保留某物的行为或能力。"},{"word":"retentive","ipa":"/rɪˈtentɪv/","tag":"adjective","definition":"good at remembering or holding things.","definitionCN":"记性好的；有保持力的。"},{"word":"retainer","ipa":"/rɪˈteɪnə(r)/","tag":"noun","definition":"a fee paid to secure a professional's services, or a device that holds teeth in place.","definitionCN":"为确保专业服务而预付的费用，或保持牙齿位置的装置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"preservation","ipa":"/ˌprezəˈveɪʃn/","tag":"noun","definition":"keeping something in good condition over time, especially from decay. It stresses protection.","definitionCN":"使某物长期保持良好状态，尤指防止腐坏；强调保护。"},{"word":"memory","ipa":"/ˈmeməri/","tag":"noun","definition":"the faculty of recalling, or a particular recollection. It names the store rather than the holding.","definitionCN":"回忆的能力，或某段记忆；命名仓储，而非握持。"},{"word":"maintenance","ipa":"/ˈmeɪntənəns/","tag":"noun","definition":"the work of keeping something in working order. It stresses ongoing effort.","definitionCN":"使某物保持正常运转的工作；强调持续投入。"},{"word":"persistence","ipa":"/pəˈsɪstəns/","tag":"noun","definition":"continuing to exist or act despite difficulty. It stresses duration rather than deliberate keeping.","definitionCN":"遇难仍继续存在或行动；强调持续，而非有意保持。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re- plus tain plus -tion. The base tenere means to hold, so retention is the holding back of something that might escape.","cn":"只用真实成分：re- 加 tain 再加 -tion。词基 tenere 意为握住，所以 retention 是拦住可能跑掉之物。"},"normal":[{"en":"Re plus tain plus tion: hold it back, and keep holding.","cn":"re 加 tain 加 tion：拦住它，并且一直握着。"},{"en":"Retention of facts is measured by how much leaks out after a week.","cn":"事实的保持，用一周后漏掉多少来衡量。"},{"en":"Staff retention counts the people who did not slip away.","cn":"员工留任统计的是没有溜走的人。"},{"en":"Clay's water retention means the rain stays where the roots can reach.","cn":"黏土的保水性意味着雨水留在根系能够到的地方。"},{"en":"Retention of title keeps the goods legally in the seller's hand until the last payment.","cn":"所有权保留让货物在法律上一直握在卖方手里，直到最后一笔付款。"}],"abstract":[{"en":"What a system retains defines what it is; everything else was only passing through.","cn":"一个系统留下什么，就定义了它是什么；其余都只是路过。"},{"en":"Memory and money obey the same verb: both can be held back.","cn":"记忆与金钱服从同一个动词：两者都能被扣住不放。"},{"en":"Retention is always selective, and selection is always a judgement about value.","cn":"留存总是有选择的，而选择总是关于价值的一次判断。"}]},"examples":[{"en":"The course uses weekly quizzes to test retention rather than speed.","cn":"这门课用每周小测考查保持，而不是速度。"},{"en":"Poor retention of new nurses pushed the hospital to redesign shifts.","cn":"新护士留任率低，促使医院重新设计排班。"},{"en":"The dam's water retention capacity has fallen by a third after years of silt.","cn":"多年淤积之后，大坝的蓄水能力下降了三成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（往回）+ ten（握）+ tion——把东西握回来不放，就是保留。","word":"retention"},"root":"由 retain（保留、保持）加 -tion（名词后缀）构成；retain 出自拉丁语 retinere“握回、扣住”，由 re-“向后”与 tenere“握持”组成，本义为“把可能失去之物拦握不放的行为或能力”。","sensesIntro":{"en":"Eight senses of retention, all circling one idea: something that could leave is held. What is held may be knowledge, employees, records, fluid in the body, water in soil, money withheld, heat in a pot, or legal ownership of goods.","cn":"retention 的八个义项都围绕一个观念：本会离开的东西被握住了。被握住的可以是知识、员工、记录、体内液体、土壤水分、被扣下的款项、锅里的热量，或货物的法律所有权。"},"semanticMap":{"core":{"en":"CORE IMAGE: a half-closed hand around wet sand, little escaping between the fingers, most staying in the palm.","cn":"核心意象：半握的手掌兜住湿沙，指缝漏下的少，掌心留下的多。"},"chain":["LATIN TENERE = TO HOLD","LATIN RETINERE = TO HOLD BACK","LATIN RETENTIO = A HOLDING BACK","ENGLISH RETAIN = TO KEEP","SUFFIX -TION = ACT OR CAPACITY","RETENTION = THE KEEPING OF WHAT MIGHT GO"],"branches":[{"senses":"S1 · S2","en":"PEOPLE AND KNOWLEDGE: facts kept in memory and staff kept in an organisation.","cn":"人与知识：留在记忆里的事实，留在组织里的员工。"},{"senses":"S3 · S6","en":"FORMAL KEEPING: records held for a required period and money withheld until acceptance.","cn":"形式化的保存：按规定期限留存的记录，以及验收前扣下的款项。"},{"senses":"S4 · S7","en":"PHYSICAL HOLDING: fluid that stays in the body and heat that stays in a pot.","cn":"物理性的握持：滞留在体内的液体，留在锅里的热量。"},{"senses":"S5","en":"MEASURED CAPACITY: how much water soil or a material can keep.","cn":"可测容量：土壤或材料能保住多少水。"},{"senses":"S8","en":"LEGAL GRIP: ownership held back as security until payment is complete.","cn":"法律上的抓握：作为担保被扣留的所有权，直到付款完成。"}]},"affixes":{"intro":{"en":"Retention is retain plus -tion. The family includes retentive and retainer, with -ive marking the holding quality and -er marking the thing or fee that holds.","cn":"retention 由 retain 加 -tion 构成。词族包括 retentive 与 retainer，其中 -ive 标记保持的性质，-er 标记起保持作用之物或费用。"},"latinIntro":{"en":"The Latin base is tenere, extended in retinere and retentio. The same root appears in contain, maintain, and tenant.","cn":"拉丁词基是 tenere，在 retinere 与 retentio 中扩展。同一词根也出现在 contain、maintain 与 tenant 中。"},"items":[{"word":"tenere","structure":"Latin verb, second conjugation","meaning":"to hold, keep, grasp","meaningCN":"握住；保持；掌握","example":"The root appears in tenant, tenure, and contain.","exampleCN":"这个词根出现在 tenant（租户）、tenure（任期）与 contain（包含）中。"},{"word":"retinere","structure":"re- (back) + tenere (to hold)","meaning":"to hold back, keep, preserve","meaningCN":"拦握；保留；保存","example":"The Latin verb described a fortress retaining its garrison.","exampleCN":"这个拉丁动词可描述要塞留住驻军。"},{"word":"retain","structure":"Latin retinere through French","meaning":"to keep something or engage a professional","meaningCN":"保留某物；聘请专业人士","example":"The museum retains the original frames.","exampleCN":"博物馆保留着原来的画框。"},{"word":"retention","structure":"retain + -tion (action or capacity)","meaning":"the keeping of something that might be lost","meaningCN":"对可能失去之物的保留","example":"Retention of the old files is required by law.","exampleCN":"法律要求保留旧档案。"},{"word":"retentive","structure":"retain + -ive (tending to)","meaning":"good at holding or remembering","meaningCN":"有保持力的；记性好的","example":"She has a retentive memory for names.","exampleCN":"她记名字的记性很好。"},{"word":"retainer","structure":"retain + -er (thing or agent)","meaning":"a fee securing a professional, or a device that holds something in place","meaningCN":"预付聘金；保持装置","example":"The clinic pays a monthly retainer to the consultant.","exampleCN":"诊所每月向顾问支付聘金。"},{"word":"retentionist","structure":"retention + -ist (advocate)","meaning":"a person who wants to keep an existing arrangement","meaningCN":"主张保留现状的人","example":"Retentionists opposed the merger of the two schools.","exampleCN":"保留现状派反对两校合并。"},{"word":"non-retention","structure":"non- (not) + retention","meaning":"a policy of not keeping something","meaningCN":"不留存的做法","example":"Privacy law requires non-retention of unnecessary data.","exampleCN":"隐私法要求不留存不必要的数据。"},{"word":"retentional","structure":"retention + -al (relating to)","meaning":"relating to the keeping of something","meaningCN":"与保留有关的","example":"The study measured retentional gains after six months.","exampleCN":"这项研究测量了六个月后的保持增益。"}],"latinEntries":[{"word":"tenere","structure":"Latin verb","meaning":"to hold, keep","meaningCN":"握住；保持"},{"word":"retinere","structure":"re- + tenere","meaning":"to hold back, retain","meaningCN":"拦握；保留"},{"word":"retentio","structure":"Latin noun from retinere","meaning":"a holding back","meaningCN":"拦握；扣留"}]}},{"word":"revelation","ipa_uk":"/ˌriːvəˈleɪʃn/","ipa_us":"/ˌriːvəˈleɪʃən/","definition_zh":"揭露；启示；惊人发现；真相的揭示；披露；顿悟","definition_en":"a fact or truth made known, especially one that was hidden and comes as a surprise","core_image":"一块蒙布从雕像上滑落，原本藏在布下的裂纹与镀金在灯下同时露出来。","scene":"档案馆员掀开盖在旧地图上的布，观众这才看到地图背面还有一整幅手绘的海岸线。When the cloth was lifted, the hidden coastline on the back of the map came as a revelation.","sceneCN":"这里 revelation 是“被揭开而显露的事实”（第 1 个义项）；句意：布被掀开后，隐藏的图画才显露出来。","pos":[{"tag":"n.","zh":"揭露；启示；惊人发现；披露"}],"collocations":[{"phrase":"a startling revelation","zh":"令人震惊的揭露"},{"phrase":"divine revelation","zh":"神的启示"},{"phrase":"come as a revelation","zh":"让人恍然大悟"},{"phrase":"the revelation of evidence","zh":"证据的披露"},{"phrase":"a personal revelation","zh":"个人的顿悟"},{"phrase":"follow the revelations","zh":"在这些揭露之后"}],"forms":[{"label":"单数","form":"revelation"},{"label":"复数","form":"revelations"},{"label":"动词形式","form":"reveal"},{"label":"形容词形式","form":"revelatory"}],"derivatives":[{"word":"reveal","pos":"v.","zh":"揭示；显露；透露"},{"word":"revelatory","pos":"adj.","zh":"揭示性的；发人深省的"},{"word":"revealed","pos":"adj.","zh":"被揭示的"},{"word":"unrevealed","pos":"adj.","zh":"未被揭示的"}],"senses":[{"no":"01","title":"A hidden fact made known","titleCN":"揭露：原本藏着的事实被公开","definition":"a surprising fact that has been hidden and is now made known","definitionCN":"原本隐藏、如今被公开的令人意外的事实","example":"The letters contained a revelation about the company's early funding.","exampleCN":"这些信件揭露了该公司早期资金来源的一段内情。","why":"Revelation comes from revelare, to un-veil; what is revealed was covered, and the noun names both the lifting and the thing uncovered.","whyCN":"revelation 出自 revelare“揭开面纱”；被揭示之物原本被盖着，这个名词既指揭开动作，也指揭开后的东西。"},{"no":"02","title":"Truth given from above","titleCN":"启示：被认为来自神明的真理","definition":"in religion, a truth disclosed by a divine source rather than discovered by human reason","definitionCN":"宗教中由神圣来源而非人的理性所发现的真理","example":"The prophet described his vision as a revelation.","exampleCN":"这位先知把自己的异象描述为一次启示。","why":"The veil here is lifted by a power outside the human mind; revelation is knowledge one could not have reasoned to.","whyCN":"这里掀开面纱的是人心之外的力量；启示是人靠推理得不到的知识。"},{"no":"03","title":"The act of unveiling","titleCN":"揭示行为：把遮盖拿掉这一动作","definition":"the act of making something known that was previously concealed","definitionCN":"使原本隐蔽之事为人所知的行为","example":"The revelation of the documents changed the course of the trial.","exampleCN":"文件的披露改变了审判的走向。","why":"The noun can name the event rather than the content, so a revelation may be a moment in time as well as a fact.","whyCN":"这个名词可以命名事件而非内容，因此一次揭露既是一个时间点，也可以是一个事实。"},{"no":"04","title":"A sudden understanding","titleCN":"顿悟：心里忽然亮起来的一刻","definition":"a sudden moment of understanding that changes how one sees something","definitionCN":"忽然理解、并改变看法的时刻","example":"It came as a revelation that the two problems were the same problem.","exampleCN":"两个问题原来是同一个问题，这让人恍然大悟。","why":"What was hidden is inside the person rather than behind a cloth; the veil is ignorance, and it drops all at once.","whyCN":"被藏住的东西在人心里而不是布后；面纱是无知，而它一下子落下。"},{"no":"05","title":"The twist in a story","titleCN":"真相揭示：叙事中揭开的关键信息","definition":"the moment in a story when information is disclosed that reinterprets what came before","definitionCN":"故事中披露关键信息、使先前内容被重新理解的时刻","example":"The final revelation makes the narrator's earlier silence meaningful.","exampleCN":"最后的真相揭示让叙述者先前的沉默有了意义。","why":"A plot works by controlled concealment; revelation is the planned release of what the story was holding back.","whyCN":"情节靠有控制的隐瞒运作；真相揭示就是故事一直扣着的信息被按计划放出。"},{"no":"06","title":"A scandal brought to light","titleCN":"曝光：把丑闻摊到公众面前","definition":"the public exposure of wrongdoing that had been kept secret","definitionCN":"把被秘而不宣的不当行为公开曝光","example":"The revelations about the factory led to an inquiry.","exampleCN":"有关这家工厂的曝光引发了调查。","why":"Public revelation adds an audience: the fact was known to some, and the wrong lies in its having been kept from the rest.","whyCN":"公开揭露加上了受众：事实本为一些人所知，过错在于把它瞒住了其他人。"},{"no":"07","title":"Formal disclosure of information","titleCN":"披露：按程序把信息交由有关方面","definition":"the formal release of information to a court, regulator, or the public","definitionCN":"按程序把信息交给法院、监管机构或公众","example":"The revelation of the financial records was ordered by the court.","exampleCN":"法院下令披露这些财务记录。","why":"Institutions use the word for the lawful lifting of confidentiality, where timing and scope are prescribed.","whyCN":"机构用这个词指合法解除保密，其时机与范围都有规定。"},{"no":"08","title":"Something that opens the eyes","titleCN":"启示性体验：让人重新看世界的事物","definition":"an experience or work that changes one's perception of life or art","definitionCN":"改变人对生活或艺术看法的体验或作品","example":"Hearing the cellist play was a revelation to the young composer.","exampleCN":"听那位大提琴家演奏，对年轻作曲家来说是一次启示。","why":"The word can praise an encounter rather than report a fact; what is unveiled is a new way of seeing.","whyCN":"这个词可以赞美一次相遇，而不只是报告一个事实；被揭开的是新的观看方式。"}],"etymology":{"intro":{"en":"Revelation is reveal plus -ation. Reveal comes from Latin revelare, literally to un-veil, from re- as the opposite of, and velare, to cover, from velum, a veil.","cn":"revelation 由 reveal 加 -ation 构成。reveal 出自拉丁语 revelare，字面即“揭开面纱”，由表示相反义的 re- 与 velare“遮盖”组成，后者源自 velum“面纱”。"},"items":[{"era":"LATIN velum","en":"Velum meant a veil, a sail, or a cloth hung to conceal. The physical cloth is the base of the whole family.","cn":"velum 意为面纱、帆或用于遮挡的布。这块实物的布是整个词族的基础。"},{"era":"LATIN velare","en":"Velare meant to cover with a veil, and so to hide from view.","cn":"velare 意为用面纱覆盖，因而指遮住视线。"},{"era":"LATIN revelare","en":"Revelare joined re-, here meaning the opposite of the action, with velare: to remove the veil, hence to disclose.","cn":"revelare 把表示“相反动作”的 re- 与 velare 组合：去掉面纱，因而指揭露。"},{"era":"FRENCH reveler","en":"Old French reveler carried the sense of disclosing or making manifest, often in religious contexts.","cn":"古法语 reveler 带有“披露、使显明”的意思，常用于宗教语境。"},{"era":"ENGLISH reveal","en":"English reveal covers showing what is hidden, whether by a person, a document, or an event.","cn":"英语 reveal 涵盖把隐藏之物显示出来，无论施动者是人、文件还是事件。"},{"era":"ENGLISH -ation","en":"The Latin suffix -ationem names the action or its result, so revelation is both the unveiling and the thing unveiled.","cn":"拉丁后缀 -ationem 命名动作或其结果，因此 revelation 既是揭开的动作，也是被揭开之物。"}]},"similar":{"note":{"en":"The first group is the reveal family, separated by word class; the second compares words for disclosure, insight, and sacred truth.","cn":"第一组是 reveal 词族，按词类区分；第二组比较表示披露、洞见与神圣真理的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reveal","ipa":"/rɪˈviːl/","tag":"verb","definition":"to make something hidden visible or known. It names the action.","definitionCN":"使隐藏之物可见或为人所知；命名的是动作。"},{"word":"revelation","ipa":"/ˌriːvəˈleɪʃn/","tag":"noun","definition":"the act or content of unveiling, often with a sense of surprise.","definitionCN":"揭开的行为或内容，常带意外感。"},{"word":"revelatory","ipa":"/ˌriːvəˈleɪtəri/","tag":"adjective","definition":"serving to reveal something important.","definitionCN":"具有揭示重要内容作用的。"},{"word":"revealed","ipa":"/rɪˈviːld/","tag":"adjective","definition":"having been made known, as in revealed truth.","definitionCN":"已被揭示的，如“启示的真理”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disclosure","ipa":"/dɪsˈkləʊʒə(r)/","tag":"noun","definition":"the release of information, especially formally or legally. It stresses procedure rather than surprise.","definitionCN":"信息的公开，尤指正式或依法进行；强调程序，而非意外。"},{"word":"insight","ipa":"/ˈɪnsaɪt/","tag":"noun","definition":"a deep and accurate understanding of something. It stresses the mental grasp, not the source.","definitionCN":"对某物的深刻准确理解；强调心智把握，而非来源。"},{"word":"epiphany","ipa":"/ɪˈpɪfəni/","tag":"noun","definition":"a sudden flash of understanding, often with a sense of significance.","definitionCN":"忽然闪现的理解，常带重大意义感。"},{"word":"exposure","ipa":"/ɪkˈspəʊʒə(r)/","tag":"noun","definition":"the act of bringing wrongdoing to public notice, or being subjected to something harmful.","definitionCN":"把不当行为公之于众，或使人遭受有害影响。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re- plus veil plus -ation. Reveal is literally to un-veil, and the noun adds the result suffix.","cn":"只用真实成分：re- 加 veil 再加 -ation。reveal 字面就是“揭开面纱”，名词再加上结果后缀。"},"normal":[{"en":"Re plus veil plus ation: the cloth comes off, and what it hid is now a fact you must deal with.","cn":"re 加 veil 加 ation：布被拿掉，布下的东西成了必须面对的事实。"},{"en":"A revelation arrives with the sound of a cover being pulled away.","cn":"一次揭露到来时，像一块盖布被拉开的声音。"},{"en":"Divine revelation is a veil lifted from the other side.","cn":"神的启示，是从另一侧掀开的面纱。"},{"en":"The plot's final revelation makes the first chapter read differently.","cn":"情节最后的真相揭示，让第一章读起来完全不同。"},{"en":"A great concert can be a revelation to a young composer.","cn":"一场伟大的音乐会，对年轻作曲家可能是一次启示。"}],"abstract":[{"en":"Nothing can be revealed without something having first been concealed.","cn":"若没有先被隐藏，就谈不上被揭示。"},{"en":"Revelation redistributes knowledge, and knowledge is power, so every unveiling changes a balance.","cn":"揭露重新分配知识，而知识即权力，因此每次揭开都改变一处平衡。"},{"en":"The most unsettling revelations are the ones that were always in front of us.","cn":"最令人不安的揭露，往往是那些一直摆在眼前的东西。"}]},"examples":[{"en":"The diary's revelation that he had known all along changed every earlier judgement.","cn":"日记揭露他其实一直知情，这改变了此前所有的判断。"},{"en":"The report's revelations about safety checks forced the plant to close.","cn":"报告对安全检查的揭露迫使工厂关闭。"},{"en":"For the students, the microscope was a revelation: the pond water was full of life.","cn":"对学生来说，显微镜是一次启示：池水里满是生命。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（去掉）+ vel（面纱）——把面纱去掉，真相就露出来了。","word":"revelation"},"root":"由 reveal（揭示、显露）加 -ation（名词后缀）构成；reveal 出自拉丁语 revelare“揭开面纱”，由表示相反义的 re- 与 velare“遮盖”组成，后者源自 velum“面纱”，本义为“揭开遮盖后显露出来的事实或动作”。","sensesIntro":{"en":"Eight senses of revelation, all circling one idea: a covering is removed. What was covered may be a fact, a divine truth, a concealed document, one's own ignorance, a plot secret, a scandal, confidential records, or a way of seeing the world.","cn":"revelation 的八个义项都围绕一个观念：遮盖被取下。被盖住的可以是事实、神圣真理、被隐藏的文件、自己的无知、情节秘密、丑闻、机密记录，或一种看世界的方式。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cloth sliding off a statue, cracks and gilding appearing together under the lamp.","cn":"核心意象：一块布从雕像上滑落，裂纹与镀金在灯下同时露出来。"},"chain":["LATIN VELUM = VEIL","LATIN VELARE = TO COVER","LATIN REVELARE = TO UNVEIL","FRENCH REVELER = TO DISCLOSE","ENGLISH REVEAL = TO MAKE KNOWN","REVELATION = THE UNVEILING AND WHAT IS UNVEILED"],"branches":[{"senses":"S1 · S3","en":"THE FACT AND THE ACT: a hidden truth made public, and the moment of making it public.","cn":"事实与动作：被公开的隐藏真相，以及公开它的那个时刻。"},{"senses":"S2","en":"THE VEIL LIFTED FROM ABOVE: truth received rather than reasoned out.","cn":"面纱由上方掀开：被接受而非被推理得出的真理。"},{"senses":"S4 · S8","en":"THE VEIL INSIDE: an inner ignorance that suddenly drops, and an encounter that changes perception.","cn":"内侧的面纱：忽然落下的内在无知，以及改变感知的一次相遇。"},{"senses":"S5","en":"THE PLANNED RELEASE: a story's withheld information delivered at the chosen moment.","cn":"有计划的释放：故事扣住的信息在选定时刻交付。"},{"senses":"S6 · S7","en":"PUBLIC AND FORMAL EXPOSURE: a scandal brought into the open and records released under order.","cn":"公开与正式披露：丑闻被摊开，记录依命令交出。"}]},"affixes":{"intro":{"en":"Revelation is reveal plus -ation. The family includes revelatory and unrevealed, with -atory marking what serves to reveal and un- marking what stays hidden.","cn":"revelation 由 reveal 加 -ation 构成。词族包括 revelatory 与 unrevealed，其中 -atory 标记有助于揭示之物，un- 标记仍被隐藏者。"},"latinIntro":{"en":"The Latin layers are velum, velare, and revelare. The prefix re- here does not mean again but the undoing of the action.","cn":"拉丁层次是 velum、velare 与 revelare。这里的前缀 re- 不表示“再一次”，而表示动作的撤销。"},"items":[{"word":"velum","structure":"Latin noun (veil, cloth)","meaning":"a covering cloth","meaningCN":"遮盖用的布；面纱","example":"The Latin word also gives English veil and velum in anatomy.","exampleCN":"这个拉丁词也给出英语 veil（面纱）以及解剖学中的 velum（软腭）。"},{"word":"velare","structure":"Latin verb from velum","meaning":"to cover, to veil","meaningCN":"覆盖；遮住","example":"The verb described covering a statue before a festival.","exampleCN":"这个动词可描述节庆前把雕像遮起来。"},{"word":"reveal","structure":"Latin revelare through French reveler","meaning":"to uncover, disclose","meaningCN":"揭开；披露","example":"The scan revealed a crack beneath the paint.","exampleCN":"扫描显示颜料下面有一道裂缝。"},{"word":"revelation","structure":"reveal + -ation (action or result)","meaning":"the unveiling, or the thing unveiled","meaningCN":"揭开；被揭开之物","example":"The letters were a revelation to the biographer.","exampleCN":"这些信件对传记作者来说是一个重大发现。"},{"word":"revelatory","structure":"reveal + -atory (serving to)","meaning":"serving to disclose something important","meaningCN":"具有揭示作用的","example":"The interview was revelatory about his early years.","exampleCN":"这次访谈对他早年的经历很有揭示性。"},{"word":"revealed","structure":"reveal + -ed (past participle)","meaning":"having been made known","meaningCN":"已被揭示的","example":"Revealed preferences differ from what people say they want.","exampleCN":"显示出来的偏好与人们口头上说的并不相同。"},{"word":"unrevealed","structure":"un- (not) + revealed","meaning":"not yet made known","meaningCN":"尚未揭示的","example":"The cause of the fire remains unrevealed.","exampleCN":"火灾原因仍未公布。"},{"word":"revealing","structure":"reveal + -ing (adjective)","meaning":"making hidden things known","meaningCN":"揭示性的；透露内情的","example":"The minutes are revealing about how the vote was arranged.","exampleCN":"会议记录透露了投票是如何安排的。"},{"word":"veil","structure":"Old French veile < Latin velum","meaning":"a cloth worn or hung to conceal","meaningCN":"面纱；遮蔽布","example":"She lifted her veil at the altar.","exampleCN":"她在圣坛前掀起面纱。"}],"latinEntries":[{"word":"velum","structure":"Latin noun","meaning":"veil, covering cloth","meaningCN":"面纱；遮盖布"},{"word":"velare","structure":"Latin verb from velum","meaning":"to cover, veil","meaningCN":"覆盖；遮住"},{"word":"revelare","structure":"re- (undoing) + velare","meaning":"to unveil, disclose","meaningCN":"揭开；披露"}]}},{"word":"revision","ipa_uk":"/rɪˈvɪʒn/","ipa_us":"/rɪˈvɪʒən/","definition_zh":"修订；修改；复习；修订版；调整；复核；分类修订","definition_en":"the act of looking at something again in order to change, correct, or study it","core_image":"书桌上摊开的手稿边缘写满红笔批注，页角折起的地方夹着新写的一页。","scene":"编辑把手稿读了第二遍，在页边写下十几处修改意见，然后把改好的稿子交回作者。After a second reading, the editor marked a dozen changes and sent back a full revision of the manuscript.","sceneCN":"这里 revision 是“对文本的修订”（第 1 个义项）；句意：编辑通读后提出修改并交出修订稿。","pos":[{"tag":"n.","zh":"修订；修改；复习；修订版"}],"collocations":[{"phrase":"make revisions","zh":"作修改"},{"phrase":"a revised edition","zh":"修订版"},{"phrase":"exam revision","zh":"考试复习"},{"phrase":"under revision","zh":"修订中"},{"phrase":"a revision of policy","zh":"政策的调整"},{"phrase":"major revisions","zh":"重大修改"}],"forms":[{"label":"单数","form":"revision"},{"label":"复数","form":"revisions"},{"label":"动词形式","form":"revise"},{"label":"形容词形式","form":"revised"}],"derivatives":[{"word":"revise","pos":"v.","zh":"修改；复习"},{"word":"reviser","pos":"n.","zh":"修订者"},{"word":"revised","pos":"adj.","zh":"修订过的"},{"word":"revisionism","pos":"n.","zh":"修正主义"}],"senses":[{"no":"01","title":"Changing a text","titleCN":"修订：对文稿作增删改动","definition":"the act of altering and improving a piece of writing","definitionCN":"对一篇文字进行修改与改进的行为","example":"The manuscript went through four revisions before publication.","exampleCN":"这份手稿在出版前经过了四次修订。","why":"Revision comes from revisere, to look at again; only a second look can reveal what the first reading missed.","whyCN":"revision 出自 revisere“再看一次”；只有第二遍看，才能发现第一遍漏掉的东西。"},{"no":"02","title":"Studying for an exam","titleCN":"复习：为考试把学过的东西再看一遍","definition":"in British usage, the work of going over material again before an examination","definitionCN":"英式用法中指考试前把材料重新过一遍","example":"She spent the weekend on revision for the history paper.","exampleCN":"她整个周末都在复习历史试卷。","why":"The same second look serves two purposes: to correct a text, or to fix knowledge in memory.","whyCN":"同样的“再看一遍”有两个用途：改正文本，或把知识固定到记忆里。"},{"no":"03","title":"A changed version","titleCN":"修订版：改过之后的成品","definition":"a version of a document or work that has been altered from an earlier one","definitionCN":"由较早版本改动而来的文件或作品版本","example":"The second revision added a chapter on the postwar period.","exampleCN":"第二次修订版增加了一章战后时期的内容。","why":"The noun can name the product rather than the process, so revisions can be counted and compared.","whyCN":"这个名词可以命名成品而非过程，因此修订版能够被计数与比较。"},{"no":"04","title":"The act of re-examining","titleCN":"复核：把已有结论重新看一遍","definition":"the act of reviewing a decision, estimate, or record in order to correct it","definitionCN":"重新审视决定、估计或记录以便改正的行为","example":"The agency ordered a revision of its earlier figures.","exampleCN":"该机构下令复核先前的数字。","why":"The word's core is the second look, which may end in correction or in confirmation.","whyCN":"这个词的核心是第二遍审视，它可能以改正收尾，也可能以确认收尾。"},{"no":"05","title":"Amending a law or treaty","titleCN":"修订：对法律或条约作正式改动","definition":"a formal change to a law, constitution, or agreement","definitionCN":"对法律、宪法或协议的正式改动","example":"The revision of the treaty took three summit meetings.","exampleCN":"条约的修订开了三次峰会。","why":"Formal texts need recorded change, so revision becomes a procedure with dates and signatories.","whyCN":"正式文本需要可记录的变化，因此修订变成有日期与签署方的程序。"},{"no":"06","title":"Adjusting a plan or forecast","titleCN":"调整：对计划或预测作出修正","definition":"a change made to a plan, budget, or forecast in light of new information","definitionCN":"依据新信息对计划、预算或预测作出的改动","example":"The growth forecast underwent a sharp downward revision.","exampleCN":"增长预测被大幅下修。","why":"A plan is a guess about the future; revision is the correction that follows when the future disagrees.","whyCN":"计划是关于未来的猜测；修订就是未来提出异议之后的改正。"},{"no":"07","title":"Reclassifying living things","titleCN":"分类修订：重新划分物种与类群","definition":"in biology, a formal rearrangement of the classification of organisms","definitionCN":"生物学中对生物分类的正式重新安排","example":"The taxonomic revision split one genus into three.","exampleCN":"这次分类修订把一个属拆成三个属。","why":"New evidence forces old categories to be redrawn, and the work is called a revision of the group.","whyCN":"新证据迫使旧分类被重新划界，这项工作就叫对该类群的修订。"},{"no":"08","title":"A change of view","titleCN":"观念修正：对历史或理论的重新解释","definition":"a substantial change in how a historical event or theory is understood","definitionCN":"对历史事件或理论理解方式的实质性改变","example":"The discovery led to a revision of the standard account.","exampleCN":"这一发现导致对标准叙述的修正。","why":"Revisions of history are second looks at evidence, and they alter what a society believes happened.","whyCN":"历史修正就是对证据的第二遍审视，它会改变一个社会对“发生了什么”的认定。"}],"etymology":{"intro":{"en":"Revision is revise plus -ion. Revise comes from Latin revisere, to look at again, from re-, again, and visere, to visit or view.","cn":"revision 由 revise 加 -ion 构成。revise 出自拉丁语 revisere“再看一次”，由 re-“再一次”与 visere“观看、造访”组成。"},"items":[{"era":"LATIN videre","en":"Videre meant to see. Nearly every word in this family carries the idea of sight or inspection.","cn":"videre 意为看见。这一词族的词几乎都带着“看见、检视”的意思。"},{"era":"LATIN visere","en":"Visere was a frequentative of videre, meaning to look at repeatedly or to go to see a place.","cn":"visere 是 videre 的反复动词，意为反复看，或前往某地查看。"},{"era":"LATIN revisere","en":"Revisere added re-, again: to look at something a second time, or to visit a place again.","cn":"revisere 加上 re-“再一次”：第二次看某物，或再次造访某地。"},{"era":"FRENCH reviser","en":"Old French reviser kept both the sense of inspecting again and the sense of correcting a text.","cn":"古法语 reviser 兼有“再次检查”与“改正文本”两义。"},{"era":"ENGLISH revise","en":"English revise first meant to look over again, then to alter in order to improve.","cn":"英语 revise 最初指重新过目，后指为使内容更好而改动。"},{"era":"ENGLISH -ion","en":"The Latin suffix -ionem names the action or its result, so revision names both the second reading and the changed version.","cn":"拉丁后缀 -ionem 命名动作或其结果，因此 revision 既指第二遍审读，也指改动后的版本。"}]},"similar":{"note":{"en":"The first group is the revise family, separated by word class; the second compares words for changing, checking, and studying again.","cn":"第一组是 revise 词族，按词类区分；第二组比较表示改动、核对与重新学习的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"revise","ipa":"/rɪˈvaɪz/","tag":"verb","definition":"to alter a text, or to study again for an exam. It names the action.","definitionCN":"修改文本，或为考试重新学习；命名的是动作。"},{"word":"revision","ipa":"/rɪˈvɪʒn/","tag":"noun","definition":"the act or result of looking again and changing.","definitionCN":"重新审视并改动的行为或结果。"},{"word":"revisionism","ipa":"/rɪˈvɪʒənɪzəm/","tag":"noun","definition":"the reinterpretation of an established doctrine or historical account, often used critically.","definitionCN":"对既有学说或历史叙述的重新解释，常含批评意味。"},{"word":"revised","ipa":"/rɪˈvaɪzd/","tag":"adjective","definition":"having been altered and improved, as in a revised edition.","definitionCN":"已经修改改进的，如“修订版”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"edit","ipa":"/ˈedɪt/","tag":"verb or noun","definition":"to prepare text for publication by correcting and arranging it. It is part of revision, not its whole.","definitionCN":"通过校正与整理使文本可以出版；是修订的一部分，而非全部。"},{"word":"amendment","ipa":"/əˈmendmənt/","tag":"noun","definition":"a formal change to a law or document. It stresses the added correction rather than the second look.","definitionCN":"对法律或文件的正式改动；强调加入的改正，而非第二遍审视。"},{"word":"review","ipa":"/rɪˈvjuː/","tag":"noun or verb","definition":"a fresh examination or assessment. It may end without any change.","definitionCN":"重新检查或评估；可能不产生任何改动。"},{"word":"correction","ipa":"/kəˈrekʃn/","tag":"noun","definition":"the removal of an error. It is narrower than revision, which may also reorganize and improve.","definitionCN":"去除错误；比修订窄，修订还可能重组与改进。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: re- plus vision plus -ion. The base is videre, to see, so revision is a seeing again.","cn":"只用真实成分：re- 加 vision 再加 -ion。词基是 videre“看见”，所以 revision 就是再看一遍。"},"normal":[{"en":"Re plus vision plus ion: look at it again, then change what is wrong.","cn":"re 加 vision 加 ion：再看一遍，然后改掉不对的地方。"},{"en":"Four revisions means four second looks, each finding something new.","cn":"四次修订就是四次重看，每次都发现新东西。"},{"en":"Exam revision is the same second look, aimed at memory instead of paper.","cn":"考试复习是同一种重看，只是对准记忆而不是纸面。"},{"en":"A forecast revision is the future correcting the plan.","cn":"预测的调整，是未来在纠正计划。"},{"en":"A taxonomic revision redraws the family tree with new evidence.","cn":"分类修订用新证据重画那棵家族树。"}],"abstract":[{"en":"Revision admits that the first version was made by someone who had not yet read it.","cn":"修订承认：第一稿出自一个还没读过它的人之手。"},{"en":"Every history is a revision of an earlier history, and every revision will be revised.","cn":"每一部历史都是对更早历史的修正，而每次修正又将被修正。"},{"en":"The second look is where craft begins; the first look only produces material.","cn":"第二眼才是手艺的开始；第一眼只产出材料。"}]},"examples":[{"en":"The author's revision cut the opening chapter from forty pages to twelve.","cn":"作者的修订把开篇一章从四十页删到十二页。"},{"en":"The constitution requires a two-thirds vote for any revision.","cn":"宪法规定任何修订都需三分之二多数票。"},{"en":"The committee published a revision of the safety guidelines after the accident.","cn":"事故之后，委员会公布了安全指南的修订版。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（再）+ vision（看）——再看一遍并动手改，就是修订。","word":"revision"},"root":"由 revise（修订、复习）加 -ion（名词后缀）构成；revise 出自拉丁语 revisere“再看一次”，由 re-“再一次”与 visere“观看”组成，后者源自 videre“看见”，本义为“重新审视并作出改动的行为或结果”。","sensesIntro":{"en":"Eight senses of revision, all circling one idea: a second look that changes something. What is looked at again may be a manuscript, exam material, a finished version, a record, a law, a forecast, a biological classification, or a historical account.","cn":"revision 的八个义项都围绕一个观念：第二遍审视带来改动。被重新审视的可以是手稿、考试材料、成品版本、记录、法律、预测、生物分类，或历史叙述。"},"semanticMap":{"core":{"en":"CORE IMAGE: a manuscript on a desk, red notes in the margins, a newly written page tucked into a folded corner.","cn":"核心意象：桌上的手稿边缘写满红笔批注，折角里夹着新写的一页。"},"chain":["LATIN VIDERE = TO SEE","LATIN VISERE = TO LOOK AT","LATIN REVISERE = TO LOOK AGAIN","FRENCH REVISER = TO INSPECT AND CORRECT","ENGLISH REVISE = TO ALTER AFTER REVIEW","REVISION = THE SECOND LOOK AND ITS CHANGES"],"branches":[{"senses":"S1 · S2","en":"TWO KINDS OF SECOND LOOK: improving a text, and fixing knowledge for an exam.","cn":"两种第二眼：改进文本，与为考试固定知识。"},{"senses":"S3 · S4","en":"THE RESULT AND THE REVIEW: a changed version, and a re-examination that may only confirm.","cn":"结果与复核：改动后的版本，以及可能只作确认的重新审视。"},{"senses":"S5 · S6","en":"FORMAL AND FORWARD-LOOKING CHANGE: amending a law, and correcting a forecast.","cn":"正式与面向未来的改动：修订法律，以及修正预测。"},{"senses":"S7","en":"REDRAWING CATEGORIES: a biological reclassification forced by new evidence.","cn":"重画分类：新证据迫使生物分类重新安排。"},{"senses":"S8","en":"REWRITING THE PAST: a changed account of what happened.","cn":"重写过去：对“发生了什么”的叙述被改变。"}]},"affixes":{"intro":{"en":"Revision is revise plus -ion. The family includes reviser and revisionism, with -er marking the person and -ism marking a doctrine of reinterpretation.","cn":"revision 由 revise 加 -ion 构成。词族包括 reviser 与 revisionism，其中 -er 标记人，-ism 标记一种重新解释的主张。"},"latinIntro":{"en":"The Latin layers are videre, visere, and revisere. The suffix -ion comes through French from Latin -ionem.","cn":"拉丁层次是 videre、visere 与 revisere。后缀 -ion 经法语来自拉丁语 -ionem。"},"items":[{"word":"videre","structure":"Latin verb (to see)","meaning":"to see, perceive","meaningCN":"看见；感知","example":"The root appears in video, vision, and evident.","exampleCN":"这个词根出现在 video（录像）、vision（视觉）与 evident（明显的）中。"},{"word":"visere","structure":"Frequentative of videre","meaning":"to look at repeatedly, to visit","meaningCN":"反复看；造访","example":"The verb described going to inspect a site.","exampleCN":"这个动词可描述前往查看某地。"},{"word":"revise","structure":"Latin revisere through French reviser","meaning":"to look over again and correct","meaningCN":"重新过目并改正","example":"Revise the draft before you send it.","exampleCN":"寄出之前先把草稿改一遍。"},{"word":"revision","structure":"revise + -ion (action or result)","meaning":"the second look, or the changed version","meaningCN":"第二遍审视；修订版","example":"The paper is under revision after peer review.","exampleCN":"论文在同行评议后处于修订中。"},{"word":"reviser","structure":"revise + -er (person)","meaning":"a person who revises a text","meaningCN":"修订者","example":"The reviser checked every date against the archive.","exampleCN":"修订者对照档案核对了每个日期。"},{"word":"revisionism","structure":"revision + -ism (doctrine)","meaning":"the reinterpretation of an established account, often used as a criticism","meaningCN":"对既定叙述的重新解释，常作贬义","example":"Critics labelled the book revisionism.","exampleCN":"批评者把这本书称为修正主义。"},{"word":"revisionist","structure":"revision + -ist (person)","meaning":"a person who reinterprets an established account","meaningCN":"主张重新解释既定叙述的人","example":"Revisionists argued that the battle was smaller than claimed.","exampleCN":"修正派主张那场战役的规模没有宣称的那么大。"},{"word":"revised","structure":"revise + -ed (past participle)","meaning":"having been changed and improved","meaningCN":"已修订的","example":"The revised plan cut the budget by a fifth.","exampleCN":"修订后的方案削减了五分之一预算。"},{"word":"unrevised","structure":"un- (not) + revised","meaning":"not yet changed","meaningCN":"未修订的","example":"The unrevised text still contains the old figures.","exampleCN":"未修订的文本仍含旧数据。"}],"latinEntries":[{"word":"videre","structure":"Latin verb","meaning":"to see","meaningCN":"看见"},{"word":"visere","structure":"Latin frequentative verb","meaning":"to look at repeatedly, visit","meaningCN":"反复看；造访"},{"word":"revisere","structure":"re- + visere","meaning":"to look at again","meaningCN":"再看一次"}]}},{"word":"revolutionary","ipa_uk":"/ˌrevəˈluːʃənəri/","ipa_us":"/ˌrevəˈluːʃəneri/","definition_zh":"革命的；革命性的；革命者；颠覆性的；革新性的；公转的","definition_en":"relating to a complete change in a political system, or to any change that overturns established ways","core_image":"广场上的旧铜像被绳索拉倒，底座上残留的铭文被人用白灰写上新日期。","scene":"历史课本里，那座旧王朝的铜像在广场上被拉倒，第二年同一位置立起了完全不同的纪念物。The bronze statue was pulled down, a revolutionary act that ended the old dynasty's rule.","sceneCN":"这里 revolutionary 是“政治革命的”（第 1 个义项）；句意：铜像被拉倒，标志着旧政权的革命性更替。","pos":[{"tag":"adj.","zh":"革命的；革命性的；颠覆性的"},{"tag":"n.","zh":"革命者"}],"collocations":[{"phrase":"revolutionary war","zh":"革命战争"},{"phrase":"a revolutionary idea","zh":"革命性的想法"},{"phrase":"revolutionary change","zh":"根本性的变革"},{"phrase":"revolutionary movement","zh":"革命运动"},{"phrase":"a revolutionary leader","zh":"革命领袖"},{"phrase":"revolutionary technology","zh":"颠覆性技术"}],"forms":[{"label":"原级（形容词）","form":"revolutionary"},{"label":"比较级（用 more）","form":"more revolutionary"},{"label":"最高级（用 most）","form":"most revolutionary"},{"label":"复数（名词）","form":"revolutionaries"},{"label":"名词形式","form":"revolution"}],"derivatives":[{"word":"revolution","pos":"n.","zh":"革命；旋转；公转"},{"word":"revolutionize","pos":"v.","zh":"彻底改变；使革命化"},{"word":"revolutionaries","pos":"n.","zh":"革命者们"},{"word":"counter-revolutionary","pos":"adj./n.","zh":"反革命的；反革命者"}],"senses":[{"no":"01","title":"To do with political revolution","titleCN":"革命的：与政权更替有关","definition":"relating to the overthrow of a government or social order and its replacement","definitionCN":"与推翻政府或社会秩序并以新秩序取代有关","example":"The revolutionary government abolished the old titles within a year.","exampleCN":"革命政府一年内废除了旧爵位。","why":"Revolution comes from revolvere, to roll back; a political revolution rolls the old order over and puts another in its place.","whyCN":"revolution 出自 revolvere“滚回”；政治革命把旧秩序翻倒，把另一套放上去。"},{"no":"02","title":"A complete overturning","titleCN":"革命性的：彻底改变做事方式","definition":"causing a complete and fundamental change in methods, ideas, or conditions","definitionCN":"使方法、观念或状况发生彻底根本的改变","example":"The printing press had a revolutionary effect on reading.","exampleCN":"印刷机对阅读产生了革命性的影响。","why":"The adjective widens beyond politics: any practice turned over from its base counts as revolutionary.","whyCN":"这个形容词越出政治范围：任何从根基上被翻过来的做法都算革命性的。"},{"no":"03","title":"A person who makes revolution","titleCN":"革命者：参与推翻旧秩序的人","definition":"a person who takes part in or supports a revolution","definitionCN":"参与或支持革命的人","example":"The revolutionaries met in a print shop to avoid the police.","exampleCN":"革命者在一家印刷店碰头以躲避警察。","why":"The -ary suffix forms a person noun from the adjective, naming those who carry the overturning through.","whyCN":"后缀 -ary 由形容词构成指人名词，命名把这场翻覆推行到底的人。"},{"no":"04","title":"Of a revolutionary party","titleCN":"革命派的：属于革命组织或阵营","definition":"belonging to or characteristic of a movement that seeks revolution","definitionCN":"属于或具有寻求革命的运动特征","example":"The revolutionary committee took over the railway station.","exampleCN":"革命委员会接管了火车站。","why":"Here the adjective labels an organization rather than an act, binding a group to the project of overturning.","whyCN":"这里形容词标记的是一个组织而非一次行动，把某个团体绑在“翻覆”这一事业上。"},{"no":"05","title":"Science that breaks a framework","titleCN":"颠覆性的：让旧范式失效的科学与技术","definition":"describing an advance that makes an established framework obsolete","definitionCN":"描述使既有框架过时的进展","example":"Plate tectonics was revolutionary for geology.","exampleCN":"板块构造学说对地质学是颠覆性的。","why":"A scientific revolution replaces the questions a field is able to ask, not merely its answers.","whyCN":"科学革命替换的是一个领域能够提出的问题，而不只是它的答案。"},{"no":"06","title":"Of orbital motion","titleCN":"公转的：天体绕行一周的运动","definition":"relating to the orbiting motion of a body around another","definitionCN":"与天体绕另一天体运行一周的运动有关","example":"The planet's revolutionary period is about eleven years.","exampleCN":"这颗行星的公转周期约为十一年。","why":"This is the oldest sense of revolution as a turning round; the adjective simply marks motion in an orbit.","whyCN":"这是 revolution 最古老的“转一圈”义；形容词只是标记轨道上的运动。"},{"no":"07","title":"Art that breaks the rules","titleCN":"革新性的：艺术上推翻旧规范","definition":"describing art or design that rejects established conventions","definitionCN":"描述推翻既有规范的艺术或设计","example":"The revolutionary staging replaced scenery with bare scaffolding.","exampleCN":"那次革新性的舞台设计用裸露的脚手架取代了布景。","why":"Aesthetic revolutions are fought over form; the same word is lent to whoever wins the argument about rules.","whyCN":"审美革命争夺的是形式；这个词被借给在规则之争中胜出的一方。"},{"no":"08","title":"Of a period of upheaval","titleCN":"革命时期的：属于历史剧变年代的","definition":"belonging to the historical period in which a revolution takes place","definitionCN":"属于革命发生的那段历史时期","example":"Revolutionary Paris banned church bells for a time.","exampleCN":"革命时期的巴黎一度禁止教堂敲钟。","why":"The adjective can date a whole era, so objects, clothes, and songs become revolutionary by belonging to those years.","whyCN":"这个形容词可以给整个时代断代，于是器物、服装与歌曲都因属于那些年份而带上“革命时期”的标记。"}],"etymology":{"intro":{"en":"Revolutionary is revolution plus -ary. Revolution comes from Latin revolutio, a rolling back, from revolvere, from re-, back, and volvere, to roll.","cn":"revolutionary 由 revolution 加 -ary 构成。revolution 出自拉丁语 revolutio“滚回”，其动词 revolvere 由 re-“向后”与 volvere“滚动”组成。"},"items":[{"era":"LATIN volvere","en":"Volvere meant to roll or turn over. The root also gives revolve, volume, and involved.","cn":"volvere 意为滚动、翻转。这个词根也给出 revolve、volume 与 involved。"},{"era":"LATIN revolvere","en":"Revolvere added re-, back: to roll back, unroll, or turn over again.","cn":"revolvere 加上 re-“向后”：滚回、展开、再次翻转。"},{"era":"LATIN revolutio","en":"Revolutio named a turning round or a rolling back, and was used for the return of a heavenly body to a starting point.","cn":"revolutio 指转一圈或滚回，也曾用于天体回到起点的运行。"},{"era":"ENGLISH revolution","en":"English revolution kept the astronomical sense of orbiting, then took on the political sense of an overturned order in the seventeenth century.","cn":"英语 revolution 保留天体公转义，随后在十七世纪获得“秩序被翻覆”的政治义。"},{"era":"ENGLISH -ary","en":"The Latin suffix -arius forms adjectives of belonging and also person nouns, so revolutionary can describe a change or name a person.","cn":"拉丁后缀 -arius 既构成表所属的形容词，也构成指人名词，因此 revolutionary 既能描述变革，也能指人。"},{"era":"ENGLISH revolutionary (17th c.)","en":"Revolutionary first applied to things belonging to a turn of events, then to supporters of political overthrow, and later to any radical novelty.","cn":"revolutionary 先指属于某次事变的事物，后指政治翻覆的支持者，再后来指任何激进的新事物。"}]},"similar":{"note":{"en":"The first group is the revolution family, separated by word class; the second compares words for radical change, novelty, and political upheaval.","cn":"第一组是 revolution 词族，按词类区分；第二组比较表示根本变革、新奇与政治剧变的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"revolution","ipa":"/ˌrevəˈluːʃn/","tag":"noun","definition":"a complete turn of a system, or one orbit of a body. It names the event.","definitionCN":"制度的彻底翻转，或天体运行一周；命名的是事件。"},{"word":"revolutionary","ipa":"/ˌrevəˈluːʃənəri/","tag":"adjective or noun","definition":"relating to such an overturning, or a person who works for it.","definitionCN":"与这种翻覆有关的；或指为它效力的人。"},{"word":"revolutionize","ipa":"/ˌrevəˈluːʃənaɪz/","tag":"verb","definition":"to change something completely.","definitionCN":"彻底改变某事物。"},{"word":"revolve","ipa":"/rɪˈvɒlv/","tag":"verb","definition":"to move in a circle around a centre. It keeps only the physical sense.","definitionCN":"绕中心做圆周运动；只保留物理义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"radical","ipa":"/ˈrædɪkl/","tag":"adjective","definition":"going to the root of a problem and favouring thorough change. It stresses depth rather than overthrow.","definitionCN":"直抵问题根源、主张彻底改变；强调深度而非推翻。"},{"word":"subversive","ipa":"/səbˈvɜːsɪv/","tag":"adjective","definition":"intended to undermine an established authority or system. It stresses hidden undermining.","definitionCN":"意图暗中削弱既有权威或制度；强调隐蔽破坏。"},{"word":"groundbreaking","ipa":"/ˈɡraʊndbreɪkɪŋ/","tag":"adjective","definition":"new and pioneering, especially in research or art. It stresses novelty rather than political change.","definitionCN":"新颖且具开创性，尤用于研究或艺术；强调新意而非政治变革。"},{"word":"upheaval","ipa":"/ʌpˈhiːvl/","tag":"noun","definition":"a violent or large-scale change causing disorder. It names the disruption rather than the ideology.","definitionCN":"造成动荡的剧烈或大规模变化；命名的是混乱，而非意识形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: revolution plus -ary. The base volvere means to roll, so a revolutionary change rolls the old order over.","cn":"只用真实成分：revolution 加 -ary。词基 volvere 意为滚动，所以革命性的变化就是把旧秩序滚翻。"},"normal":[{"en":"Re plus volve plus ary: rolled back, then given an adjective or a person.","cn":"re 加 volve 加 ary：被滚回去，再变成形容词或指人。"},{"en":"A pulled-down statue is a revolution you can photograph.","cn":"被拉倒的铜像，是一场可以拍下来的革命。"},{"en":"The printing press did not change a government; it changed what reading was.","cn":"印刷机没有更换政府，它改变了“阅读”本身。"},{"en":"Plate tectonics was revolutionary because old questions stopped making sense.","cn":"板块构造学说之所以颠覆，是因为旧问题不再成立。"},{"en":"A planet's revolutionary period is simply the time of one orbit.","cn":"行星的公转周期，就是绕行一圈的时间。"}],"abstract":[{"en":"Every revolution promises an end and delivers a new beginning with its own costs.","cn":"每次革命都许诺一个终点，交出的却是一个带着自身代价的新开始。"},{"en":"The word is always spoken from one side: one person's reform is another's upheaval.","cn":"这个词总是从某一方的角度说出：此方的改良，是彼方的动荡。"},{"en":"Radical novelty is judged later; at the moment it appears, it mostly looks like an error.","cn":"激进的新事物要事后才被评判；它刚出现时，多半像个错误。"}]},"examples":[{"en":"The revolutionary government rewrote the calendar and renamed the months.","cn":"革命政府重写历法，并重新给月份命名。"},{"en":"Cheap sequencing has been revolutionary for the study of evolution.","cn":"廉价的测序技术对进化研究具有革命性意义。"},{"en":"As a young revolutionary, he printed pamphlets on a hand press.","cn":"作为年轻的革命者，他用一台手摇印刷机印小册子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"re（回）+ volution（滚动）——把旧秩序滚回去，就是革命。","word":"revolutionary"},"root":"由 revolution（革命、旋转）加 -ary（属于……的；……的人）构成；revolution 出自拉丁语 revolutio“滚回”，其动词 revolvere 由 re-“向后”与 volvere“滚动”组成，本义为“把旧秩序整个翻覆过来的，或从事这种翻覆的人”。","sensesIntro":{"en":"Eight senses of revolutionary, all circling one idea: something is rolled over from its base. What is overturned may be a government, a method, a movement, a scientific framework, an orbit, a set of artistic rules, or a whole historical period.","cn":"revolutionary 的八个义项都围绕一个观念：某物从根基上被翻覆。被翻覆的可以是政府、方法、运动、科学框架、天体轨道、艺术规范，或整个历史时期。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bronze statue pulled down by ropes in a square, a new date chalked on the empty pedestal.","cn":"核心意象：广场上的铜像被绳索拉倒，空基座上用白灰写上新日期。"},"chain":["LATIN VOLVERE = TO ROLL","LATIN REVOLVERE = TO ROLL BACK","LATIN REVOLUTIO = A TURNING ROUND","ENGLISH REVOLUTION = OVERTURNED ORDER","SUFFIX -ARY = BELONGING TO","REVOLUTIONARY = OF THE OVERTURNING"],"branches":[{"senses":"S1 · S4 · S8","en":"POLITICS AND ITS PERIOD: a toppled government, the party that did it, and the years that carry its name.","cn":"政治及其年代：被推翻的政府、动手的派别，以及带上其名字的那些年份。"},{"senses":"S2 · S7","en":"OVERTURNING PRACTICE AND FORM: a new method in general, and a new set of rules in art.","cn":"翻覆做法与形式：一般意义上的新方法，以及艺术中的新规范。"},{"senses":"S3","en":"THE PERSON: someone who carries the overturning through.","cn":"人：把这场翻覆推行到底的人。"},{"senses":"S5","en":"A FRAMEWORK MADE OBSOLETE: science that replaces the questions a field can ask.","cn":"框架过时：替换一个领域所能提出问题的科学。"},{"senses":"S6","en":"THE OLD ASTRONOMICAL SENSE: one body rolling round another.","cn":"古老的天文义：一个天体绕另一个滚行一周。"}]},"affixes":{"intro":{"en":"Revolutionary is revolution plus -ary. The family includes revolutionize, revolutionaries, and counter-revolutionary, with -ize marking the act and counter- marking opposition.","cn":"revolutionary 由 revolution 加 -ary 构成。词族包括 revolutionize、revolutionaries 与 counter-revolutionary，其中 -ize 标记动作，counter- 标记对立。"},"latinIntro":{"en":"The Latin layers are volvere and revolvere, with the noun revolutio. The suffix -ary comes from Latin -arius.","cn":"拉丁层次是 volvere 与 revolvere，以及名词 revolutio。后缀 -ary 出自拉丁语 -arius。"},"items":[{"word":"volvere","structure":"Latin verb (to roll)","meaning":"to roll, turn over","meaningCN":"滚动；翻转","example":"The root appears in revolve, volume, and convoluted.","exampleCN":"这个词根出现在 revolve（旋转）、volume（卷册）与 convoluted（盘绕的）中。"},{"word":"revolvere","structure":"re- (back) + volvere (to roll)","meaning":"to roll back, unroll","meaningCN":"滚回；展开","example":"The Latin verb described a scroll being unrolled.","exampleCN":"这个拉丁动词可描述卷轴被展开。"},{"word":"revolution","structure":"Latin revolutio through French","meaning":"a turning round, or an overturned order","meaningCN":"转一圈；被翻覆的秩序","example":"The revolution began with a tax on bread.","exampleCN":"这场革命始于对面包征税。"},{"word":"revolutionary","structure":"revolution + -ary (belonging to)","meaning":"of an overturning, or a person who works for one","meaningCN":"革命的；革命者","example":"Revolutionary ideas spread through cheap pamphlets.","exampleCN":"革命思想通过廉价小册子传播。"},{"word":"revolutionize","structure":"revolution + -ize (to make)","meaning":"to change something completely","meaningCN":"彻底改变","example":"The internet revolutionized how archives are searched.","exampleCN":"互联网彻底改变了检索档案的方式。"},{"word":"revolutionaries","structure":"revolutionary + -es (plural noun)","meaning":"more than one person working for revolution","meaningCN":"多名革命者","example":"The revolutionaries disagreed about what came next.","exampleCN":"革命者们对下一步该怎么办意见不一。"},{"word":"counter-revolutionary","structure":"counter- (against) + revolutionary","meaning":"opposing a revolution or its aims","meaningCN":"反革命的；反对革命目标的","example":"Counter-revolutionary pamphlets were banned.","exampleCN":"反革命小册子被查禁。"},{"word":"pre-revolutionary","structure":"pre- (before) + revolutionary","meaning":"belonging to the period before a revolution","meaningCN":"革命前的","example":"Pre-revolutionary buildings still line the square.","exampleCN":"革命前的建筑仍排列在广场两侧。"},{"word":"revolutionist","structure":"revolution + -ist (person)","meaning":"a person who advocates revolution","meaningCN":"主张革命的人","example":"Revolutionists wanted the assembly dissolved.","exampleCN":"革命派希望解散议会。"}],"latinEntries":[{"word":"volvere","structure":"Latin verb","meaning":"to roll, turn","meaningCN":"滚动；转动"},{"word":"revolvere","structure":"re- + volvere","meaning":"to roll back, unroll","meaningCN":"滚回；展开"},{"word":"revolutio","structure":"Latin noun from revolvere","meaning":"a turning round","meaningCN":"转一圈；旋转"}]}}]);
